('essay', 1, 'اكتب قانون جيب التمام في المتجهات، ووضّح مدلول كل رمز فيه، ثم عبّر عنه بالكلمات.', null, null, null, 'تذكر', 'كتابة قانون وشرح رموزه', 'متوسط', 'الكتاب ص 133 — قانون جيب التمام في المتجهات'),
('essay', 2, 'باستعمال قانون جيب التمام في المتجهات، بيّن ما يؤول إليه مقدار المحصلة $R$ عندما تكون الزاوية $\theta$ بين المتجهين في مثلث الجمع: (أ) $90^\circ$، (ب) $180^\circ$، (ج) $0^\circ$. وفسّر كل نتيجة بوصف وضع المتجهين.', null, null, null, 'فهم', 'تفسير حالات خاصة', 'صعب', 'الكتاب ص 155 — دليل مراجعة الفصل: قانونا جيب التمام والجيب'),
('essay', 3, 'يبين الشكل الآتي متجهين $\boldsymbol{P}$ و$\boldsymbol{Q}$ وُضع ذيل $\boldsymbol{Q}$ عند رأس $\boldsymbol{P}$، ومحصلتهما $\boldsymbol{S}$ (الخط المتقطع)، والزاوية بينهما $\varphi$. (أ) اكتب قانون جيب التمام لإيجاد مقدار $\boldsymbol{S}$ بدلالة رموز الشكل. (ب) احسب $S$ إذا كان $P = 12.0\ \text{N}$ و$Q = 7.5\ \text{N}$ و$\varphi = 115.0^\circ$.', null, '[{"src":"qimg/phys1/c5l1-o02-pqs.svg","alt":"سهم أزرق P يتجه من أسفل اليسار إلى اليمين صاعدًا قليلًا، ومن رأسه سهم أزرق Q يتجه إلى أعلى، وسهم متقطع S من ذيل P إلى رأس Q. عند التقاء رأس P بذيل Q قوس للزاوية الداخلية بين P وQ مكتوب عنده φ."}]'::jsonb, null, 'تطبيق', 'كتابة قانون وتطبيقه', 'صعب', 'الكتاب ص 133 — قانون جيب التمام في المتجهات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C5-L1-O02') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'قانون جيب التمام في المتجهات: $R^2 = A^2 + B^2 - 2AB\cos\theta$، حيث $\theta$ الزاوية بين المتجهين عند وضع ذيل أحدهما عند رأس الآخر، أي الزاوية المقابلة للمحصلة في مثلث الجمع.', '["هذه نظرية فيثاغورس، وهي حالة خاصة تصح فقط عندما تكون الزاوية بين المتجهين $90^\\circ$.","","استُعمل جيب الزاوية بدل جيب تمامها؛ والقانون يتضمن $\\cos\\theta$.","حُذفت التربيعات؛ فالقانون يربط مربع مقدار المحصلة بمربعي مقداري المتجهين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-20T17:53:29.914Z"}'::jsonb),
('mcq', 2, 3, 'العلاقة التي تحوي جيب تمام الزاوية بين المتجهين وتعطي مربع مقدار المحصلة هي قانون جيب التمام في المتجهات.', '["قانون الجيب نسب: $\\frac{R}{\\sin\\theta} = \\frac{A}{\\sin a} = \\frac{B}{\\sin b}$، ولا يتضمن مربعات المقادير.","نظرية فيثاغورس $R^2 = A^2 + B^2$ لا تحوي الحد $2AB\\cos\\theta$.","زاوية المتجه المحصل تُحسب بالعلاقة $\\theta = \\tan^{-1}\\left(\\frac{R_y}{R_x}\\right)$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-20T17:53:29.914Z"}'::jsonb),
('mcq', 3, 0, 'الحد المطروح في $R^2 = A^2 + B^2 - 2AB\cos\theta$ هو $2AB\cos\theta$: ضعف حاصل ضرب مقداري المتجهين مضروبًا في جيب تمام الزاوية بينهما.', '["","نقص العدد 2؛ فالحد المطروح هو $2AB\\cos\\theta$ لا $AB\\cos\\theta$.","الحد المطروح يحوي جيب تمام الزاوية $\\cos\\theta$ لا جيبها.","الحد المطروح فيه حاصل ضرب المقدارين $AB$ لا مجموعهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-20T17:53:29.914Z"}'::jsonb),
('mcq', 4, 2, 'في $R^2 = A^2 + B^2 - 2AB\cos\theta$ تكون $\theta$ الزاوية المحصورة بين المتجهين $\boldsymbol{A}$ و$\boldsymbol{B}$، وهي الزاوية المقابلة للضلع $\boldsymbol{R}$ في مثلث الجمع، أي الزاوية 2.', '["الزاوية 1 محصورة بين $\\boldsymbol{A}$ و$\\boldsymbol{R}$ وتقابل الضلع $\\boldsymbol{B}$؛ فهي تُستعمل في قانون الجيب لا لحساب R بقانون جيب التمام.","الزاوية 3 محصورة بين $\\boldsymbol{B}$ و$\\boldsymbol{R}$ وتقابل الضلع $\\boldsymbol{A}$، وليست الزاوية بين المتجهين المجموعين.","","هذه تحدد اتجاه المحصلة، ولا تظهر في قانون جيب التمام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-20T17:53:29.915Z"}'::jsonb),
('mcq', 5, 3, '$R$ هو مقدار المتجه المحصل $\boldsymbol{R}$ الناتج من جمع $\boldsymbol{A}$ و$\boldsymbol{B}$، و$A$ و$B$ مقدارا المتجهين.', '["مقدار المحصلة لا يساوي مجموع المقدارين إلا إذا كان المتجهان في الاتجاه نفسه.","المركّبة الأفقية $R_x$ جزء من المحصلة، والقانون يعطي مقدار المحصلة كاملًا.","R مقدار متجه جديد هو المحصلة، وليس أحد المتجهين المجموعين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-20T17:53:29.915Z"}'::jsonb),
('mcq', 6, 1, '$\cos 90^\circ = 0$، فيصبح الحد $2AB\cos\theta$ صفرًا، ويؤول القانون إلى نظرية فيثاغورس $R^2 = A^2 + B^2$.', '["$\\cos 90^\\circ = 0$ لا 1، والمحصلة لا تساوي مجموع المقدارين للمتجهين المتعامدين.","","$\\cos 90^\\circ = 0$، فيختفي الحد $2AB\\cos\\theta$ كاملًا.","$\\cos 90^\\circ = 0$، وجيب التمام يساوي $-1$ عند $180^\\circ$ لا عند $90^\\circ$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-20T17:53:29.915Z"}'::jsonb),
('mcq', 7, 0, '$A$ و$B$ مقدارا المتجهين $\boldsymbol{A}$ و$\boldsymbol{B}$ اللذين نجمعهما، و$R$ مقدار محصلتهما، و$\theta$ الزاوية بينهما.', '["","مركّبتا المحصلة هما $R_x$ و$R_y$، وهما لا تظهران في قانون جيب التمام.","الزاويتان المقابلتان هما $a$ و$b$ في قانون الجيب، و$A$ و$B$ أطوال لا زوايا.","مقدار المحصلة هو $R$ في الطرف الأيسر، أما $A$ و$B$ فهما المتجهان المجموعان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-20T17:53:29.916Z"}'::jsonb),
('essay', 1, null::int, null, null, '$R^2 = A^2 + B^2 - 2AB\cos\theta$؛ حيث $R$ مقدار المتجه المحصل، و$A$ و$B$ مقدارا المتجهين المجموعين، و$\theta$ الزاوية بين المتجهين عند وضع ذيل أحدهما عند رأس الآخر (الزاوية المقابلة للمحصلة في مثلث الجمع). وبالكلمات: مربع مقدار المتجه المحصل يساوي مجموع مربعي مقداري المتجهين مطروحًا منه ضعف حاصل ضرب مقداري المتجهين مضروبًا في جيب تمام الزاوية التي بينهما.', '["كتابة القانون صحيحًا","مدلول $R$ و$A$ و$B$ و$\\theta$","الصياغة اللفظية"]'::jsonb, '[]'::jsonb, '[{"element":"كتابة القانون","marks":1},{"element":"مدلول الرموز","marks":1},{"element":"الصياغة اللفظية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"درجتان","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة $\\sin\\theta$ بدل $\\cos\\theta$","نسيان العدد 2 في الحد الأخير","عدّ $R$ مجموع المقدارين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-20T17:53:29.916Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $\cos 90^\circ = 0$ ⇐ $R^2 = A^2 + B^2$، أي نظرية فيثاغورس؛ والمتجهان متعامدان. (ب) $\cos 180^\circ = -1$ ⇐ $R^2 = A^2 + B^2 + 2AB = (A + B)^2$ ⇐ $R = A + B$؛ فالمتجه $\boldsymbol{B}$ يكمل في اتجاه $\boldsymbol{A}$ نفسه فتجمع المقادير. (ج) $\cos 0^\circ = 1$ ⇐ $R^2 = (A - B)^2$ ⇐ $R$ يساوي الفرق بين المقدارين؛ فالمتجه $\boldsymbol{B}$ يرتد على $\boldsymbol{A}$ في الاتجاه المعاكس.', '["الحالة $90^\\circ$: فيثاغورس","الحالة $180^\\circ$: $R = A + B$ مع التفسير","الحالة $0^\\circ$: $R$ يساوي الفرق مع التفسير","استعمال قيم جيب التمام $0$ و$-1$ و$1$ صحيحة"]'::jsonb, '["$\\cos 90^\\circ = 0$ ⇐ $R^2 = A^2 + B^2$","$\\cos 180^\\circ = -1$ ⇐ $R^2 = (A + B)^2$","$\\cos 0^\\circ = 1$ ⇐ $R^2 = (A - B)^2$"]'::jsonb, '[{"element":"الحالة $90^\\circ$","marks":1},{"element":"الحالة $180^\\circ$ وتفسيرها","marks":1},{"element":"الحالة $0^\\circ$ وتفسيرها","marks":1},{"element":"قيم جيب التمام الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجتان","description":"عنصران صحيحان فقط أو طريقة صحيحة مع أخطاء متعددة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الزاوية في مثلث الجمع والزاوية بين ذيلي المتجهين فتنعكس نتيجتا (ب) و(ج)","عدّ $\\cos 180^\\circ = 0$","كتابة $R = A^2 + B^2$ دون جذر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-20T17:53:29.916Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $S^2 = P^2 + Q^2 - 2PQ\cos\varphi$. (ب) $S^2 = (12.0)^2 + (7.5)^2 - 2(12.0)(7.5)\cos 115.0^\circ = 144 + 56.25 + 76.1 = 276\ \text{N}^2$، إذن $S = 16.6\ \text{N}$.', '["كتابة القانون برموز الشكل","التعويض الصحيح مع إشارة جيب التمام","S = 16.6 N"]'::jsonb, '["$S^2 = P^2 + Q^2 - 2PQ\\cos\\varphi$","$\\cos 115.0^\\circ = -0.423$ فيصبح الحد الأخير موجبًا","$S^2 = 276\\ \\text{N}^2$ ⇐ $S = 16.6\\ \\text{N}$"]'::jsonb, '[{"element":"كتابة القانون برموز الشكل","marks":1},{"element":"التعويض مع الإشارة الصحيحة","marks":1},{"element":"الناتج 16.6 N بالوحدة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"درجتان","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة القانون بالرموز A وB وR دون ربطها برموز الشكل","إهمال إشارة $\\cos 115.0^\\circ$ السالبة فينتج 11.1 N","ضبط الآلة الحاسبة على الراديان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-20T17:53:29.916Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C5-L1-O02') and x.type = v.type and x.number = v.number
