insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C5-L1-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'سار طالب 3.0 km شرقًا، ثم 4.0 km شمالًا. أيّ الطرائق الآتية أنسب لحساب مقدار إزاحته المحصلة مباشرة؟', null, null, '["قانون جيب التمام؛ لأن الزاوية بين الإزاحتين لا تساوي $90^\\circ$","الجمع العددي للمقدارين؛ لأن الإزاحتين متتاليتان","قانون الجيب؛ لأن المثلث فيه زاوية قائمة","نظرية فيثاغورس؛ لأن الزاوية بين الإزاحتين $90^\\circ$"]'::jsonb, 'فهم', 'اختيار الطريقة المناسبة', 'سهل', 'الكتاب ص 132 — متى تُستعمل نظرية فيثاغورس وقانونا جيب التمام والجيب'),
('mcq', 2, 'قوتان تؤثران في جسم، والزاوية بينهما في مثلث الجمع (بعد وضع ذيل إحداهما عند رأس الأخرى) $120^\circ$. أيّ علاقة تُستعمل لحساب مقدار محصلتهما؟', null, null, '["نظرية فيثاغورس $R^2 = A^2 + B^2$","قانون جيب التمام $R^2 = A^2 + B^2 - 2AB\\cos\\theta$","الجمع العددي للمقدارين $R = A + B$","علاقة زاوية المحصلة $\\theta = \\tan^{-1}\\left(\\frac{R_y}{R_x}\\right)$"]'::jsonb, 'فهم', 'اختيار القانون المناسب', 'سهل', 'الكتاب ص 132 — متى تُستعمل نظرية فيثاغورس وقانونا جيب التمام والجيب'),
('mcq', 3, 'يبين الشكل الآتي أربعة رسوم على شبكة مربعات، في كل منها متجهان $\boldsymbol{A}$ و$\boldsymbol{B}$ وُضع ذيل $\boldsymbol{B}$ عند رأس $\boldsymbol{A}$. في أيّ رسم يمكن حساب مقدار المحصلة مباشرة بنظرية فيثاغورس؟', null, '[{"src":"qimg/phys1/c5l1-o03-pairs.svg","alt":"أربعة رسوم متجاورة على شبكة مربعات معنونة الرسم 1 إلى الرسم 4. في كل رسم سهم أزرق A وسهم أزرق B يبدأ من رأس A. الرسم 1: A أفقي إلى اليمين وB مائل إلى أعلى اليمين. الرسم 2: A أفقي إلى اليمين وB رأسي إلى أعلى على خط الشبكة. الرسم 3: A أفقي إلى اليمين وB مائل إلى أعلى اليسار. الرسم 4: A مائل إلى أعلى اليمين وB مائل إلى أعلى اليسار. لا تظهر المحصلة ولا الزوايا."}]'::jsonb, '["الرسم 2","الرسم 1","الرسم 3","الرسم 4"]'::jsonb, 'فهم', 'تمييز حالة التعامد من الرسم', 'متوسط', 'الكتاب ص 132 — متى تُستعمل نظرية فيثاغورس وقانونا جيب التمام والجيب'),
('mcq', 4, 'استعمل طالب نظرية فيثاغورس لحساب محصلة قوتين مقداراهما 5.0 N و7.0 N، والزاوية بينهما في مثلث الجمع $60^\circ$. ما الخطأ في طريقته؟', null, null, '["نظرية فيثاغورس تصح للإزاحات فقط ولا تصح للقوى","كان عليه جمع المقدارين مباشرة لأن الزاوية حادة","فيثاغورس تصح فقط إذا كان المتجهان متعامدين","كان عليه طرح المقدارين لأن الزاوية أقل من $90^\\circ$"]'::jsonb, 'فهم', 'تشخيص خطأ في اختيار القانون', 'متوسط', 'الكتاب ص 155 — المفاهيم الرئيسة للدرس 5-1'),
('mcq', 5, 'بعد أن حسب طالب مقدار المحصلة لمتجهين الزاوية بينهما في مثلث الجمع $70^\circ$ بقانون جيب التمام، أراد إيجاد الزاوية بين المحصلة وأحد المتجهين. أيّ علاقة أنسب لذلك؟', null, null, '["قانون الجيب: $\\frac{R}{\\sin\\theta} = \\frac{B}{\\sin b}$","نظرية فيثاغورس: $R^2 = A^2 + B^2$","نسبة الظل في المثلث القائم: $\\tan b = \\frac{B}{A}$","الجمع العددي للمقادير: $R = A + B$"]'::jsonb, 'فهم', 'اختيار القانون المناسب', 'متوسط', 'الكتاب ص 132 — متى تُستعمل نظرية فيثاغورس وقانونا جيب التمام والجيب'),
('mcq', 6, 'يعبر قارب نهرًا؛ فسرعته المتجهة بالنسبة إلى الماء $\boldsymbol{v}_b$ مقدارها 4.0 m/s عمودية على الضفة، وسرعة التيار $\boldsymbol{v}_w$ مقدارها 3.0 m/s موازية للضفة كما في الشكل الآتي. إذا كانت سرعة القارب بالنسبة إلى الضفة هي محصلة هاتين السرعتين، فأيّ مما يأتي يعطي مقدارها؟', null, '[{"src":"qimg/phys1/c5l1-o03-boat.svg","alt":"نهر بين ضفتين أفقيتين، وفيه قارب. من القارب سهم أحمر إلى أعلى عمودي على الضفة مكتوب عنده vb و4.0 m/s، وسهم أحمر إلى اليمين موازٍ للضفة مكتوب عنده vw و3.0 m/s، وفي أعلى اليمين سهم رمادي إلى اليمين مكتوب عنده اتجاه التيار. لا تظهر السرعة المحصلة."}]'::jsonb, '["$4.0 + 3.0 = 7.0\\ \\text{m/s}$","$4.0 - 3.0 = 1.0\\ \\text{m/s}$","$\\sqrt{(4.0)^2 - (3.0)^2} = 2.6\\ \\text{m/s}$","$\\sqrt{(4.0)^2 + (3.0)^2} = 5.0\\ \\text{m/s}$"]'::jsonb, 'تطبيق', 'تطبيق نظرية فيثاغورس على السرعات', 'سهل', 'الكتاب ص 174 — جمع سرعتين متعامدتين بنظرية فيثاغورس'),
('mcq', 7, 'أيّ الحالات الآتية لا يكفي فيها استعمال نظرية فيثاغورس وحدها لإيجاد مقدار المحصلة؟', null, null, '["إزاحة 6.0 km شرقًا ثم 4.0 km جنوبًا","قوة 6.0 N أفقية وقوة 4.0 N رأسية تؤثران في جسم","إزاحة 6.0 km شرقًا ثم 4.0 km في اتجاه الشمال الشرقي","سرعة قارب 6.0 m/s عبر النهر وسرعة تيار 4.0 m/s على طوله"]'::jsonb, 'تحليل', 'تمييز الحالات', 'صعب', 'الكتاب ص 155 — المفاهيم الرئيسة للدرس 5-1'),
('essay', 1, 'وضّح متى تُستعمل نظرية فيثاغورس، ومتى يُستعمل قانون جيب التمام أو قانون الجيب لإيجاد محصلة متجهين، واذكر مثالًا لكل حالة.', null, null, null, 'فهم', 'توضيح وتمييز', 'متوسط', 'الكتاب ص 132 — متى تُستعمل نظرية فيثاغورس وقانونا جيب التمام والجيب'),
('essay', 2, 'لكل حالة من الحالات الثلاث في الجدول الآتي: حدّد العلاقة المناسبة لإيجاد مقدار المحصلة مع التعليل، ثم احسب مقدار المحصلة.', '{"headers":["الحالة","الوصف"],"rows":[["1","إزاحة 8.0 m شمالًا ثم 6.0 m غربًا"],["2","قوتان مقدار كل منهما 10.0 N تؤثران في نقطة، والزاوية بين اتجاهيهما $60.0^\\circ$"],["3","إزاحة 5.0 km، ثم انعطاف $30.0^\\circ$ إلى اليمين وإزاحة 5.0 km أخرى"]]}'::jsonb, null, null, 'تحليل', 'تصنيف حالات وحسابها', 'صعب', 'الكتاب ص 132 — متى تُستعمل نظرية فيثاغورس وقانونا جيب التمام والجيب'),
('essay', 3, 'قال طالب: «قانون جيب التمام قانون عام لإيجاد مقدار محصلة متجهين، ونظرية فيثاغورس حالة خاصة منه». قوّم هذه العبارة مبيّنًا ذلك رياضيًّا، ثم وضّح متى يكون استعمال نظرية فيثاغورس كافيًا.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 155 — المفاهيم الرئيسة للدرس 5-1')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
