insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'الإزاحتان متعامدتان (الزاوية بينهما $90^\circ$)، فتكوّنان مع المحصلة مثلثًا قائم الزاوية وترًا فيه المحصلة، فتُستعمل نظرية فيثاغورس $R^2 = A^2 + B^2$.', '["الشرق والشمال متعامدان، فالزاوية بين الإزاحتين $90^\\circ$ تمامًا.","المقادير تُجمع عدديًّا فقط إذا كان للمتجهين الاتجاه نفسه.","قانون الجيب يحتاج إلى زاوية مقابلة لضلع معلوم غير الزاوية القائمة، ولا يعطي المقدار مباشرة هنا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-20T17:53:29.917Z"}'::jsonb),
('mcq', 2, 1, 'الزاوية بين المتجهين لا تساوي $90^\circ$، فيُستعمل قانون جيب التمام $R^2 = A^2 + B^2 - 2AB\cos\theta$ بالزاوية $\theta = 120^\circ$.', '["نظرية فيثاغورس تصح فقط عندما تكون الزاوية بين المتجهين $90^\\circ$، والزاوية هنا $120^\\circ$.","","الجمع العددي يصح فقط عندما يكون للقوتين الاتجاه نفسه.","هذه العلاقة تعطي زاوية المحصلة لا مقدارها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-20T17:53:29.917Z"}'::jsonb),
('mcq', 3, 0, 'في الرسم 2 يقع $\boldsymbol{A}$ على خط أفقي من خطوط الشبكة و$\boldsymbol{B}$ على خط رأسي، فهما متعامدان والزاوية بينهما $90^\circ$، فيكوّنان مع المحصلة مثلثًا قائم الزاوية.', '["","المتجه $\\boldsymbol{B}$ يميل على امتداد $\\boldsymbol{A}$، فالزاوية بين المتجهين في مثلث الجمع منفرجة لا قائمة، فيلزم قانون جيب التمام.","المتجه $\\boldsymbol{B}$ يرتد مائلًا نحو الخلف، فالزاوية بين المتجهين في مثلث الجمع حادة لا قائمة.","المتجهان كلاهما مائلان على خطوط الشبكة بزاويتين مختلفتين، والزاوية بينهما ليست $90^\\circ$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-20T17:53:29.918Z"}'::jsonb),
('mcq', 4, 2, 'نظرية فيثاغورس تصح فقط إذا كان المتجهان متعامدين؛ والمثلث المكوَّن من المتجهين والمحصلة هنا ليس قائم الزاوية لأن الزاوية بينهما $60^\circ$، فيجب استعمال قانون جيب التمام.', '["النظرية تصح لأي متجهين متعامدين: إزاحات أو قوى أو سرعات.","الجمع العددي يصح فقط إذا كان للمتجهين الاتجاه نفسه.","","الطرح العددي يصح فقط إذا كان المتجهان متعاكسين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-20T17:53:29.918Z"}'::jsonb),
('mcq', 5, 0, 'عندما تكون الزاوية بين المتجهين لا تساوي $90^\circ$ يُستعمل قانون الجيب لإيجاد زاوية في مثلث الجمع: $\frac{R}{\sin\theta} = \frac{B}{\sin b}$.', '["","نظرية فيثاغورس تعطي مقدارًا لا زاوية، ولا تصح هنا لأن الزاوية $70^\\circ$.","هذه النسبة تصح في المثلث القائم فقط، والمثلث هنا ليس قائمًا.","هذا جمع عددي للمقادير، ولا يعطي أي زاوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-20T17:53:29.918Z"}'::jsonb),
('mcq', 6, 3, 'السرعتان متعامدتان، فمقدار المحصلة $v = \sqrt{v_b^2 + v_w^2} = \sqrt{(4.0)^2 + (3.0)^2} = 5.0\ \text{m/s}$.', '["جُمع المقداران عدديًّا، والسرعتان متعامدتان.","طُرح المقداران كأن السرعتين متعاكستان، وهما متعامدتان.","طُرح المربعان؛ ونظرية فيثاغورس تجمع مربعي الضلعين القائمين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-20T17:53:29.919Z"}'::jsonb),
('mcq', 7, 2, 'في إزاحة 6.0 km شرقًا ثم 4.0 km في اتجاه الشمال الشرقي، يصنع اتجاه الشمال الشرقي $45^\circ$ مع الشرق، فالزاوية بين الإزاحتين ليست $90^\circ$، فيلزم قانون جيب التمام (أو تحليل المتجهات)، أما بقية الحالات فالمتجهان فيها متعامدان.', '["الشرق والجنوب متعامدان، فتكفي نظرية فيثاغورس.","القوة الأفقية والقوة الرأسية متعامدتان، فتكفي نظرية فيثاغورس.","","السرعة عبر النهر عمودية على سرعة التيار، فتكفي نظرية فيثاغورس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-20T17:53:29.919Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تُستعمل نظرية فيثاغورس $R^2 = A^2 + B^2$ عندما تكون الزاوية بين المتجهين $90^\circ$، لأن المتجهين والمحصلة يكوّنون مثلثًا قائمًا وترُه المحصلة؛ مثل إزاحة شرقًا ثم إزاحة شمالًا. أما إذا كانت الزاوية بين المتجهين لا تساوي $90^\circ$ فيُستعمل قانون جيب التمام $R^2 = A^2 + B^2 - 2AB\cos\theta$ لإيجاد المقدار، وقانون الجيب $\frac{R}{\sin\theta} = \frac{A}{\sin a} = \frac{B}{\sin b}$ لإيجاد الزوايا؛ مثل قوتين بينهما $120^\circ$.', '["فيثاغورس عند الزاوية $90^\\circ$ مع التعليل","جيب التمام أو الجيب عند زاوية لا تساوي $90^\\circ$","مثال صحيح لكل حالة"]'::jsonb, '[]'::jsonb, '[{"element":"حالة فيثاغورس","marks":1},{"element":"حالة جيب التمام والجيب","marks":1},{"element":"مثالان صحيحان","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"درجتان","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال فيثاغورس لأي زاويتين","القول إن قانون الجيب يعطي مقدار المحصلة دائمًا دون معرفة زاوية مقابلة","عدم ذكر شرط الزاوية القائمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-20T17:53:29.920Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) الشمال والغرب متعامدان ⇐ فيثاغورس: $R = \sqrt{(8.0)^2 + (6.0)^2} = 10.0\ \text{m}$. (2) الزاوية بين ذيلي القوتين $60.0^\circ$ فالزاوية في مثلث الجمع $180^\circ - 60.0^\circ = 120.0^\circ$ ⇐ قانون جيب التمام: $R = \sqrt{100 + 100 - 200\cos 120.0^\circ} = 17.3\ \text{N}$. (3) الانعطاف $30.0^\circ$ يجعل الزاوية بين الإزاحتين في مثلث الجمع $180^\circ - 30.0^\circ = 150.0^\circ$ ⇐ قانون جيب التمام: $R = \sqrt{25 + 25 - 50\cos 150.0^\circ} = 9.7\ \text{km}$.', '["الحالة 1: فيثاغورس و10.0 m","الحالة 2: جيب التمام بالزاوية $120.0^\\circ$ و17.3 N","الحالة 3: جيب التمام بالزاوية $150.0^\\circ$ و9.7 km"]'::jsonb, '["(1) $R = \\sqrt{64 + 36} = 10.0\\ \\text{m}$","(2) $\\theta = 120.0^\\circ$ ⇐ $R^2 = 300\\ \\text{N}^2$ ⇐ $R = 17.3\\ \\text{N}$","(3) $\\theta = 150.0^\\circ$ ⇐ $R^2 = 93.3\\ \\text{km}^2$ ⇐ $R = 9.7\\ \\text{km}$"]'::jsonb, '[{"element":"اختيار العلاقة وتعليلها في الحالة 1","marks":1},{"element":"حساب الحالة 1","marks":1},{"element":"الزاوية الصحيحة في الحالة 2","marks":1},{"element":"حساب الحالة 2","marks":1},{"element":"الزاوية الصحيحة في الحالة 3","marks":1},{"element":"حساب الحالة 3","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"5 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجتان","description":"عنصران صحيحان فقط أو طريقة صحيحة مع أخطاء متعددة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التعويض بالزاوية $60.0^\\circ$ مباشرة في الحالة 2 فينتج 10.0 N","التعويض بزاوية الانعطاف $30.0^\\circ$ في الحالة 3 فينتج 2.6 km","استعمال فيثاغورس في الحالات الثلاث"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-20T17:53:29.920Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة صحيحة. فقانون جيب التمام $R^2 = A^2 + B^2 - 2AB\cos\theta$ يصح لأي زاوية بين المتجهين، وعندما $\theta = 90^\circ$ يكون $\cos 90^\circ = 0$ فيختفي الحد الأخير ويصبح $R^2 = A^2 + B^2$ وهي نظرية فيثاغورس. لذلك تكفي نظرية فيثاغورس (وهي أبسط) عندما يكون المتجهان متعامدين، أما لغير ذلك من الزوايا فلا بد من قانون جيب التمام أو قانون الجيب.', '["الحكم بصحة العبارة","البرهان بالتعويض $\\theta = 90^\\circ$ و$\\cos 90^\\circ = 0$","تحديد شرط كفاية فيثاغورس (التعامد)"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"البرهان الرياضي","marks":1},{"element":"شرط استعمال فيثاغورس","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"درجتان","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بخطأ العبارة لأن القانونين مختلفان في الشكل","عدّ $\\cos 90^\\circ = 1$","القول إن فيثاغورس تصح لكل الزوايا الحادة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-20T17:53:29.920Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
