from (values
('mcq', 1, 0, 'الانعطاف $60.0^\circ$ يجعل الزاوية بين الإزاحتين في مثلث الجمع $120.0^\circ$: $R = \sqrt{(6.0)^2 + (4.0)^2 - 2(6.0)(4.0)\cos 120.0^\circ} = \sqrt{76} = 8.7\ \text{km}$.', '["","عُوّضت زاوية الانعطاف $60.0^\\circ$ في القانون، والزاوية بين الإزاحتين في مثلث الجمع $180^\\circ - 60.0^\\circ = 120.0^\\circ$.","جُمع المقداران مباشرة كأن الشخص لم ينعطف.","استُعملت نظرية فيثاغورس، والزاوية بين الإزاحتين ليست $90^\\circ$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-20T17:53:29.921Z"}'::jsonb),
('mcq', 2, 2, '$R^2 = (15.0)^2 + (10.0)^2 - 2(15.0)(10.0)\cos 135.0^\circ = 225 + 100 + 212 = 537\ \text{m}^2$، إذن $R = 23.2\ \text{m}$.', '["أُهملت إشارة $\\cos 135.0^\\circ$ السالبة فطُرح الحد $2AB|\\cos\\theta|$ بدل إضافته.","جُمع المقداران مباشرة؛ وهذا يصح فقط إذا كان للإزاحتين الاتجاه نفسه.","","استُعملت نظرية فيثاغورس، والزاوية $135.0^\\circ$ لا $90^\\circ$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-20T17:53:29.921Z"}'::jsonb),
('mcq', 3, 1, 'بنقل $\boldsymbol{F}_2$ إلى رأس $\boldsymbol{F}_1$ تصبح الزاوية بينهما في مثلث الجمع $180^\circ - 60.0^\circ = 120.0^\circ$، فـ $R = \sqrt{(20.0)^2 + (30.0)^2 - 2(20.0)(30.0)\cos 120.0^\circ} = \sqrt{1900} = 43.6\ \text{N}$.', '["عُوّضت الزاوية $60.0^\\circ$ بين ذيلي القوتين مباشرة؛ وعند وضع ذيل $\\boldsymbol{F}_2$ عند رأس $\\boldsymbol{F}_1$ تصبح الزاوية بينهما في مثلث الجمع $120.0^\\circ$.","","جُمع المقداران مباشرة كأن القوتين في الاتجاه نفسه.","استُعملت نظرية فيثاغورس، والقوتان غير متعامدتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-20T17:53:29.921Z"}'::jsonb),
('mcq', 4, 3, 'الزاوية في مثلث الجمع $160.0^\circ$: $R = \sqrt{(600)^2 + (600)^2 - 2(600)(600)\cos 160.0^\circ} = 1.18 \times 10^3\ \text{N}$، وهي أقل قليلًا من 1200 N لأن الحبلين متقاربان في الاتجاه.', '["جُمع المقداران مباشرة، وهذا يصح فقط لو كان الحبلان في الاتجاه نفسه تمامًا.","عُوّضت الزاوية $20.0^\\circ$ بين الحبلين مباشرة، والزاوية في مثلث الجمع $180^\\circ - 20.0^\\circ = 160.0^\\circ$.","استُعملت نظرية فيثاغورس، والحبلان غير متعامدين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-20T17:53:29.921Z"}'::jsonb),
('mcq', 5, 2, 'من $R^2 = A^2 + B^2 - 2AB\cos\theta$: $\cos\theta = \frac{A^2 + B^2 - R^2}{2AB} = \frac{64 + 25 - 49}{2(8.0)(5.0)} = 0.500$، إذن $\theta = 60.0^\circ$.', '["أُخطئ في إشارة جيب التمام عند إعادة ترتيب القانون، فالصحيح $\\cos\\theta = \\frac{A^2 + B^2 - R^2}{2AB} = +0.500$.","نُسي العدد 2 في المقام فنتج $\\cos\\theta = 1$.","","حُسبت الزاوية بمعكوس الجيب $\\sin^{-1}(0.500)$ بدل معكوس جيب التمام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-20T17:53:29.921Z"}'::jsonb),
('mcq', 6, 0, '$R = \sqrt{(2.50)^2 + (3.80)^2 - 2(2.50)(3.80)\cos 75.0^\circ} = 3.97\ \text{km}$؛ وهي أقل من 4.55 km لأن الزاوية حادة.', '["","استُعملت الزاوية المكمّلة $105.0^\\circ$ بدل الزاوية بين الإزاحتين في مثلث الجمع.","جُمع المقداران مباشرة.","استُعملت نظرية فيثاغورس، والزاوية $75.0^\\circ$ لا $90^\\circ$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-20T17:53:29.922Z"}'::jsonb),
('mcq', 7, 3, 'في $R^2 = A^2 + B^2 - 2AB\cos\theta$ كلما كبرت $\theta$ في مثلث الجمع صغر $\cos\theta$ (وصار سالبًا) فكبرت $R$؛ وعند $150^\circ$ تكون $R = 19.3\ \text{m}$ وهي أكبر القيم.', '["عند $30^\\circ$ يكون $\\cos\\theta$ كبيرًا موجبًا فتصغر المحصلة إلى 5.2 m تقريبًا.","عند $60^\\circ$ تكون المحصلة 10.0 m فقط.","عند $90^\\circ$ تكون المحصلة 14.1 m، وهي أقل من قيمتها عند زاوية منفرجة أكبر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-20T17:53:29.922Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المخطط: إزاحة $\boldsymbol{A}$ طولها 30.0 km، ومن رأسها إزاحة $\boldsymbol{B}$ طولها 20.0 km تنحرف $40.0^\circ$ عن امتداد $\boldsymbol{A}$، والمحصلة من ذيل $\boldsymbol{A}$ إلى رأس $\boldsymbol{B}$. الزاوية بين الإزاحتين في مثلث الجمع $180^\circ - 40.0^\circ = 140.0^\circ$، فـ $R^2 = (30.0)^2 + (20.0)^2 - 2(30.0)(20.0)\cos 140.0^\circ = 2219\ \text{km}^2$، إذن $R = 47.1\ \text{km}$.', '["مخطط صحيح للإزاحتين والمحصلة","الزاوية في مثلث الجمع $140.0^\\circ$","التعويض في قانون جيب التمام","R = 47.1 km"]'::jsonb, '["$\\theta = 180^\\circ - 40.0^\\circ = 140.0^\\circ$","$R^2 = 900 + 400 - 1200\\cos 140.0^\\circ = 2219\\ \\text{km}^2$","$R = 47.1\\ \\text{km}$"]'::jsonb, '[{"element":"المخطط","marks":1},{"element":"تحديد الزاوية $140.0^\\circ$","marks":1},{"element":"التعويض الصحيح","marks":1},{"element":"الناتج بالوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجتان","description":"عنصران صحيحان فقط أو طريقة صحيحة مع أخطاء متعددة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التعويض بزاوية الانعطاف $40.0^\\circ$ فينتج 19.5 km","جمع المقدارين 50.0 km","استعمال فيثاغورس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-20T17:53:29.922Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نضع ذيل $\boldsymbol{F}_2$ عند رأس $\boldsymbol{F}_1$ فتصبح الزاوية بينهما في مثلث الجمع $180^\circ - 50.0^\circ = 130.0^\circ$ (لأن قانون جيب التمام يستعمل الزاوية المقابلة للمحصلة). $R^2 = (45.0)^2 + (60.0)^2 - 2(45.0)(60.0)\cos 130.0^\circ = 9096\ \text{N}^2$، إذن $R = 95.4\ \text{N}$.', '["نقل المتجه رأسًا لذيل","الزاوية $130.0^\\circ$ مع التعليل","R = 95.4 N"]'::jsonb, '["$\\theta = 180^\\circ - 50.0^\\circ = 130.0^\\circ$","$R^2 = 2025 + 3600 - 5400\\cos 130.0^\\circ = 9096\\ \\text{N}^2$","$R = 95.4\\ \\text{N}$"]'::jsonb, '[{"element":"ترتيب المتجهين رأسًا لذيل","marks":1},{"element":"تحديد الزاوية $130.0^\\circ$ وتعليلها","marks":1},{"element":"حساب R = 95.4 N","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"درجتان","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التعويض بالزاوية $50.0^\\circ$ فينتج 46.4 N","جمع المقدارين 105 N","إهمال إشارة جيب التمام السالبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-20T17:53:29.922Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $\cos\theta = \frac{A^2 + B^2 - R^2}{2AB} = \frac{81 + 36 - 144}{2(9.0)(6.0)} = -0.25$، إذن $\theta = 104^\circ$. (ب) الزاوية منفرجة لأن جيب تمامها سالب؛ ولذلك يكون $R^2 = 144$ أكبر من $A^2 + B^2 = 117$، أي أن المحصلة أطول مما لو كان المتجهان متعامدين.', '["إعادة ترتيب القانون صحيحة","$\\cos\\theta = -0.25$","$\\theta$ = $104^\\circ$","الحكم بأنها منفرجة مع المقارنة بفيثاغورس"]'::jsonb, '["$\\cos\\theta = \\frac{A^2 + B^2 - R^2}{2AB}$","$\\cos\\theta = \\frac{-27}{108} = -0.25$","$\\theta = \\cos^{-1}(-0.25) = 104^\\circ$"]'::jsonb, '[{"element":"إعادة ترتيب القانون","marks":1},{"element":"حساب جيب التمام","marks":1},{"element":"الزاوية $104^\\circ$","marks":1},{"element":"التفسير والمقارنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجتان","description":"عنصران صحيحان فقط أو طريقة صحيحة مع أخطاء متعددة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["خطأ إشارة عند نقل الحدود فينتج $76^\\circ$","نسيان العدد 2 في المقام","استعمال $\\sin^{-1}$ بدل $\\cos^{-1}$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-20T17:53:29.923Z"}'::jsonb)
