('mcq', 2, 'لماذا تُحلَّل المتجهات إلى مركّباتها عند جمعها حسابيًّا؟', null, null, '["لأن مركّبات المحور الواحد تُجمع عدديًّا فيسهل الجمع","لأن مقدار المحصلة يساوي دائمًا مجموع مقادير المتجهات المجموعة","لأن مقدار كل مركّبة أكبر من مقدار المتجه الأصلي","لأن الجمع بالمركّبات لا يحتاج إلى نظام إحداثي"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 135 — جمع المتجهات جبريًّا'),
('mcq', 3, 'بعد اختيار نظام إحداثي وتحليل كل متجه إلى مركّبتيه، ما الخطوة التالية في جمع المتجهات جبريًّا؟', null, null, '["تطبيق $\\theta = \\tan^{-1}\\left(\\frac{R_y}{R_x}\\right)$ لإيجاد زاوية المحصلة","جمع مقادير المتجهات للحصول على مقدار المحصلة","تطبيق نظرية فيثاغورس على كل متجه لإيجاد مقداره","جمع مركّبات x للحصول على $R_x$، وجمع مركّبات y للحصول على $R_y$"]'::jsonb, 'فهم', 'ترتيب خطوات', 'متوسط', 'الكتاب ص 136 — استراتيجيات حل المسألة: جمع المتجهات'),
('mcq', 4, 'يبين الشكل الآتي ثلاثة متجهات $\boldsymbol{A}$ و$\boldsymbol{B}$ و$\boldsymbol{C}$ على شبكة مربعات (ضلع المربع 1.0 m) وُضع كل منها عند رأس السابق. ما مركّبتا المحصلة $R_x$ و$R_y$؟', null, '[{"src":"qimg/phys1/c5l1-o05-grid3.svg","alt":"شبكة مربعات ضلع المربع فيها 1.0 m، ومحوران +x و+y. المتجه A يبدأ من نقطة الأصل وينتهي عند (2، 1)، ومن رأسه المتجه B ينتهي عند (5، 3)، ومن رأسه المتجه C ينتهي عند (4، 6). الأسهم زرقاء ولا تظهر المحصلة."}]'::jsonb, '["$R_x = 6.0\\ \\text{m}$ و$R_y = 6.0\\ \\text{m}$","$R_x = 4.0\\ \\text{m}$ و$R_y = 6.0\\ \\text{m}$","$R_x = 6.0\\ \\text{m}$ و$R_y = 4.0\\ \\text{m}$","$R_x = 5.0\\ \\text{m}$ و$R_y = 3.0\\ \\text{m}$"]'::jsonb, 'تطبيق', 'قراءة مركّبات وجمعها من رسم', 'متوسط', 'الكتاب ص 135 — جمع المتجهات جبريًّا'),
('mcq', 5, 'لماذا يمكن حساب مقدار المحصلة من مركّبتيها بالعلاقة $R^2 = R_x^2 + R_y^2$؟', null, null, '["لأن $R_x$ و$R_y$ متساويتان في المقدار دائمًا","لأن المحصلة تساوي مجموع مركّبتيها جمعًا عدديًّا","لأن $\\boldsymbol{R}$ تصنع زاوية $45^\\circ$ مع المحور x دائمًا","لأن $R_x$ و$R_y$ متعامدتان فتكوّنان مع $\\boldsymbol{R}$ مثلثًا قائمًا"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 135 — جمع المتجهات جبريًّا'),
('mcq', 6, 'تحرك جسم 5.0 m شرقًا، ثم 8.0 m غربًا، ثم 2.0 m شرقًا. إذا كان المحور $+x$ نحو الشرق، فما المركّبة $R_x$ للإزاحة المحصلة؟', null, null, '["$-1.0\\ \\text{m}$","$+15.0\\ \\text{m}$","$+1.0\\ \\text{m}$","$-5.0\\ \\text{m}$"]'::jsonb, 'تطبيق', 'جمع جبري بالإشارات', 'متوسط', 'الكتاب ص 135 — جمع المتجهات جبريًّا'),
('mcq', 7, 'ثلاثة متجهات مجموع مركّباتها الأفقية صفر، ومجموع مركّباتها الرأسية $-6.0\ \text{N}$. ماذا تستنتج عن محصلتها؟', null, null, '["مقدارها صفر لأن إحدى مركّبتيها صفر","مقدارها 6.0 N واتجاهها نحو $+x$","مقدارها 6.0 N واتجاهها نحو $-y$","مقدارها $-6.0\\ \\text{N}$ لأن المقدار يأخذ إشارة المركّبة"]'::jsonb, 'تحليل', 'استنتاج من المركّبات', 'صعب', 'الكتاب ص 155 — المفاهيم الرئيسة: جمع المركّبات على كل محور منفصلًا'),
('essay', 1, 'وضّح خطوات جمع متجهين أو أكثر جبريًّا (بطريقة المركّبات) بدءًا من اختيار النظام الإحداثي حتى إيجاد مقدار المحصلة واتجاهها.', null, null, null, 'فهم', 'توضيح إجراء', 'متوسط', 'الكتاب ص 136 — استراتيجيات حل المسألة: جمع المتجهات'),
('essay', 2, 'يبين الشكل الآتي متجهين $\boldsymbol{A}$ و$\boldsymbol{B}$ على شبكة مربعات (ضلع المربع 1.0 m)، وُضع ذيل $\boldsymbol{B}$ عند رأس $\boldsymbol{A}$. (أ) اكتب مركّبتي كل متجه. (ب) وضّح كيف تحصل على $R_x$ و$R_y$، ثم احسب مقدار المحصلة واتجاهها.', null, '[{"src":"qimg/phys1/c5l1-o05-e2.svg","alt":"شبكة مربعات ضلع المربع فيها 1.0 m، ومحوران +x و+y. المتجه A يبدأ من نقطة الأصل وينتهي عند (4، 1)، ومن رأسه المتجه B ينتهي عند (3، 4) أي يتجه إلى اليسار مربعًا واحدًا وإلى أعلى 3 مربعات. لا تظهر المحصلة."}]'::jsonb, null, 'تطبيق', 'توضيح بالرسم وحساب', 'صعب', 'الكتاب ص 135 — جمع المتجهات جبريًّا'),
('essay', 3, 'قارن بين جمع المتجهات بطريقة الرسم وجمعها جبريًّا من حيث: الأدوات اللازمة، ودقة النتيجة، وسهولة جمع عدد كبير من المتجهات. ثم بيّن أيّ الطريقتين تفضّل لجمع خمس قوى مختلفة الاتجاهات، مع التعليل.', null, null, null, 'تقويم', 'مقارنة وإصدار حكم', 'صعب', 'الكتاب ص 136 — استراتيجيات حل المسألة: جمع المتجهات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
