insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'تُجمع المركّبات الأفقية (مركّبات المحور x) للمتجهات جميعها جمعًا جبريًّا: $R_x = A_x + B_x + C_x$.', '["هذا جمع لمقادير المتجهات كاملة لا لمركّباتها الأفقية.","هاتان مركّبتا متجه واحد على محورين مختلفين، ولا تُجمعان معًا.","","المركّبات على المحور نفسه تُجمع جمعًا جبريًّا مباشرًا لا بالتربيع والجذر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-20T17:53:29.923Z"}'::jsonb),
('mcq', 2, 0, 'تحليل المتجهات يسهّل عملية جمعها حسابيًّا؛ فالمركّبات على المحور x متوازية فتُجمع جبريًّا، وكذلك المركّبات على المحور y.', '["","مقدار المحصلة لا يساوي مجموع المقادير إلا إذا كانت المتجهات في اتجاه واحد.","المتجه الأصلي وتر المثلث، فمقداره أكبر من أي مركّبة.","المركّبات تُعرَّف بالنسبة إلى محوري نظام إحداثي، فاختياره أول خطوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-20T17:53:29.923Z"}'::jsonb),
('mcq', 3, 3, 'بعد التحليل تُجمع المركّبات على المحور x لتكوين $R_x$، وعلى المحور y لتكوين $R_y$، ثم يُحسب $R = \sqrt{R_x^2 + R_y^2}$ و$\theta = \tan^{-1}\left(\frac{R_y}{R_x}\right)$.', '["إيجاد الزاوية هو الخطوة الأخيرة، ويحتاج إلى $R_x$ و$R_y$ أولًا.","لا تُجمع المقادير مباشرة؛ بل تُجمع المركّبات على كل محور.","مقادير المتجهات معلومة أصلًا، وفيثاغورس تُطبَّق على $R_x$ و$R_y$ بعد جمعهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-20T17:53:29.923Z"}'::jsonb),
('mcq', 4, 1, '$A_x = 2.0$، $B_x = 3.0$، $C_x = -1.0$ ⇐ $R_x = 4.0\ \text{m}$. و$A_y = 1.0$، $B_y = 2.0$، $C_y = 3.0$ ⇐ $R_y = 6.0\ \text{m}$.', '["أُهملت الإشارة السالبة للمركّبة $C_x$ (المتجه $\\boldsymbol{C}$ يتجه إلى اليسار).","","تبادلت قيمتا المركّبتين؛ فالحركة الرأسية الكلية 6 مربعات والأفقية 4.","جُمعت مركّبات $\\boldsymbol{A}$ و$\\boldsymbol{B}$ فقط ونُسي المتجه $\\boldsymbol{C}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-20T17:53:29.924Z"}'::jsonb),
('mcq', 5, 3, 'المركّبة $R_x$ توازي المحور x و$R_y$ توازي المحور y، فهما متعامدتان فتكوّنان مع $\boldsymbol{R}$ مثلثًا قائمًا، والمحصلة وتر هذا المثلث، فتُطبَّق نظرية فيثاغورس.', '["المركّبتان لا تتساويان إلا عندما تصنع المحصلة $45^\\circ$ مع المحور x.","لو كان كذلك لكان $R = R_x + R_y$، والمركّبتان متعامدتان فلا تُجمعان عدديًّا.","زاوية المحصلة تتغير بحسب المتجهات المجموعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-20T17:53:29.924Z"}'::jsonb),
('mcq', 6, 0, '$R_x = (+5.0) + (-8.0) + (+2.0) = -1.0\ \text{m}$، أي 1.0 m نحو الغرب.', '["","جُمعت المقادير دون مراعاة إشارة الاتجاه؛ فالإزاحة غربًا مركّبتها سالبة.","الحساب صحيح عدديًّا لكن الإشارة خطأ؛ فالمحصلة نحو الغرب.","عوملت الإزاحة الأخيرة (2.0 m شرقًا) على أنها سالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-20T17:53:29.924Z"}'::jsonb),
('mcq', 7, 2, '$R_x = 0$ و$R_y = -6.0\ \text{N}$ ⇐ $R = \sqrt{0 + (-6.0)^2} = 6.0\ \text{N}$، واتجاهها في الاتجاه السالب للمحور y.', '["المحصلة تكون صفرًا فقط إذا كانت المركّبتان كلتاهما صفرًا.","المركّبة الأفقية صفر، فالمحصلة على المحور y، والإشارة السالبة تعني $-y$.","","المقدار لا يكون سالبًا؛ الإشارة تدل على الاتجاه فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-20T17:53:29.924Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) نختار نظامًا إحداثيًّا. 2) نحلّل كل متجه إلى مركّبتيه: $A_x = A\cos\theta$ و$A_y = A\sin\theta$، حيث $\theta$ مقيسة في عكس اتجاه حركة عقارب الساعة من محور x الموجب. 3) نجمع مركّبات x جبريًّا لنحصل على $R_x$. 4) نجمع مركّبات y جبريًّا لنحصل على $R_y$. 5) نحسب المقدار $R = \sqrt{R_x^2 + R_y^2}$. 6) نحسب الزاوية $\theta = \tan^{-1}\left(\frac{R_y}{R_x}\right)$.', '["اختيار النظام الإحداثي","التحليل بالعلاقتين $A\\cos\\theta$ و$A\\sin\\theta$","جمع مركّبات كل محور منفصلة مع الإشارات","المقدار بفيثاغورس والاتجاه بالظل العكسي"]'::jsonb, '[]'::jsonb, '[{"element":"اختيار النظام الإحداثي","marks":1},{"element":"التحليل إلى مركّبات","marks":1},{"element":"جمع المركّبات لكل محور","marks":1},{"element":"حساب المقدار والاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجتان","description":"عنصران صحيحان فقط أو طريقة صحيحة مع أخطاء متعددة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع مقادير المتجهات مباشرة","جمع المركّبة x لمتجه مع المركّبة y لمتجه آخر","إهمال إشارات المركّبات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-20T17:53:29.924Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $A_x = 4.0\ \text{m}$، $A_y = 1.0\ \text{m}$؛ $B_x = -1.0\ \text{m}$، $B_y = 3.0\ \text{m}$. (ب) تُجمع مركّبات كل محور منفصلة: $R_x = 4.0 + (-1.0) = 3.0\ \text{m}$، $R_y = 1.0 + 3.0 = 4.0\ \text{m}$. ولأنهما متعامدتان: $R = \sqrt{(3.0)^2 + (4.0)^2} = 5.0\ \text{m}$، و$\theta = \tan^{-1}\left(\frac{4.0}{3.0}\right) = 53.1^\circ$ فوق محور $+x$.', '["مركّبات A وB بالإشارات الصحيحة","$R_x$ = 3.0 m و$R_y$ = 4.0 m","R = 5.0 m","$\\theta$ = $53.1^\\circ$"]'::jsonb, '["$R_x = A_x + B_x = 4.0 - 1.0 = 3.0\\ \\text{m}$","$R_y = A_y + B_y = 1.0 + 3.0 = 4.0\\ \\text{m}$","$R = \\sqrt{R_x^2 + R_y^2} = 5.0\\ \\text{m}$","$\\theta = \\tan^{-1}\\left(\\frac{4.0}{3.0}\\right) = 53.1^\\circ$"]'::jsonb, '[{"element":"المركّبات","marks":1},{"element":"جمع المركّبات","marks":1},{"element":"المقدار","marks":1},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجتان","description":"عنصران صحيحان فقط أو طريقة صحيحة مع أخطاء متعددة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ $B_x$ موجبة","حساب $\\tan^{-1}(3.0/4.0)$","جمع مقداري A وB"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-20T17:53:29.925Z"}'::jsonb),
('essay', 3, null::int, null, null, 'طريقة الرسم تحتاج إلى مسطرة ومنقلة ومقياس رسم، ودقتها محدودة بدقة الرسم والقياس، ويصعب تطبيقها مع متجهات كثيرة. أما الطريقة الجبرية فتحتاج إلى نظام إحداثي وآلة حاسبة (حساب المثلثات)، ونتيجتها أدق، وتُجمع فيها أي عدد من المتجهات بجمع المركّبات على كل محور. لذا تُفضَّل الطريقة الجبرية لجمع خمس قوى، لأنها تحوّل الجمع إلى عمليتي جمع عدديتين ($R_x$ و$R_y$)، ويمكن التحقق منها بالرسم.', '["المقارنة في الأدوات","المقارنة في الدقة","المقارنة في عدد المتجهات","اختيار الجبرية مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"الأدوات","marks":1},{"element":"الدقة","marks":1},{"element":"عدد المتجهات واختيار الطريقة مع التعليل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"درجتان","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن طريقة الرسم أدق دائمًا","عدم تعليل الاختيار","الخلط بين الطريقتين في الخطوات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-20T17:53:29.925Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
