from (values
('mcq', 1, 'إزاحتان: $\boldsymbol{A}$ مقدارها 10.0 km في اتجاه يصنع $30.0^\circ$ مع محور $+x$، و$\boldsymbol{B}$ مقدارها 6.0 km في اتجاه يصنع $120.0^\circ$ مع محور $+x$ (الزاويتان مقيستان في عكس اتجاه حركة عقارب الساعة). ما مقدار المحصلة واتجاهها؟', null, null, '["11.7 km بزاوية $29.0^\\circ$ مع محور $+x$","11.7 km بزاوية $61.0^\\circ$ مع محور $+x$","15.5 km بزاوية $41.2^\\circ$ مع محور $+x$","16.0 km بزاوية $75.0^\\circ$ مع محور $+x$"]'::jsonb, 'تطبيق', 'جمع متجهين جبريًّا', 'متوسط', 'الكتاب ص 136 — استراتيجيات حل المسألة: جمع المتجهات'),
('mcq', 2, 'تؤثر ثلاث قوى في حلقة كما في الشكل الآتي. ما مقدار القوة المحصلة؟', null, '[{"src":"qimg/phys1/c5l1-o06-forces3.svg","alt":"محوران +x و+y وحلقة عند نقطة الأصل. من الحلقة ثلاثة أسهم زرقاء: F₁ على محور +x مكتوب تحته 50.0 N، وF2 مائل إلى أعلى اليمين بزاوية 60.0° مع محور +x مكتوب بجانبه 120.0 N، وF3 على المحور x نحو اليسار مكتوب تحته 90.0 N. لا تظهر القوة المحصلة."}]'::jsonb, '["260 N","225 N","87.7 N","106 N"]'::jsonb, 'تطبيق', 'جمع ثلاث قوى جبريًّا', 'صعب', 'الكتاب ص 157 — السؤال 62: القوة المحصلة المؤثرة في حلقة'),
('mcq', 3, 'حسب طالب مركّبتي محصلة فوجد $R_x = -6.0\ \text{N}$ و$R_y = 8.0\ \text{N}$. ما اتجاه المحصلة مقيسًا من محور $+x$ في عكس اتجاه حركة عقارب الساعة؟', null, null, '["$127^\\circ$","$-53.1^\\circ$","$53.1^\\circ$","$36.9^\\circ$"]'::jsonb, 'تحليل', 'تحديد اتجاه المحصلة', 'متوسط', 'الكتاب ص 137 — المثال 2: الطريق إلى المنزل'),
('mcq', 4, 'يقع منزل على بعد 12.0 km في اتجاه يصنع $30.0^\circ$ شمال الشرق من موقعك، والطريق المتاح يتجه أولًا 4.0 km شرقًا. ما مقدار الإزاحة التي يجب أن تقطعها بعد ذلك حتى تصل إلى المنزل؟', null, null, '["8.0 km","15.6 km","8.8 km","11.3 km"]'::jsonb, 'تطبيق', 'إيجاد متجه مجهول من المحصلة', 'صعب', 'الكتاب ص 137 — المثال 2: الطريق إلى المنزل'),
('mcq', 5, 'بدأت الحركة من منزلك فقطعت 6.0 km شمالًا، ثم انعطفت شرقًا حتى أصبحت إزاحتك من المنزل 10.0 km. ما مقدار إزاحتك شرقًا؟', null, null, '["4.0 km","8.0 km","16.0 km","11.7 km"]'::jsonb, 'تطبيق', 'إيجاد مركّبة مجهولة', 'سهل', 'الكتاب ص 138 — المسائل التدريبية 3–8'),
('mcq', 6, 'أرجوحة طفل معلّقة بحبلين يميل كل منهما $15.0^\circ$ عن الرأسي، والشد في كل حبل 3.10 N كما في الشكل الآتي. ما مقدار القوة المحصلة التي يؤثر بها الحبلان في الأرجوحة واتجاهها؟', null, '[{"src":"qimg/phys1/c5l1-o06-swing.svg","alt":"مقعد أرجوحة أفقي في أسفل الشكل، ومن نقطة في وسطه يخرج سهمان أزرقان مائلان إلى أعلى: F₁ يميل إلى اليسار وF2 يميل إلى اليمين، ومكتوب عند كل منهما 3.10 N، وخط رأسي متقطع بينهما، ومكتوب 15.0° بين كل سهم والخط الرأسي. لا تظهر القوة المحصلة."}]'::jsonb, '["6.20 N رأسيًّا إلى أعلى","1.60 N رأسيًّا إلى أعلى","5.99 N أفقيًّا","5.99 N رأسيًّا إلى أعلى"]'::jsonb, 'تطبيق', 'جمع قوتين متماثلتين', 'سهل', 'الكتاب ص 138 — المسائل التدريبية 3–8'),
('mcq', 7, 'يبين الشكل الآتي ثلاث إزاحات متتالية $\boldsymbol{A}$ و$\boldsymbol{B}$ و$\boldsymbol{C}$ على شبكة مربعات (ضلع المربع 1.0 m). ما مقدار الإزاحة المحصلة؟', null, '[{"src":"qimg/phys1/c5l1-o06-grid.svg","alt":"شبكة مربعات ضلع المربع فيها 1.0 m ومحوران +x و+y. ثلاثة أسهم خضراء متتالية: A من نقطة الأصل إلى (4، 3)، ثم B من (4، 3) إلى (5، −2)، ثم C من (5، −2) إلى (3، −4). لا تظهر الإزاحة المحصلة."}]'::jsonb, '["5.0 m","12.9 m","7.0 m","1.0 m"]'::jsonb, 'تطبيق', 'جمع ثلاث إزاحات من رسم', 'سهل', 'الكتاب ص 136 — استراتيجيات حل المسألة: جمع المتجهات'),
('essay', 1, 'قطع متسابق ثلاث إزاحات متتالية: 4.0 km في اتجاه محور $+x$، ثم 7.0 km في اتجاه يصنع $60.0^\circ$ مع محور $+x$، ثم 3.0 km في اتجاه يصنع $150.0^\circ$ مع محور $+x$. احسب مقدار الإزاحة المحصلة واتجاهها جبريًّا.', null, null, null, 'تطبيق', 'مسألة جمع جبري', 'متوسط', 'الكتاب ص 136 — استراتيجيات حل المسألة: جمع المتجهات'),
('essay', 2, 'يُرفع صندوق بحبلين كما في الشكل الآتي: الحبل الأول يؤثر بقوة $\boldsymbol{F}_1$ مقدارها 24.0 N في اتجاه يصنع $125.0^\circ$ مع محور $+x$، والثاني بقوة $\boldsymbol{F}_2$ مقدارها 21.0 N في اتجاه يصنع $55.0^\circ$ مع محور $+x$، ووزن الصندوق $\boldsymbol{F}_g$ مقداره 20.0 N. احسب المركّبتين x وy للقوة المحصلة المؤثرة في الصندوق، ثم احسب مقدارها واتجاهها.', null, '[{"src":"qimg/phys1/c5l1-o06-e2.svg","alt":"محوران +x و+y ونقطة عند الأصل تمثّل الصندوق. منها ثلاثة أسهم زرقاء: F₁ مائل إلى أعلى اليسار مكتوب بجانبه 24.0 N وقوس من محور +x إليه مكتوب عنده 125.0°، وF2 مائل إلى أعلى اليمين مكتوب بجانبه 21.0 N وقوس من محور +x إليه مكتوب عنده 55.0°، وFg رأسي إلى أسفل مكتوب بجانبه 20.0 N. لا تظهر القوة المحصلة."}]'::jsonb, null, 'تطبيق', 'مسألة قوى متعددة', 'متوسط', 'الكتاب ص 138 — المسائل التدريبية 3–8'),
('essay', 3, 'يقع منزل على بعد 14.0 km من موقعك في اتجاه يصنع $125.0^\circ$ مع محور $+x$ (المحور $+x$ نحو الشرق و$+y$ نحو الشمال)، والطريق المتاح يتجه أولًا 6.0 km غربًا. احسب مقدار الإزاحة التي يجب أن تقطعها بعد ذلك واتجاهها.', null, null, null, 'تحليل', 'إيجاد متجه مجهول', 'صعب', 'الكتاب ص 137 — المثال 2: الطريق إلى المنزل')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
