insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, '$A_x = 10.0\cos 30.0^\circ = 8.66$، $A_y = 5.00$، $B_x = 6.0\cos 120.0^\circ = -3.00$، $B_y = 5.20$ ⇐ $R_x = 5.66\ \text{km}$، $R_y = 10.20\ \text{km}$ ⇐ $R = 11.7\ \text{km}$، $\theta = \tan^{-1}\left(\frac{10.20}{5.66}\right) = 61.0^\circ$.', '["استُعمل $\\sin\\theta$ للمركّبة x و$\\cos\\theta$ للمركّبة y، فانعكست المركّبتان وتغيرت الزاوية.","","عُدّت المركّبة $B_x$ موجبة، و$\\boldsymbol{B}$ في الربع الثاني فمركّبته x سالبة.","جُمع المقداران مباشرة وأُخذ متوسط الزاويتين، والمتجهات لا تُجمع هكذا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-20T17:53:29.925Z"}'::jsonb),
('mcq', 2, 3, '$R_x = 50.0 + 120.0\cos 60.0^\circ - 90.0 = 20.0\ \text{N}$، $R_y = 120.0\sin 60.0^\circ = 103.9\ \text{N}$ ⇐ $R = \sqrt{(20.0)^2 + (103.9)^2} = 106\ \text{N}$.', '["جُمعت مقادير القوى الثلاث مباشرة دون مراعاة اتجاهاتها.","عُدّت القوة 90.0 N موجبة، وهي في الاتجاه السالب للمحور x.","بُدّلت $\\sin$ و$\\cos$ عند تحليل القوة 120.0 N.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-20T17:53:29.925Z"}'::jsonb),
('mcq', 3, 0, '$R_x < 0$ و$R_y > 0$ فالمحصلة في الربع الثاني. الزاوية مع محور $-x$: $\tan^{-1}\left(\frac{8.0}{6.0}\right) = 53.1^\circ$، فاتجاهها $180^\circ - 53.1^\circ = 127^\circ$.', '["","هذه قراءة الآلة الحاسبة لـ $\\tan^{-1}(8.0/-6.0)$ دون مراعاة أن المتجه في الربع الثاني.","أُهملت إشارة $R_x$ فوُضعت المحصلة في الربع الأول.","قُلبت النسبة وأُهملت الإشارة معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-20T17:53:29.926Z"}'::jsonb),
('mcq', 4, 2, '$R_x = 12.0\cos 30.0^\circ = 10.39\ \text{km}$، $R_y = 6.00\ \text{km}$، $A_x = 4.0\ \text{km}$، $A_y = 0$ ⇐ $B_x = 6.39\ \text{km}$، $B_y = 6.00\ \text{km}$ ⇐ $B = \sqrt{(6.39)^2 + (6.00)^2} = 8.8\ \text{km}$.', '["طُرح المقداران مباشرة ($12.0 - 4.0$)، والإزاحتان مختلفتان في الاتجاه.","أُضيف $A_x$ إلى $R_x$ بدل طرحه، والصحيح $B_x = R_x - A_x$.","","طُبّقت فيثاغورس على المقدارين $\\sqrt{12.0^2 - 4.0^2}$ كأن الإزاحتين متعامدتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-20T17:53:29.926Z"}'::jsonb),
('mcq', 5, 1, 'المحصلة وتر: $R^2 = A^2 + B^2$ ⇐ $B = \sqrt{(10.0)^2 - (6.0)^2} = 8.0\ \text{km}$ شرقًا.', '["طُرح المقداران مباشرة، والإزاحتان متعامدتان.","","جُمع المقداران، و10.0 km هي المحصلة لا إحدى الإزاحتين.","جُمع المربعان $\\sqrt{10.0^2 + 6.0^2}$ كأن 10.0 km إحدى الإزاحتين لا الوتر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.927Z"}'::jsonb),
('mcq', 6, 3, 'المركّبتان الأفقيتان تُلغي إحداهما الأخرى. المركّبة الرأسية لكل حبل $3.10\cos 15.0^\circ = 2.99\ \text{N}$، فالمحصلة $2(3.10)\cos 15.0^\circ = 5.99\ \text{N}$ رأسيًّا إلى أعلى.', '["جُمع المقداران مباشرة، والحبلان مائلان فلا تُجمع إلا مركّبتاهما الرأسيتان.","استُعمل $\\sin 15.0^\\circ$ للمركّبة الرأسية، والزاوية مقيسة من الرأسي فالمركّبة الرأسية $F\\cos 15.0^\\circ$.","المركّبتان الأفقيتان متساويتان ومتعاكستان فتُلغيان، فالمحصلة رأسية لا أفقية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-20T17:53:29.927Z"}'::jsonb),
('mcq', 7, 0, '$R_x = 4 + 1 - 2 = 3.0\ \text{m}$، $R_y = 3 - 5 - 2 = -4.0\ \text{m}$ ⇐ $R = \sqrt{(3.0)^2 + (-4.0)^2} = 5.0\ \text{m}$.', '["","جُمعت أطوال الإزاحات الثلاث، وهذه هي المسافة المقطوعة لا مقدار الإزاحة.","جُمع $|R_x| + |R_y| = 3 + 4$ عدديًّا، والمركّبتان متعامدتان فتُجمعان بفيثاغورس.","جُمعت المركّبتان بإشارتيهما $3 + (-4)$، ولا يُجمع $R_x$ مع $R_y$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-20T17:53:29.927Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المركّبات: $\boldsymbol{A}$: (4.00، 0)؛ $\boldsymbol{B}$: $7.0\cos 60.0^\circ = 3.50$ و$7.0\sin 60.0^\circ = 6.06$؛ $\boldsymbol{C}$: $3.0\cos 150.0^\circ = -2.60$ و$3.0\sin 150.0^\circ = 1.50$. $R_x = 4.00 + 3.50 - 2.60 = 4.90\ \text{km}$، $R_y = 0 + 6.06 + 1.50 = 7.56\ \text{km}$. $R = \sqrt{(4.90)^2 + (7.56)^2} = 9.0\ \text{km}$، $\theta = \tan^{-1}\left(\frac{7.56}{4.90}\right) = 57.0^\circ$ مع محور $+x$.', '["تحليل الإزاحات الثلاث بالإشارات الصحيحة","$R_x$ = 4.90 km و$R_y$ = 7.56 km","R = 9.0 km","$\\theta$ = $57.0^\\circ$"]'::jsonb, '["$B_x = 3.50\\ \\text{km}$، $B_y = 6.06\\ \\text{km}$؛ $C_x = -2.60\\ \\text{km}$، $C_y = 1.50\\ \\text{km}$","$R_x = 4.90\\ \\text{km}$، $R_y = 7.56\\ \\text{km}$","$R = 9.0\\ \\text{km}$","$\\theta = 57.0^\\circ$"]'::jsonb, '[{"element":"التحليل","marks":1},{"element":"جمع المركّبات","marks":1},{"element":"المقدار","marks":1},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجتان","description":"عنصران صحيحان فقط أو طريقة صحيحة مع أخطاء متعددة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ $C_x$ موجبة","تبديل $\\sin$ و$\\cos$","جمع المقادير 14.0 km"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-20T17:53:29.927Z"}'::jsonb),
('essay', 2, null::int, null, null, '$F_{1x} = 24.0\cos 125.0^\circ = -13.77\ \text{N}$، $F_{1y} = 24.0\sin 125.0^\circ = 19.66\ \text{N}$؛ $F_{2x} = 21.0\cos 55.0^\circ = 12.05\ \text{N}$، $F_{2y} = 21.0\sin 55.0^\circ = 17.20\ \text{N}$؛ $F_{gx} = 0$، $F_{gy} = -20.0\ \text{N}$. $R_x = -1.72\ \text{N}$، $R_y = 16.86\ \text{N}$. $R = \sqrt{(-1.72)^2 + (16.86)^2} = 16.9\ \text{N}$. الآلة الحاسبة تعطي $\tan^{-1}\left(\frac{16.86}{-1.72}\right) = -84.2^\circ$، والمحصلة في الربع الثاني فاتجاهها $95.8^\circ$ مع محور $+x$ (أي إلى أعلى مع ميل قليل نحو اليسار).', '["تحليل القوى الثلاث بالإشارات","$R_x = -1.72\\ \\text{N}$ و$R_y = 16.86\\ \\text{N}$","R = 16.9 N","الاتجاه $95.8^\\circ$ مع تصحيح قراءة الآلة الحاسبة"]'::jsonb, '["$R_x = -13.77 + 12.05 + 0 = -1.72\\ \\text{N}$","$R_y = 19.66 + 17.20 - 20.0 = 16.86\\ \\text{N}$","$R = 16.9\\ \\text{N}$","$\\theta = 180^\\circ - 84.2^\\circ = 95.8^\\circ$"]'::jsonb, '[{"element":"تحليل القوى","marks":1},{"element":"المركّبتان","marks":1},{"element":"المقدار","marks":1},{"element":"الاتجاه في الربع الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجتان","description":"عنصران صحيحان فقط أو طريقة صحيحة مع أخطاء متعددة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان الوزن","عدّ الوزن موجبًا","كتابة الاتجاه $-84.2^\\circ$ دون مراعاة الربع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-20T17:53:29.928Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المحصلة: $R_x = 14.0\cos 125.0^\circ = -8.03\ \text{km}$، $R_y = 14.0\sin 125.0^\circ = 11.47\ \text{km}$. الإزاحة الأولى: $A_x = -6.0\ \text{km}$، $A_y = 0$. الإزاحة المجهولة: $B_x = R_x - A_x = -8.03 - (-6.0) = -2.03\ \text{km}$، $B_y = 11.47\ \text{km}$. $B = \sqrt{(-2.03)^2 + (11.47)^2} = 11.6\ \text{km}$. الآلة الحاسبة تعطي $\tan^{-1}\left(\frac{11.47}{-2.03}\right) = -80.0^\circ$، و$\boldsymbol{B}$ في الربع الثاني فاتجاهها $100.0^\circ$ مع محور $+x$، أي $10.0^\circ$ غرب الشمال.', '["مركّبتا المحصلة","طرح مركّبات الإزاحة الأولى بالإشارات","B = 11.6 km","الاتجاه $100.0^\\circ$ في الربع الثاني"]'::jsonb, '["$R_x = -8.03\\ \\text{km}$، $R_y = 11.47\\ \\text{km}$","$B_x = R_x - A_x = -2.03\\ \\text{km}$، $B_y = 11.47\\ \\text{km}$","$B = 11.6\\ \\text{km}$","$\\theta = 180^\\circ - 80.0^\\circ = 100.0^\\circ$"]'::jsonb, '[{"element":"مركّبتا المحصلة","marks":1},{"element":"مركّبتا المتجه المجهول","marks":1},{"element":"المقدار","marks":1},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجتان","description":"عنصران صحيحان فقط أو طريقة صحيحة مع أخطاء متعددة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب $B_x = R_x + A_x$","عدّ الإزاحة غربًا موجبة","الاكتفاء بقراءة الآلة الحاسبة $-80.0^\\circ$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-20T17:53:29.928Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C5-L1-O06') and x.type = v.type and x.number = v.number
