insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C5-L1-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'جُمعت ثلاث إزاحات مختلفة المقادير بطريقة الرسم، فوُضع ذيل كل منها عند رأس السابقة، فانتهى رأس الإزاحة الثالثة عند ذيل الإزاحة الأولى تمامًا مكوّنًا مثلثًا مغلقًا. ما الإزاحة المحصلة؟', null, null, '["طولها مجموع أطوال الأضلاع الثلاثة مضروبًا في مقياس الرسم","تساوي الإزاحة الثالثة لأنها آخر إزاحة رُسمت في المثلث","تساوي أطول الإزاحات الثلاث مقدارًا واتجاهًا","صفر؛ لأن ذيل الإزاحة الأولى ورأس الأخيرة عند النقطة نفسها"]'::jsonb, 'فهم', 'استنتاج من الرسم', 'متوسط', 'الكتاب ص 138 — مراجعة 5-1، السؤال 14'),
('mcq', 2, 'لجمع متجهين في بُعدين بطريقة الرسم، ما الذي تحتاج إليه لرسم كل متجه بطوله واتجاهه الصحيحين؟', null, null, '["مقياس رسم مناسب، ومسطرة لرسم الأطوال، ومنقلة لرسم الزوايا","مسطرة ومنقلة فقط، ويُرسم كل متجه بطول يساوي مقداره بالسنتيمترات","مقياس رسم ومسطرة فقط، لأن الزوايا تُحسب بالآلة الحاسبة","منقلة ومقياس رسم فقط، لأن طول المتجه لا يؤثر في المحصلة"]'::jsonb, 'تذكر', 'تذكر إجراء', 'سهل', 'الكتاب ص 132 — المتجهات في أبعاد متعددة'),
('mcq', 3, 'رُسم متجه طوله 15 mm ليمثّل سرعة مقدارها 30 m/s. كم يجب أن يكون طول المتجه الذي يمثّل سرعة مقدارها 20 m/s بمقياس الرسم نفسه؟', null, null, '["5 mm","20 mm","10 mm","40 mm"]'::jsonb, 'تطبيق', 'مقياس الرسم', 'متوسط', 'الكتاب ص 156 — الأسئلة 43–46 و56'),
('mcq', 4, 'يبين الشكل الأول المتجهين $\boldsymbol{A}$ و$\boldsymbol{B}$، ويبين الشكل الثاني أربعة رسوم لجمعهما بطريقة الرسم ($\boldsymbol{R}$ خط متقطع). أيّ رسم يمثّل المحصلة $\boldsymbol{R} = \boldsymbol{A} + \boldsymbol{B}$ تمثيلًا صحيحًا؟', null, '[{"src":"qimg/phys1/c5l1-o07-given.svg","alt":"شبكة مربعات عليها سهم أزرق أفقي A إلى اليمين طوله 4 مربعات، وإلى يمينه منفصلًا سهم أزرق B يتجه إلى أعلى بميل قليل إلى اليمين (مربع واحد أفقيًّا و3 مربعات رأسيًّا)."},{"src":"qimg/phys1/c5l1-o07-panels.svg","alt":"أربعة رسوم على شبكة مربعات معنونة الرسم 1 إلى الرسم 4. الرسم 1: A أفقي، ومن رأسه B، وR متقطع من ذيل A إلى رأس B ورأس سهمه عند رأس B. الرسم 2: الوضع نفسه لكن رأس سهم R المتقطع عند ذيل A. الرسم 3: A وB يبدآن من النقطة نفسها، وR متقطع من رأس A إلى رأس B. الرسم 4: A أفقي، ومن رأسه B مدوَّر يميل قليلًا عن الأفقي (3 مربعات أفقيًّا ومربع واحد رأسيًّا)، وR متقطع من ذيل A إلى رأس B."}]'::jsonb, '["الرسم 2","الرسم 1","الرسم 3","الرسم 4"]'::jsonb, 'فهم', 'تمييز الرسم الصحيح', 'متوسط', 'الكتاب ص 132 — جمع المتجهات بطريقة الرسم'),
('mcq', 5, 'جُمعت إزاحتان بطريقة الرسم على شبكة مربعات كما في الشكل الآتي (ضلع المربع يمثّل 10 m). إذا قيس طول المحصلة بالمسطرة، فما مقدار الإزاحة المحصلة؟', null, '[{"src":"qimg/phys1/c5l1-o07-measure.svg","alt":"شبكة مربعات مكتوب فيها: ضلع المربع = 10 m. نقطة بداية، ومنها سهم أخضر A أفقي إلى اليمين طوله 5 مربعات، ومن رأسه سهم أخضر B يتجه إلى أعلى اليسار: مربعين إلى اليسار و4 مربعات إلى أعلى. لا تظهر المحصلة."}]'::jsonb, '["50 m","95 m","70 m","5.0 m"]'::jsonb, 'تطبيق', 'قياس المحصلة من رسم بمقياس', 'متوسط', 'الكتاب ص 132 — جمع المتجهات بطريقة الرسم'),
('mcq', 6, 'يبين الشكل الآتي متجهين $\boldsymbol{A}$ و$\boldsymbol{B}$ على شبكة مربعات، وُضع ذيل $\boldsymbol{B}$ عند رأس $\boldsymbol{A}$ وذيل $\boldsymbol{A}$ عند نقطة الأصل. إذا رُسمت المحصلة وقيس اتجاهها بالمنقلة من محور $+x$ في عكس اتجاه حركة عقارب الساعة، فكم يكون تقريبًا؟', null, '[{"src":"qimg/phys1/c5l1-o07-protractor.svg","alt":"شبكة مربعات ومحوران +x و+y. سهم أزرق A من نقطة الأصل على محور +x طوله مربعان، ومن رأسه سهم أزرق B يتجه إلى أعلى اليسار وينتهي عند النقطة التي تبعد مربعين يسار المحور y و3 مربعات فوق المحور x. لا تظهر المحصلة."}]'::jsonb, '["$56^\\circ$","$34^\\circ$","$146^\\circ$","$124^\\circ$"]'::jsonb, 'تطبيق', 'قياس اتجاه المحصلة', 'صعب', 'الكتاب ص 132 — جمع المتجهات بطريقة الرسم'),
('mcq', 7, 'رُسمت الإزاحة $\boldsymbol{A}$ نحو الشمال على ورقة رسم بياني محورها $+x$ نحو الشرق. يُراد أن تُجمع معها بطريقة الرسم الإزاحة $\boldsymbol{B}$ التي تتجه $30^\circ$ شمال الشرق. كيف تُرسم $\boldsymbol{B}$؟', null, null, '["يوضع ذيلها عند رأس $\\boldsymbol{A}$، وتُقاس $30^\\circ$ بالمنقلة من اتجاه $\\boldsymbol{A}$ نفسه","يوضع ذيلها عند ذيل $\\boldsymbol{A}$، وتُقاس $30^\\circ$ من محور $+x$ في عكس اتجاه حركة عقارب الساعة","يوضع ذيلها عند رأس $\\boldsymbol{A}$، وتُقاس $30^\\circ$ من خط موازٍ لمحور $+x$ في عكس اتجاه حركة عقارب الساعة","يوضع ذيلها عند رأس $\\boldsymbol{A}$، وتُقاس $30^\\circ$ من خط موازٍ لمحور $+x$ في اتجاه حركة عقارب الساعة"]'::jsonb, 'تطبيق', 'رسم متجه بالمنقلة', 'متوسط', 'الكتاب ص 132، 134 — الجمع بالرسم وقياس الاتجاه'),
('essay', 1, 'صف كيف يمكن جمع متجهين غير متعامدين في بُعدين بطريقة الرسم، وإيجاد مقدار المحصلة واتجاهها، مع ذكر الأدوات المستعملة.', null, null, null, 'فهم', 'وصف إجراء', 'سهل', 'الكتاب ص 156 — الأسئلة 43–46 و56'),
('essay', 2, 'مشى رجل 40 m جنوبًا، ثم 30 m شرقًا. (أ) باستعمال مقياس رسم 1 cm لكل 10 m، صف كيف ترسم الإزاحتين والمحصلة، واذكر طول كل سهم على الرسم، والطول المتوقع للمحصلة على الرسم. (ب) تحقق من مقدار الإزاحة المحصلة حسابيًّا، وحدّد اتجاهها.', null, null, null, 'تطبيق', 'الرسم مع التحقق الحسابي', 'صعب', 'الكتاب ص 157 — السؤالان 60 و61'),
('essay', 3, 'يبين الشكل الآتي ثلاث إزاحات $\boldsymbol{A}$ و$\boldsymbol{B}$ و$\boldsymbol{C}$ مرسومة متفرقة على شبكة مربعات، ضلع المربع فيها يمثّل 2.0 m. (أ) صف كيف تجمعها بطريقة الرسم. (ب) حدّد من الشبكة مركّبتي المحصلة بالمربعات، ثم احسب مقدار الإزاحة المحصلة بالأمتار واتجاهها مع محور $+x$ (الأفقي نحو اليمين).', null, '[{"src":"qimg/phys1/c5l1-o07-e3.svg","alt":"شبكة مربعات مكتوب فيها: ضلع المربع = 2.0 m. ثلاثة أسهم خضراء متفرقة: A يتجه 3 مربعات إلى اليمين ومربعًا واحدًا إلى أعلى، وB يتجه مربعًا واحدًا إلى اليسار و3 مربعات إلى أعلى، وC يتجه مربعين إلى اليمين ومربعًا واحدًا إلى أسفل. لا تظهر المحصلة."}]'::jsonb, null, 'تطبيق', 'جمع ثلاثة متجهات بالرسم', 'صعب', 'الكتاب ص 157 — السؤالان 60 و61')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C5-L1-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'المحصلة تُرسم من ذيل الإزاحة الأولى إلى رأس الإزاحة الأخيرة، وفي المثلث المغلق يقع ذيل الإزاحة الأولى ورأس الأخيرة عند النقطة نفسها، فالمحصلة صفر؛ أي أن الجسم عاد إلى نقطة بدايته مع أن الإزاحات غير متساوية المقادير.', '["هذا مجموع الأطوال، أي المسافة الكلية المقطوعة، لا مقدار الإزاحة المحصلة.","الإزاحة الأخيرة أحد المتجهات المجموعة؛ والمحصلة تُرسم من ذيل الأول إلى رأس الأخير.","لا تساوي المحصلة أيًّا من المتجهات المجموعة؛ فهي تبدأ من ذيل الأول وتنتهي عند رأس الأخير، وهما منطبقان هنا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-20T17:53:29.929Z"}'::jsonb),
('mcq', 2, 0, 'يُرسم كل متجه بطول يمثّل مقداره وفق مقياس رسم مناسب (بالمسطرة)، وبالزاوية الصحيحة (بالمنقلة)، ثم يُقاس طول المحصلة بالمسطرة واتجاهها بالمنقلة.', '["","يلزم اختيار مقياس رسم مناسب يحوّل المقدار إلى طول يتسع له الورق؛ فإزاحة 125 km مثلًا لا تُرسم بطول 125 cm.","في طريقة الرسم تُرسم الزوايا وتُقاس بالمنقلة؛ أما حسابها بالآلة الحاسبة فهو من الطريقة الجبرية.","طول المتجه يمثّل مقداره، فيجب رسمه بالمسطرة بدقة وإلا تغيّرت المحصلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.929Z"}'::jsonb),
('mcq', 3, 2, 'المقياس: $\frac{15\ \text{mm}}{30\ \text{m/s}} = 0.50\ \text{mm}$ لكل 1 m/s، فطول المتجه $20 \times 0.50 = 10\ \text{mm}$.', '["طُرح الفرق بين السرعتين (10) من الطول 15 mm، والمقياس نسبة لا فرق.","افتُرض أن كل 1 mm يمثّل 1 m/s، والمقياس هنا 1 mm لكل 2 m/s.","","قُلبت النسبة فضُرب في 2 بدل القسمة على 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-20T17:53:29.929Z"}'::jsonb),
('mcq', 4, 1, 'في الرسم 1 نُقل $\boldsymbol{B}$ دون تغيير طوله واتجاهه فصار ذيله عند رأس $\boldsymbol{A}$، ورُسم $\boldsymbol{R}$ من ذيل $\boldsymbol{A}$ إلى رأس $\boldsymbol{B}$.', '["وُضع $\\boldsymbol{B}$ صحيحًا، لكن رأس سهم $\\boldsymbol{R}$ عند ذيل $\\boldsymbol{A}$؛ فاتجاه المحصلة معكوس.","","وُضع ذيلا المتجهين عند نقطة واحدة ورُسم $\\boldsymbol{R}$ من رأس $\\boldsymbol{A}$ إلى رأس $\\boldsymbol{B}$، وهذا يمثّل $\\boldsymbol{B} - \\boldsymbol{A}$.","دُوِّر المتجه $\\boldsymbol{B}$ فتغيّر اتجاهه، فصار يمثّل متجهًا آخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-20T17:53:29.930Z"}'::jsonb),
('mcq', 5, 0, 'المحصلة من ذيل $\boldsymbol{A}$ (نقطة البداية) إلى رأس $\boldsymbol{B}$: 3 مربعات أفقيًّا و4 رأسيًّا، فطولها 5 مربعات، وبمقياس الرسم $5 \times 10 = 50\ \text{m}$.', '["","جُمع طولا الإزاحتين (50 m و45 m تقريبًا)، وهذا المسافة الكلية لا الإزاحة المحصلة.","عُدّت المربعات أفقيًّا ورأسيًّا وجُمعت ($3 + 4 = 7$ مربعات)، والمحصلة خط مائل يُقاس طوله مباشرة.","قيس طول المحصلة بالمربعات (5 مربعات) ولم يُضرب في مقياس الرسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-20T17:53:29.930Z"}'::jsonb),
('mcq', 6, 3, 'المحصلة من الأصل إلى رأس $\boldsymbol{B}$: مربعان إلى اليسار و3 مربعات إلى أعلى، أي في الربع الثاني. زاويتها مع محور $-x$ هي $\tan^{-1}\left(\frac{3}{2}\right) = 56^\circ$، فاتجاهها $180^\circ - 56^\circ = 124^\circ$.', '["هذه الزاوية بين المحصلة ومحور $-x$؛ والمحصلة في الربع الثاني فتُقاس من محور $+x$.","هذه الزاوية بين المحصلة ومحور $+y$، لا مع محور $+x$.","قيست الزاوية مع محور $+y$ ثم طُرحت من $180^\\circ$، فالقياس من المحور الخطأ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.931Z"}'::jsonb),
('mcq', 7, 2, 'يُنقل $\boldsymbol{B}$ دون تغيير اتجاهه فيوضع ذيله عند رأس $\boldsymbol{A}$، واتجاهه $30^\circ$ شمال الشرق يعني زاوية $30^\circ$ فوق خط يوازي محور $+x$ (الشرق) مقيسة في عكس اتجاه حركة عقارب الساعة، ثم يُرسم بطول يمثّل مقداره بمقياس الرسم.', '["اتجاه $\\boldsymbol{A}$ هو الشمال، فقياس $30^\\circ$ منه يعطي اتجاهًا $30^\\circ$ شرق الشمال لا شمال الشرق؛ والاتجاه يُقاس من خط يوازي محور $+x$.","هذا رسم للمتجهين من نقطة واحدة؛ وفي الجمع بالرسم يوضع ذيل $\\boldsymbol{B}$ عند رأس $\\boldsymbol{A}$.","","القياس من الشرق في اتجاه حركة عقارب الساعة يعطي اتجاهًا $30^\\circ$ جنوب الشرق لا شماله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-20T17:53:29.931Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) نختار مقياس رسم مناسبًا. 2) نرسم المتجه الأول بطول يمثّل مقداره وبالزاوية الصحيحة مستعملين المسطرة والمنقلة. 3) نرسم المتجه الثاني بحيث يكون ذيله عند رأس الأول، بالطول والاتجاه الصحيحين. 4) نرسم المحصلة من ذيل المتجه الأول إلى رأس المتجه الثاني. 5) نقيس طول المحصلة بالمسطرة ونحوّله بمقياس الرسم إلى مقدار، ونقيس اتجاهها بالمنقلة.', '["اختيار مقياس رسم","رسم المتجهين رأسًا لذيل بالطول والزاوية الصحيحين","رسم المحصلة من ذيل الأول إلى رأس الأخير","قياس الطول بالمسطرة والاتجاه بالمنقلة"]'::jsonb, '[]'::jsonb, '[{"element":"مقياس الرسم","marks":1},{"element":"الرسم رأسًا لذيل","marks":1},{"element":"رسم المحصلة","marks":1},{"element":"القياس بالمسطرة والمنقلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجتان","description":"عنصران صحيحان فقط أو طريقة صحيحة مع أخطاء متعددة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم المحصلة من رأس الأول إلى رأس الثاني","إهمال مقياس الرسم","تدوير المتجه عند نقله"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-20T17:53:29.931Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) نرسم سهمًا طوله 4.0 cm نحو الجنوب، ومن رأسه سهمًا طوله 3.0 cm نحو الشرق، ثم نرسم المحصلة من ذيل الأول إلى رأس الثاني؛ يُتوقع أن يكون طولها 5.0 cm، أي 50 m. ونقيس بالمنقلة زاويتها. (ب) $R = \sqrt{(40)^2 + (30)^2} = 50\ \text{m}$، وزاويتها مع الجنوب $\tan^{-1}\left(\frac{30}{40}\right) = 36.9^\circ$ نحو الشرق (أي $36.9^\circ$ شرق الجنوب).', '["أطوال الأسهم 4.0 cm و3.0 cm بالاتجاهين الصحيحين","رسم المحصلة وطولها 5.0 cm","R = 50 m حسابيًّا","الاتجاه $36.9^\\circ$ شرق الجنوب"]'::jsonb, '["$40\\ \\text{m} \\div 10 = 4.0\\ \\text{cm}$، $30\\ \\text{m} \\div 10 = 3.0\\ \\text{cm}$","$R = \\sqrt{1600 + 900} = 50\\ \\text{m}$ (5.0 cm على الرسم)","$\\theta = \\tan^{-1}\\left(\\frac{30}{40}\\right) = 36.9^\\circ$ شرق الجنوب"]'::jsonb, '[{"element":"تحويل الأطوال بالمقياس","marks":1},{"element":"وصف الرسم والمحصلة","marks":1},{"element":"المقدار حسابيًّا","marks":1},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجتان","description":"عنصران صحيحان فقط أو طريقة صحيحة مع أخطاء متعددة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم المحصلة من رأس الأول إلى رأس الثاني","كتابة الاتجاه $53.1^\\circ$ شرق الجنوب بقلب النسبة","جمع المقدارين 70 m"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-20T17:53:29.932Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) ننقل $\boldsymbol{B}$ دون تدوير أو تغيير طوله حتى يصبح ذيله عند رأس $\boldsymbol{A}$، ثم ننقل $\boldsymbol{C}$ حتى يصبح ذيله عند رأس $\boldsymbol{B}$، ونرسم المحصلة من ذيل $\boldsymbol{A}$ إلى رأس $\boldsymbol{C}$. (ب) $\boldsymbol{A}$: 3 مربعات يمينًا و1 لأعلى؛ $\boldsymbol{B}$: 1 يسارًا و3 لأعلى؛ $\boldsymbol{C}$: 2 يمينًا و1 لأسفل. المحصلة: $3 - 1 + 2 = 4$ مربعات أفقيًّا و$1 + 3 - 1 = 3$ مربعات رأسيًّا، فطولها $\sqrt{4^2 + 3^2} = 5$ مربعات، أي $5 \times 2.0 = 10.0\ \text{m}$، واتجاهها $\tan^{-1}\left(\frac{3}{4}\right) = 36.9^\circ$ فوق محور $+x$.', '["وصف النقل رأسًا لذيل دون تدوير","قراءة مركّبات كل إزاحة بالإشارات","المحصلة 5 مربعات = 10.0 m","الاتجاه $36.9^\\circ$"]'::jsonb, '["$R_x = 3 - 1 + 2 = 4$ مربعات، $R_y = 1 + 3 - 1 = 3$ مربعات","$R = 5$ مربعات $= 10.0\\ \\text{m}$","$\\theta = \\tan^{-1}\\left(\\frac{3}{4}\\right) = 36.9^\\circ$"]'::jsonb, '[{"element":"وصف طريقة الرسم","marks":1},{"element":"قراءة المركّبات","marks":1},{"element":"المقدار بالأمتار","marks":1},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجتان","description":"عنصران صحيحان فقط أو طريقة صحيحة مع أخطاء متعددة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان ضرب عدد المربعات في 2.0 m","عدّ الإزاحة C صاعدة","جمع أطوال الإزاحات الثلاث"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-20T17:53:29.932Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
