('mcq', 2, 'يؤثر خيط في صندوق بقوة مقدارها 25.0 N تميل على الأفقي بزاوية $40.0^\circ$. ما مقدار المركّبة الأفقية لهذه القوة؟', null, null, '["$16.1\\ \\text{N}$","$32.6\\ \\text{N}$","$19.2\\ \\text{N}$","$-16.7\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب مركّبة أفقية', 'سهل', 'الكتاب ص 159 — اختبار مقنن: السؤالان 4 و5'),
('mcq', 3, 'يبين الشكل الآتي إزاحة $\boldsymbol{A}$ مقدارها 12.0 m تصنع $30.0^\circ$ مع محور $+x$، ومركّبتيها (الخطان المتقطعان). ما مقدار المركّبة $A_x$؟', null, '[{"src":"qimg/phys1/c5l1-o08-angle.svg","alt":"محوران +x و+y. سهم أخضر A من نقطة الأصل مائل إلى أعلى اليمين مكتوب عنده 12.0 m، وقوس بينه وبين محور +x مكتوب عنده 30.0°. خط متقطع أخضر على محور x من الأصل إلى أسفل رأس A، وخط متقطع رأسي من محور x إلى رأس A."}]'::jsonb, '["6.0 m","13.9 m","12.0 m","10.4 m"]'::jsonb, 'تطبيق', 'حساب مركّبة من رسم', 'سهل', 'الكتاب ص 135 — حساب المركّبتين بجيب الزاوية وجيب تمامها'),
('mcq', 4, 'المتجه $\boldsymbol{M}$ مقداره 5.0 ويصنع زاوية $37.0^\circ$ مع محور $+x$. ما مركّبتاه؟', null, null, '["$M_x = 3.0$ و$M_y = 4.0$","$M_x = 4.0$ و$M_y = 3.0$","$M_x = 5.0$ و$M_y = 5.0$","$M_x = 4.0$ و$M_y = 1.0$"]'::jsonb, 'تطبيق', 'تحليل متجه', 'متوسط', 'الكتاب ص 138 — مراجعة 5-1: السؤالان 7 و11'),
('mcq', 5, 'تسير سيارة بسرعة 50 km/h في اتجاه $60^\circ$ شمال الشرق، والمحور $+x$ نحو الشرق و$+y$ نحو الشمال. أيّ مركّبتي متجه السرعة أكبر؟', null, null, '["المركّبة x (نحو الشرق) وتساوي 43 km/h تقريبًا","المركّبتان متساويتان وتساوي كل منهما 25 km/h تقريبًا","المركّبة y (نحو الشمال) وتساوي 43 km/h تقريبًا","المركّبة x (نحو الشرق) وتساوي 50 km/h"]'::jsonb, 'تطبيق', 'مقارنة مركّبتين', 'متوسط', 'الكتاب ص 156 — السؤالان 58 و59'),
('mcq', 6, 'تؤثر القوة $\boldsymbol{F}$ المبينة في الشكل الآتي في جسم، ومقدارها 40.0 N، وتصنع $25.0^\circ$ مع الرأسي (محور $+y$). ما مقدار مركّبتها الأفقية؟', null, '[{"src":"qimg/phys1/c5l1-o08-vertical.svg","alt":"محوران +x و+y ونقطة عند الأصل. سهم أزرق F من النقطة مائل إلى أعلى اليمين مكتوب بجانبه 40.0 N، وقوس بين محور +y والسهم مكتوب عنده 25.0°."}]'::jsonb, '["16.9 N","36.3 N","18.7 N","44.1 N"]'::jsonb, 'تحليل', 'تحليل متجه زاويته مقيسة من الرأسي', 'صعب', 'الكتاب ص 135 — حساب المركّبتين بجيب الزاوية وجيب تمامها'),
('mcq', 7, 'قُذفت كرة بسرعة متجهة مقدارها 18.0 m/s بزاوية $50.0^\circ$ فوق الأفقي كما في الشكل الآتي. ما المركّبتان الأفقية والرأسية لسرعتها المتجهة الابتدائية؟', null, '[{"src":"qimg/phys1/c5l1-o08-velocity.svg","alt":"كرة عند نقطة الأصل لمحورين +x و+y، ومنها سهم أحمر v مائل إلى أعلى اليمين مكتوب بجانبه 18.0 m/s، وقوس بينه وبين محور +x مكتوب عنده 50.0°."}]'::jsonb, '["$v_x = 13.8\\ \\text{m/s}$ و$v_y = 11.6\\ \\text{m/s}$","$v_x = 9.0\\ \\text{m/s}$ و$v_y = 9.0\\ \\text{m/s}$","$v_x = 17.4\\ \\text{m/s}$ و$v_y = -4.7\\ \\text{m/s}$","$v_x = 11.6\\ \\text{m/s}$ و$v_y = 13.8\\ \\text{m/s}$"]'::jsonb, 'تطبيق', 'تحليل سرعة متجهة', 'متوسط', 'الكتاب ص 135 — حساب المركّبتين بجيب الزاوية وجيب تمامها'),
('essay', 1, 'حلّل كلًّا من المتجهات الآتية إلى مركّبتيه الأفقية والرأسية (الزوايا مقيسة من محور $+x$ في عكس اتجاه حركة عقارب الساعة): (أ) قوة $\boldsymbol{F}$ مقدارها 20.0 N بزاوية $35.0^\circ$. (ب) إزاحة $\boldsymbol{d}$ مقدارها 12.0 m بزاوية $90.0^\circ$. (ج) إزاحة $\boldsymbol{C}$ مقدارها 8.0 km بزاوية $0^\circ$.', null, null, null, 'تطبيق', 'تحليل متجهات', 'متوسط', 'الكتاب ص 156 — السؤالان 58 و59'),
('essay', 2, 'يسحب شخصان صندوقًا بحبلين: الأول بقوة $\boldsymbol{F}_1$ مقدارها 18.5 N في اتجاه يصنع $115.0^\circ$ مع محور $+x$، والثاني بقوة $\boldsymbol{F}_2$ مقدارها 16.0 N في اتجاه يصنع $50.0^\circ$ مع محور $+x$. (أ) حلّل كل قوة إلى مركّبتيها مع الإشارات. (ب) تحقّق من صحة تحليل كل قوة باستعمال نظرية فيثاغورس.', null, null, null, 'تطبيق', 'تحليل قوتين مع التحقق', 'صعب', 'الكتاب ص 138 — مراجعة 5-1: السؤالان 7 و11'),
('essay', 3, 'هل يمكن أن يكون مقدار متجه أقل من مقدار إحدى مركّبتيه أو مساويًا له؟ وضّح إجابتك بالاعتماد على العلاقتين $A_x = A\cos\theta$ و$A_y = A\sin\theta$، واذكر مثالًا لحالة التساوي.', null, null, null, 'تحليل', 'استدلال وتعليل', 'صعب', 'الكتاب ص 138 — مراجعة 5-1: السؤالان 7 و11')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
