from (values
('mcq', 1, 0, '$F_y = F\sin\theta = (64.0\ \text{N})\sin 38.0^\circ = 39.4\ \text{N}$.', '["","هذه المركّبة الأفقية $F\\cos 38.0^\\circ$؛ والمركّبة الرأسية تُحسب بـ $F\\sin\\theta$.","قُسم المقدار على $\\sin 38.0^\\circ$ بدل الضرب فيه، والمركّبة لا تكون أكبر من المتجه.","ضُبطت الآلة الحاسبة على الراديان فحُسب $\\sin(38.0\\ \\text{rad})$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-20T17:53:29.933Z"}'::jsonb),
('mcq', 2, 2, '$F_x = F\cos\theta = (25.0\ \text{N})\cos 40.0^\circ = 19.2\ \text{N}$.', '["استُعمل $\\sin 40.0^\\circ$، وهذه المركّبة الرأسية.","قُسم المقدار على $\\cos 40.0^\\circ$ بدل الضرب فيه.","","ضُبطت الآلة الحاسبة على الراديان، فحُسب $\\cos(40.0\\ \\text{rad})$ وهو سالب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-20T17:53:29.933Z"}'::jsonb),
('mcq', 3, 3, '$A_x = A\cos\theta = (12.0\ \text{m})\cos 30.0^\circ = 10.4\ \text{m}$.', '["هذه المركّبة $A_y = A\\sin 30.0^\\circ$.","قُسم المقدار على $\\cos 30.0^\\circ$؛ والمركّبة أقصر من الوتر دائمًا.","عُدّت المركّبة مساوية للمتجه، والمتجه مائل فمركّبته الأفقية أقصر منه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-20T17:53:29.933Z"}'::jsonb),
('mcq', 4, 1, '$M_x = 5.0\cos 37.0^\circ = 4.0$، $M_y = 5.0\sin 37.0^\circ = 3.0$؛ وللتحقق: $\sqrt{4.0^2 + 3.0^2} = 5.0$.', '["بُدّلت العلاقتان: $M_x = M\\cos\\theta$ و$M_y = M\\sin\\theta$.","","كل مركّبة أقصر من المتجه المائل، ولا تساويه.","حُسبت $M_y$ بطرح $M_x$ من المقدار، والمركّبتان لا تُجمعان عدديًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-20T17:53:29.934Z"}'::jsonb),
('mcq', 5, 2, '$v_x = 50\cos 60^\circ = 25\ \text{km/h}$، $v_y = 50\sin 60^\circ = 43\ \text{km/h}$؛ فالمركّبة الشمالية أكبر لأن الزاوية مع الشرق أكبر من $45^\circ$.', '["الزاوية $60^\\circ$ مقيسة من الشرق، فالمركّبة الشرقية $50\\cos 60^\\circ = 25\\ \\text{km/h}$ هي الأصغر.","تتساوى المركّبتان فقط عند $45^\\circ$، والزاوية هنا $60^\\circ$.","","المركّبة لا تساوي مقدار المتجه المائل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-20T17:53:29.934Z"}'::jsonb),
('mcq', 6, 0, 'الزاوية مع محور x هي $90^\circ - 25.0^\circ = 65.0^\circ$، فـ $F_x = 40.0\cos 65.0^\circ = 40.0\sin 25.0^\circ = 16.9\ \text{N}$.', '["","استُعمل $\\cos 25.0^\\circ$ للمركّبة الأفقية؛ لكن الزاوية مقيسة من الرأسي، فهذه هي المركّبة الرأسية.","استُعمل $\\tan 25.0^\\circ$، والمركّبة تُحسب بضرب المقدار في جيب الزاوية أو جيب تمامها.","قُسم المقدار على $\\cos 25.0^\\circ$؛ والمركّبة لا تكون أكبر من المتجه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-20T17:53:29.934Z"}'::jsonb),
('mcq', 7, 3, '$v_x = 18.0\cos 50.0^\circ = 11.6\ \text{m/s}$، $v_y = 18.0\sin 50.0^\circ = 13.8\ \text{m/s}$.', '["بُدّل $\\sin$ و$\\cos$؛ فالمركّبة الأفقية $v\\cos\\theta$.","قُسم المقدار مناصفة؛ والمركّبتان لا تُجمعان عدديًّا ولا تتساويان إلا عند $45^\\circ$.","ضُبطت الآلة الحاسبة على الراديان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-20T17:53:29.935Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) $F_x = 20.0\cos 35.0^\circ = 16.4\ \text{N}$، $F_y = 20.0\sin 35.0^\circ = 11.5\ \text{N}$. (ب) $d_x = 12.0\cos 90.0^\circ = 0$، $d_y = 12.0\sin 90.0^\circ = 12.0\ \text{m}$. (ج) $C_x = 8.0\cos 0^\circ = 8.0\ \text{km}$، $C_y = 8.0\sin 0^\circ = 0$.', '["مركّبتا F: 16.4 N و11.5 N","مركّبتا d: 0 و12.0 m","مركّبتا C: 8.0 km و0"]'::jsonb, '["$F_x = F\\cos\\theta = 16.4\\ \\text{N}$، $F_y = F\\sin\\theta = 11.5\\ \\text{N}$","$d_x = 0$، $d_y = 12.0\\ \\text{m}$","$C_x = 8.0\\ \\text{km}$، $C_y = 0$"]'::jsonb, '[{"element":"المتجه (أ)","marks":1},{"element":"المتجه (ب)","marks":1},{"element":"المتجه (ج)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"درجتان","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل $\\sin$ و$\\cos$","عدّ مركّبة المتجه الرأسي الأفقية مساوية لمقداره","الآلة الحاسبة على الراديان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-20T17:53:29.935Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $F_{1x} = 18.5\cos 115.0^\circ = -7.82\ \text{N}$، $F_{1y} = 18.5\sin 115.0^\circ = 16.77\ \text{N}$؛ $F_{2x} = 16.0\cos 50.0^\circ = 10.28\ \text{N}$، $F_{2y} = 16.0\sin 50.0^\circ = 12.26\ \text{N}$. المركّبة $F_{1x}$ سالبة لأن $\boldsymbol{F}_1$ في الربع الثاني. (ب) $\sqrt{(-7.82)^2 + (16.77)^2} = 18.5\ \text{N}$ و$\sqrt{(10.28)^2 + (12.26)^2} = 16.0\ \text{N}$، فالتحليل صحيح.', '["مركّبتا $\\boldsymbol{F}_1$ بالإشارة السالبة لـ $F_{1x}$","مركّبتا $\\boldsymbol{F}_2$","التحقق بفيثاغورس للقوتين"]'::jsonb, '["$F_{1x} = -7.82\\ \\text{N}$، $F_{1y} = 16.77\\ \\text{N}$","$F_{2x} = 10.28\\ \\text{N}$، $F_{2y} = 12.26\\ \\text{N}$","$F_1 = \\sqrt{F_{1x}^2 + F_{1y}^2} = 18.5\\ \\text{N}$، $F_2 = 16.0\\ \\text{N}$"]'::jsonb, '[{"element":"تحليل $\\boldsymbol{F}_1$ مع الإشارة","marks":1},{"element":"تحليل $\\boldsymbol{F}_2$","marks":1},{"element":"التحقق","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"درجتان","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة $F_{1x}$ موجبة","استعمال الزاوية مع محور $-x$ ($65.0^\\circ$) مع $\\cos$ دون إشارة","جمع المركّبات بدل التحقق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-20T17:53:29.935Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لا يمكن أن يكون أقل؛ لأن $|\cos\theta| \le 1$ و$|\sin\theta| \le 1$ فيكون $|A_x| \le A$ و$|A_y| \le A$، كما أن المتجه وتر المثلث القائم المكوَّن من مركّبتيه. ويمكن أن يساوي إحدى مركّبتيه عندما تكون المركّبة الأخرى صفرًا، أي عندما يقع المتجه على أحد المحورين ($\theta = 0^\circ$ أو $90^\circ$ أو $180^\circ$ أو $270^\circ$)؛ مثل إزاحة 5.0 m نحو الشرق: $A_x = 5.0\ \text{m}$ و$A_y = 0$.', '["لا يكون أقل مع التعليل بحدود $\\sin$ و$\\cos$ أو الوتر","يساويها عندما تنعدم المركّبة الأخرى","مثال صحيح لحالة التساوي"]'::jsonb, '[]'::jsonb, '[{"element":"نفي إمكان كونه أقل مع التعليل","marks":1},{"element":"شرط التساوي","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"درجتان","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المركّبة قد تكون أكبر عند الزوايا الكبيرة","إهمال حالة المتجه الواقع على أحد المحورين","الخلط بين المقدار والإشارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-20T17:53:29.935Z"}'::jsonb)
