from (values
('mcq', 1, 'ما المقصود بمركّبتي المتجه؟', null, null, '["متجهان متساويان في المقدار يُجمعان معًا فيكوّنان المتجه الأصلي","متجهان يوازي أحدهما المحور x والآخر المحور y، ومجموعهما المتجه الأصلي","مقدار المتجه واتجاهه مقيسًا من محور x الموجب في عكس اتجاه عقارب الساعة","متجهان يوازيان المتجه الأصلي، ومجموع مقداريهما يساوي مقداره"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 134 — مركّبات المتجهات وتحليل المتجه'),
('mcq', 2, 'ماذا تُسمّى عملية تجزئة المتجه إلى مركّبتيه؟', null, null, '["جمع المتجهات جبريًّا","زاوية المتجه المحصل","جمع المتجهات بالرسم","تحليل المتجه"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 134 — مركّبات المتجهات وتحليل المتجه'),
('mcq', 3, 'ما المقصود بزاوية المتجه المحصل؟', null, null, '["الظل العكسي لخارج قسمة المركّبة y على المركّبة x للمتجه المحصل","الظل العكسي لخارج قسمة المركّبة x على المركّبة y للمتجه المحصل","الزاوية المحصورة بين المتجهين المجموعين في مثلث الجمع","معكوس جيب تمام خارج قسمة المركّبة y على مقدار المتجه المحصل"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'صعب', 'الكتاب ص 136 — زاوية المتجه المحصل'),
('mcq', 4, 'في المعادلة المتجهة $\boldsymbol{A} = \boldsymbol{A}_x + \boldsymbol{A}_y$، ماذا يمثّل $\boldsymbol{A}_x$؟', null, null, '["مركّبة المتجه $\\boldsymbol{A}$ الموازية للمحور y","الزاوية التي يصنعها $\\boldsymbol{A}$ مع المحور x","مركّبة المتجه $\\boldsymbol{A}$ الموازية للمحور x","المتجه المحصل للمتجهين $\\boldsymbol{A}$ و$\\boldsymbol{A}_y$"]'::jsonb, 'تذكر', 'تحديد مدلول رمز', 'متوسط', 'الكتاب ص 134 — مركّبات المتجهات وتحليل المتجه'),
('mcq', 5, 'يبين الشكل الآتي متجهًا $\boldsymbol{A}$ يصنع الزاوية $\theta$ مع محور $+x$، وسهمين متقطعين رُقّما (1) و(2). ماذا يُسمّى السهم المتقطع (2)؟', null, '[{"src":"qimg/phys1/c5l1-o09-labels.svg","alt":"محوران +x و+y. سهم أزرق A من نقطة الأصل مائل إلى أعلى اليمين، وقوس بينه وبين محور +x مكتوب عنده θ. سهم أزرق متقطع على محور x من الأصل إلى أسفل رأس A مكتوب تحته (1)، وسهم أزرق متقطع رأسي من نهاية السهم (1) إلى رأس A مكتوب بجانبه (2)."}]'::jsonb, '["المركّبة الرأسية $\\boldsymbol{A}_y$","المركّبة الأفقية $\\boldsymbol{A}_x$","المتجه المحصل $\\boldsymbol{R}$","المتجه $\\boldsymbol{A}$ بعد تحريكه"]'::jsonb, 'تذكر', 'تعرّف مصطلح من رسم', 'سهل', 'الكتاب ص 134 — مركّبات المتجهات وتحليل المتجه'),
('mcq', 6, 'ما الشكل الذي يكوّنه المتجه الأصلي مع مركّبتيه؟', null, null, '["مثلثًا قائم الزاوية تكون المركّبة الأفقية وتره","مثلثًا متساوي الأضلاع أضلاعه الثلاثة متساوية","مثلثًا منفرج الزاوية يقابل المتجه فيه الزاوية المنفرجة","مثلثًا قائم الزاوية يكون المتجه الأصلي وتره"]'::jsonb, 'فهم', 'علاقة المتجه بمركّبتيه', 'متوسط', 'الكتاب ص 134 — مركّبات المتجهات وتحليل المتجه'),
