('mcq', 2, 3, 'تُسمّى عملية تجزئة المتجه إلى مركّبتيه تحليل المتجه.', '["الجمع الجبري يأتي بعد التحليل، ويُقصد به جمع المركّبات لإيجاد المحصلة.","هذه زاوية تحدد اتجاه المحصلة، وليست عملية تجزئة.","طريقة الرسم تجمع المتجهات رأسًا لذيل، ولا تجزّئ المتجه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-20T17:53:29.936Z"}'::jsonb),
('mcq', 3, 0, 'زاوية المتجه المحصل $\theta = \tan^{-1}\left(\frac{R_y}{R_x}\right)$: الظل العكسي لخارج قسمة المركّبة y على المركّبة x للمتجه المحصل.', '["","قُلبت النسبة؛ وهذه تعطي زاوية المحصلة مع المحور y لا مع المحور x.","هذه الزاوية $\\theta$ في قانون جيب التمام، وليست زاوية المحصلة.","$\\cos\\theta = \\frac{R_x}{R}$ لا $\\frac{R_y}{R}$؛ فهذه العلاقة تعطي زاوية المحصلة مع المحور y."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-20T17:53:29.936Z"}'::jsonb),
('mcq', 4, 2, '$\boldsymbol{A}_x$ المركّبة الأفقية: متجه يوازي المحور x، وإذا جُمع مع $\boldsymbol{A}_y$ كانت المحصلة المتجه الأصلي $\boldsymbol{A}$.', '["المركّبة الموازية للمحور y هي $\\boldsymbol{A}_y$.","الزاوية ليست متجهًا، و$\\boldsymbol{A}_x$ متجه يُجمع مع $\\boldsymbol{A}_y$.","","$\\boldsymbol{A}$ هو مجموع مركّبتيه، و$\\boldsymbol{A}_x$ إحداهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-20T17:53:29.936Z"}'::jsonb),
('mcq', 5, 0, 'السهم (2) يوازي المحور y ويمتد من رأس المركّبة الأفقية إلى رأس $\boldsymbol{A}$، فهو المركّبة الرأسية $\boldsymbol{A}_y$، ومجموعه مع (1) يساوي $\boldsymbol{A}$.', '["","المركّبة الأفقية هي السهم (1) الموازي للمحور x.","السهم (2) جزء من تحليل $\\boldsymbol{A}$ وليس محصلة متجهين.","السهم (2) أقصر من $\\boldsymbol{A}$ ويوازي المحور y، فليس هو $\\boldsymbol{A}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-20T17:53:29.936Z"}'::jsonb),
('mcq', 6, 3, 'المركّبتان متعامدتان، فيكوّن المتجه الأصلي معهما مثلثًا قائم الزاوية وترُه المتجه الأصلي؛ لذا يكون مقداره أكبر من مقدار أي من مركّبتيه عندما لا يقع على أحد المحورين.', '["الوتر يقابل الزاوية القائمة بين المركّبتين، وهو المتجه الأصلي.","المركّبتان متعامدتان، فلا يمكن أن تكون زوايا المثلث كلها $60^\\circ$.","الزاوية بين المركّبتين قائمة لا منفرجة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-20T17:53:29.936Z"}'::jsonb),
('mcq', 7, 1, 'اتجاه أي متجه، ومنه المحصل، هو الزاوية التي يصنعها مع محور x الموجب مقيسة في عكس اتجاه حركة عقارب الساعة.', '["الظل هنا نسبة $R_y$ إلى $R_x$، فالزاوية مقيسة من المحور x.","","زاوية المحصلة تُقاس من محور النظام الإحداثي لا من أحد المتجهات المجموعة.","الزاوية تُقاس في عكس اتجاه حركة عقارب الساعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-20T17:53:29.936Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) مركّبتا المتجه: متجهان يُسقطان على محوري النظام الإحداثي، أحدهما يوازي المحور x والآخر يوازي المحور y، ومجموعهما يساوي المتجه الأصلي. (ب) تحليل المتجه: عملية تجزئة المتجه إلى مركّبتيه. (ج) زاوية المتجه المحصل: الظل العكسي لخارج قسمة المركّبة y على المركّبة x للمتجه المحصل، $\theta = \tan^{-1}\left(\frac{R_y}{R_x}\right)$.', '["تعريف المركّبتين","تعريف تحليل المتجه","تعريف زاوية المحصل مع العلاقة"]'::jsonb, '[]'::jsonb, '[{"element":"المركّبتان","marks":1},{"element":"تحليل المتجه","marks":1},{"element":"زاوية المحصل والعلاقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"درجتان","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف المركّبتين بأنهما متجهان متساويان","الخلط بين التحليل والجمع","كتابة $\\tan^{-1}(R_x/R_y)$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-20T17:53:29.936Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تحليل المتجه تجزئته إلى مركّبتين: إحداهما توازي المحور x والأخرى توازي المحور y. (ب) $A_x = 4.0\ \text{m}$ (سهم على المحور x من الأصل إلى أسفل رأس $\boldsymbol{A}$)، و$A_y = 3.0\ \text{m}$ (سهم رأسي من رأس $\boldsymbol{A}_x$ إلى رأس $\boldsymbol{A}$). (ج) $A = \sqrt{(4.0)^2 + (3.0)^2} = 5.0\ \text{m}$، و$\theta = \tan^{-1}\left(\frac{3.0}{4.0}\right) = 36.9^\circ$، وهما مقدار $\boldsymbol{A}$ واتجاهه، فـ $\boldsymbol{A} = \boldsymbol{A}_x + \boldsymbol{A}_y$.', '["تعريف تحليل المتجه","$A_x = 4.0\\ \\text{m}$ و$A_y = 3.0\\ \\text{m}$ مع وصف موضعيهما","A = 5.0 m","الزاوية $36.9^\\circ$"]'::jsonb, '["$A_x = 4.0\\ \\text{m}$، $A_y = 3.0\\ \\text{m}$","$A = \\sqrt{A_x^2 + A_y^2} = 5.0\\ \\text{m}$","$\\theta = \\tan^{-1}\\left(\\frac{A_y}{A_x}\\right) = 36.9^\\circ$"]'::jsonb, '[{"element":"تعريف التحليل","marks":1},{"element":"المركّبتان","marks":1},{"element":"المقدار","marks":1},{"element":"الزاوية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجتان","description":"عنصران صحيحان فقط أو طريقة صحيحة مع أخطاء متعددة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل المركّبتين","جمع المركّبتين عدديًّا 7.0 m","رسم المركّبة الرأسية من الأصل دون ربطها برأس المركّبة الأفقية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-20T17:53:29.937Z"}'::jsonb),
('essay', 3, null::int, null, null, 'زاوية المتجه المحصل تحدد اتجاه المحصلة، وهي الزاوية التي يصنعها المحصل مع محور x الموجب في عكس اتجاه حركة عقارب الساعة، $\theta = \tan^{-1}\left(\frac{R_y}{R_x}\right)$. أما $\theta$ في قانون جيب التمام فهي الزاوية المحصورة بين المتجهين المجموعين في مثلث الجمع، وتُستعمل لحساب مقدار المحصلة. في المثال: الزاوية بين الإزاحتين $90^\circ$ (فيؤول القانون إلى فيثاغورس ويعطي $R = 5.0\ \text{m}$)، أما زاوية المتجه المحصل فهي $\tan^{-1}\left(\frac{3.0}{4.0}\right) = 36.9^\circ$ فوق محور $+x$.', '["تعريف زاوية المتجه المحصل ومرجع قياسها","تعريف $\\theta$ في قانون جيب التمام","المثال: $90^\\circ$ مقابل $36.9^\\circ$"]'::jsonb, '[]'::jsonb, '[{"element":"زاوية المتجه المحصل","marks":1},{"element":"زاوية قانون جيب التمام","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"درجتان","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الزاويتين شيئًا واحدًا","قياس زاوية المحصل من المتجه الأول بدل المحور x","حساب $\\tan^{-1}(4.0/3.0)$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.937Z"}'::jsonb)
