('mcq', 2, 0, '$A_x = A\cos\theta$ موجبة عندما يكون $\cos\theta > 0$، أي في الربعين الأول والرابع: بين $0^\circ$ و$90^\circ$ وبين $270^\circ$ و$360^\circ$.', '["","في هذا المدى ($0^\\circ$ إلى $180^\\circ$) تكون المركّبة y موجبة، أما المركّبة x فتصبح سالبة بعد $90^\\circ$.","في هذا المدى (الربعان الثاني والثالث) تكون المركّبة x سالبة.","في هذا المدى تكون المركّبة y سالبة، والمركّبة x سالبة في جزئه الأول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-20T17:53:29.937Z"}'::jsonb),
('mcq', 3, 1, '$230^\circ$ تقع بين $180^\circ$ و$270^\circ$ فالمتجه في الربع الثالث: $\cos 230^\circ < 0$ و$\sin 230^\circ < 0$، فالمركّبتان سالبتان.', '["الزاوية بين $180^\\circ$ و$270^\\circ$، فالمتجه في الربع الثالث لا الرابع.","","هذه إشارات الربع الثاني (بين $90^\\circ$ و$180^\\circ$).","هذه إشارات الربع الأول (بين $0^\\circ$ و$90^\\circ$)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-20T17:53:29.938Z"}'::jsonb),
('mcq', 4, 3, 'المركّبة x موجبة والمركّبة y سالبة في الربع الرابع (يمين المحور y وتحت المحور x)، وهو موضع $\boldsymbol{T}$.', '["$\\boldsymbol{P}$ في الربع الأول، فمركّبتاه موجبتان.","$\\boldsymbol{Q}$ في الربع الثاني، فمركّبته x سالبة ومركّبته y موجبة.","$\\boldsymbol{S}$ في الربع الثالث، فمركّبتاه سالبتان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-20T17:53:29.938Z"}'::jsonb),
('mcq', 5, 1, '$d_x = 8.0\cos 150.0^\circ = -6.9\ \text{km}$، $d_y = 8.0\sin 150.0^\circ = +4.0\ \text{km}$؛ فالإزاحة في الربع الثاني.', '["أُهملت الإشارة السالبة لـ $\\cos 150.0^\\circ$؛ فالإزاحة في الربع الثاني ومركّبتها x سالبة.","","بُدّل $\\sin$ و$\\cos$ عند الحساب.","المركّبة y موجبة لأن المتجه فوق المحور x."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-20T17:53:29.938Z"}'::jsonb),
('mcq', 6, 2, 'المركّبتان سالبتان فالمتجه في الربع الثالث، ويصنع $45^\circ$ مع محور $-x$، فاتجاهه $180^\circ + 45^\circ = 225^\circ$.', '["هذه قراءة الآلة الحاسبة لـ $\\tan^{-1}\\left(\\frac{-5.0}{-5.0}\\right)$، لكن المركّبتين سالبتان فالمتجه في الربع الثالث.","هذه الزاوية في الربع الثاني، حيث تكون المركّبة y موجبة.","","هذه الزاوية في الربع الرابع، حيث تكون المركّبة x موجبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-20T17:53:29.938Z"}'::jsonb),
('mcq', 7, 0, '$A_y = A\sin\theta$ موجبة عندما يكون $\sin\theta > 0$، أي عندما يقع المتجه فوق المحور x: في الربعين الأول والثاني.', '["","في هذين الربعين تكون المركّبة x موجبة، أما y فسالبة في الرابع.","المركّبة y سالبة في الربع الثالث.","في هذين الربعين يقع المتجه تحت المحور x فتكون المركّبة y سالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-20T17:53:29.938Z"}'::jsonb),
('essay', 1, null::int, null, null, '$40^\circ$: الربع الأول، $A_x > 0$ و$A_y > 0$. $135^\circ$: الربع الثاني، $A_x < 0$ و$A_y > 0$. $210^\circ$: الربع الثالث، $A_x < 0$ و$A_y < 0$. $300^\circ$: الربع الرابع، $A_x > 0$ و$A_y < 0$.', '["$40^\\circ$: الأول (موجبة، موجبة)","$135^\\circ$: الثاني (سالبة، موجبة)","$210^\\circ$: الثالث (سالبة، سالبة)","$300^\\circ$: الرابع (موجبة، سالبة)"]'::jsonb, '[]'::jsonb, '[{"element":"المتجه $40^\\circ$","marks":1},{"element":"المتجه $135^\\circ$","marks":1},{"element":"المتجه $210^\\circ$","marks":1},{"element":"المتجه $300^\\circ$","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجتان","description":"عنصران صحيحان فقط أو طريقة صحيحة مع أخطاء متعددة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الربع الرابع بين $180^\\circ$ و$270^\\circ$","إشارة x موجبة في الربع الثاني","الخلط بين ترتيب الأرباع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-20T17:53:29.938Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $240.0^\circ$ بين $180^\circ$ و$270^\circ$: الربع الثالث، فالمركّبتان سالبتان. (ب) $d_x = 12.0\cos 240.0^\circ = -6.00\ \text{m}$، $d_y = 12.0\sin 240.0^\circ = -10.4\ \text{m}$. (ج) الإشارة السالبة لـ $d_x$ تعني 6.00 m نحو الغرب، والإشارة السالبة لـ $d_y$ تعني 10.4 m نحو الجنوب.', '["الربع الثالث وتوقع الإشارتين","$d_x = -6.00\\ \\text{m}$ و$d_y = -10.4\\ \\text{m}$","التفسير: غربًا وجنوبًا"]'::jsonb, '["$180^\\circ < 240.0^\\circ < 270^\\circ$ ⇐ الربع الثالث","$d_x = 12.0\\cos 240.0^\\circ = -6.00\\ \\text{m}$","$d_y = 12.0\\sin 240.0^\\circ = -10.4\\ \\text{m}$"]'::jsonb, '[{"element":"الربع والإشارتان","marks":1},{"element":"حساب المركّبتين","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"درجتان","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حذف الإشارات السالبة","حساب $\\cos 60^\\circ$ دون تحديد الإشارة","تفسير السالب بأنه نحو الشرق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-20T17:53:29.939Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الاستنتاج خطأ. فإشارتا المركّبتين ($R_x < 0$ و$R_y > 0$) تضعان المحصلة في الربع الثاني لا الرابع؛ والآلة الحاسبة تعطي لـ $\tan^{-1}$ زاوية بين $-90^\circ$ و$90^\circ$ فقط، ولا تميّز بين الربعين الثاني والرابع لأن النسبة سالبة في الحالتين. الاتجاه الصحيح: $180^\circ - 53.1^\circ = 126.9^\circ$ مع محور $+x$.', '["الحكم بخطأ الاستنتاج","تحديد الربع الثاني من الإشارتين","تفسير قصور الآلة الحاسبة","الاتجاه $126.9^\\circ$"]'::jsonb, '["$R_x < 0$، $R_y > 0$ ⇐ الربع الثاني","$\\theta = 180^\\circ - 53.1^\\circ = 126.9^\\circ$"]'::jsonb, '[{"element":"الحكم وتحديد الربع الصحيح","marks":1},{"element":"تفسير قراءة الآلة الحاسبة","marks":1},{"element":"الاتجاه الصحيح","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"درجتان","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول قراءة الآلة الحاسبة دون فحص الإشارات","إضافة $360^\\circ$ فيصبح $306.9^\\circ$ (الربع الرابع)","إضافة $180^\\circ$ إلى الزاوية الموجبة $53.1^\\circ$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-20T17:53:29.939Z"}'::jsonb)
