from (values
('mcq', 1, 'يدرس طالب حركة سيارة تتنقل بين شوارع مدينة على سطح أرض مستوٍ. ما النظام الإحداثي الأسهل لتحليل حركتها؟', null, null, '["المحور $+x$ أفقي، والمحور $+y$ رأسي إلى أعلى","المحور $+x$ نحو الشرق، والمحور $+y$ نحو الشمال الشرقي","المحور $+x$ نحو الشمال، والمحور $+y$ نحو الشمال أيضًا","المحور $+x$ نحو الشرق، والمحور $+y$ نحو الشمال"]'::jsonb, 'تطبيق', 'اختيار نظام إحداثي', 'سهل', 'الكتاب ص 134 — مركّبات المتجهات: اختيار النظام الإحداثي'),
('mcq', 2, 'قُذفت كرة إلى أعلى في الهواء. ما النظام الإحداثي المناسب لتحليل حركتها؟', null, null, '["المحور x نحو الشرق، والمحور y نحو الشمال على سطح الأرض","المحور x أفقي، والمحور y عمودي عليه رأسيًّا","المحور x في اتجاه مائل $45^\\circ$، والمحور y أفقي","المحور x رأسي، والمحور y رأسي أيضًا"]'::jsonb, 'تطبيق', 'اختيار نظام إحداثي', 'سهل', 'الكتاب ص 156 — الأسئلة 48 و51 و52'),
('mcq', 3, 'سار متنزّه 3.0 km شرقًا ثم 4.0 km شمالًا، ويُراد وصف مواقعه وإزاحاته في نظام إحداثي محوره $+x$ نحو الشرق و$+y$ نحو الشمال. أين يكون الأنسب وضع نقطة الأصل؟', null, null, '["عند نقطة نهاية الرحلة؛ لأن الإزاحة تُقاس إليها","عند منتصف المسار؛ ليكون الأصل في وسط الحركة","عند نقطة البداية؛ فيكون موقعه النهائي هو إزاحته","عند نقطة الانعطاف دائمًا؛ لأن الأصل يوضع حيث يتغير الاتجاه"]'::jsonb, 'تطبيق', 'اختيار نقطة الأصل', 'متوسط', 'الكتاب ص 134 — مركّبات المتجهات (اختيار النظام الإحداثي)'),
('mcq', 4, 'المحور $+x$ نحو الشرق و$+y$ نحو الشمال. متجه يتجه $30^\circ$ جنوب الشرق. ما اتجاهه مقيسًا من محور $+x$ في عكس اتجاه حركة عقارب الساعة؟', null, null, '["$330^\\circ$","$30^\\circ$","$210^\\circ$","$150^\\circ$"]'::jsonb, 'تطبيق', 'التعبير عن الاتجاه بالزاوية', 'متوسط', 'الكتاب ص 135 — تعريف اتجاه المتجه'),
('mcq', 5, 'يبين الشكل الآتي إزاحة $\boldsymbol{d}$ تتجه $40.0^\circ$ شمال الغرب. ما اتجاهها مقيسًا من محور $+x$ (الشرق) في عكس اتجاه حركة عقارب الساعة؟', null, '[{"src":"qimg/phys1/c5l1-o11-nw.svg","alt":"محوران متعامدان مكتوب عند أطرافهما: الشرق يمينًا، والشمال أعلى، والغرب يسارًا، والجنوب أسفل. سهم أخضر d من نقطة الأصل يتجه إلى أعلى اليسار، وقوس بينه وبين اتجاه الغرب مكتوب عنده 40.0°."}]'::jsonb, '["$40.0^\\circ$","$130.0^\\circ$","$220.0^\\circ$","$140.0^\\circ$"]'::jsonb, 'تطبيق', 'التعبير عن الاتجاه بالزاوية', 'سهل', 'الكتاب ص 137 — المثال 2: زاوية الاتجاه في الربع الثاني'),
('mcq', 6, 'يبين الشكل الآتي متجهًا $\boldsymbol{A}$ يصنع زاوية $35.0^\circ$ تحت محور $-x$. ما اتجاهه مقيسًا من محور $+x$ في عكس اتجاه حركة عقارب الساعة؟', null, '[{"src":"qimg/phys1/c5l1-o11-third.svg","alt":"محوران +x و+y. سهم أزرق A من نقطة الأصل يتجه إلى أسفل اليسار، وقوس بين الجزء السالب من محور x والسهم مكتوب عنده 35.0°."}]'::jsonb, '["$35.0^\\circ$","$215.0^\\circ$","$145.0^\\circ$","$325.0^\\circ$"]'::jsonb, 'تطبيق', 'التعبير عن الاتجاه بالزاوية', 'صعب', 'الكتاب ص 135 — تعريف اتجاه المتجه'),
('mcq', 7, 'عُيّن نظام إحداثي يصنع فيه محور $+x$ زاوية $30^\circ$ فوق الأفقي كما في الشكل الآتي. كيف يجب أن يكون اتجاه محور $+y$؟', null, '[{"src":"qimg/phys1/c5l1-o11-tilted.svg","alt":"خط أفقي متقطع مكتوب عنده الأفقي، ومن نقطة على يساره سهم أسود مائل إلى أعلى اليمين مكتوب عند رأسه +x، وقوس بين الخط الأفقي والسهم مكتوب عنده 30°. لا يظهر المحور y."}]'::jsonb, '["عموديًّا على محور x، بزاوية $120^\\circ$ مع الأفقي","رأسيًّا إلى أعلى، فيصنع $90^\\circ$ مع الخط الأفقي","أفقيًّا، فيصنع $0^\\circ$ مع الأفقي","مائلًا $60^\\circ$ فوق الأفقي"]'::jsonb, 'تطبيق', 'توجيه المحورين', 'صعب', 'الكتاب ص 156 — الأسئلة 48 و51 و52'),
('essay', 1, 'صف نظامًا إحداثيًّا مناسبًا (نقطة الأصل واتجاها المحورين) لكل حالة مما يأتي، مع تعليل اختيارك: (أ) سيارة تتنقل في شوارع مدينة مستوية. (ب) كرة تُقذف إلى أعلى في الهواء. (ج) زلاجة تنزلق إلى أسفل تل مائل.', null, null, null, 'تطبيق', 'اختيار نظام إحداثي وتعليله', 'متوسط', 'الكتاب ص 134 — مركّبات المتجهات: اختيار النظام الإحداثي'),
('essay', 2, 'في نظام إحداثي محوره $+x$ نحو الشرق و$+y$ نحو الشمال، عبّر عن اتجاه كل متجه مما يأتي بالزاوية التي يصنعها مع محور $+x$ مقيسة في عكس اتجاه حركة عقارب الساعة: (أ) $25.0^\circ$ شمال الغرب. (ب) نحو الجنوب تمامًا. (ج) $60.0^\circ$ جنوب الشرق. (د) $15.0^\circ$ غرب الشمال.', null, null, null, 'تطبيق', 'التعبير عن الاتجاه بالزاوية', 'متوسط', 'الكتاب ص 135 — تعريف اتجاه المتجه'),
('essay', 3, 'إزاحة مقدارها 10.0 m في اتجاه $30.0^\circ$ شمال الشرق. (أ) احسب مركّبتيها في نظام إحداثي محوره $+x$ نحو الشرق. (ب) ما مركّبتاها في نظام إحداثي آخر محوره $+x$ في اتجاه الإزاحة نفسها؟ (ج) ماذا تستنتج عن أثر اختيار النظام الإحداثي في المتجه وفي مركّبتيه، وأيّ النظامين أسهل هنا؟', null, null, null, 'تحليل', 'مقارنة نظامين إحداثيين', 'صعب', 'الكتاب ص 134 — مركّبات المتجهات: اختيار النظام الإحداثي')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
