select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'عندما تكون الحركة محصورة في سطح الأرض يكون الأسهل جعل المحور x يشير إلى الشرق والمحور y يشير إلى الشمال.', '["هذا مناسب للحركة في الهواء (أعلى وأسفل)، والسيارة تتحرك على سطح الأرض.","المحوران يجب أن يكونا متعامدين، والشرق والشمال الشرقي بينهما $45^\\circ$.","لا يكون المحوران في الاتجاه نفسه؛ فالمحور y يصنع $90^\\circ$ مع المحور x.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-20T17:53:29.939Z"}'::jsonb),
('mcq', 2, 1, 'عندما يتحرك جسم خلال الهواء يُختار المحور x أفقيًّا والمحور y عموديًّا عليه (رأسيًّا).', '["هذا يناسب الحركة على سطح الأرض، وحركة الكرة رأسية في الهواء.","","المحوران يجب أن يتعامدا، والمائل $45^\\circ$ لا يتعامد مع الأفقي.","لا يكون المحوران في الاتجاه نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-20T17:53:29.940Z"}'::jsonb),
('mcq', 3, 2, 'ليس لموضع نقطة الأصل إجابة واحدة صحيحة، لكن بعض الخيارات تسهّل الحل؛ فوضع الأصل عند نقطة البداية يجعل متجه الموقع النهائي (3.0 km شرقًا و4.0 km شمالًا) هو الإزاحة المحصلة مباشرة.', '["الإزاحة تبدأ من نقطة البداية؛ ووضع الأصل عند النهاية يجعل الموقع الابتدائي بمركّبتين سالبتين ويعقّد الحل.","لا ميزة لمنتصف المسار؛ فهو يجعل لموقعي البداية والنهاية مركّبات كسرية بإشارات مختلفة.","","لا توجد قاعدة تُلزم بوضع الأصل عند نقطة الانعطاف؛ فالأصل يُختار حيث يسهّل الحل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-20T17:53:29.940Z"}'::jsonb),
('mcq', 4, 0, '$30^\circ$ جنوب الشرق تقع تحت محور $+x$ في الربع الرابع، فالزاوية المقيسة في عكس اتجاه حركة عقارب الساعة $360^\circ - 30^\circ = 330^\circ$.', '["","هذه $30^\\circ$ شمال الشرق؛ فالقياس في عكس اتجاه عقارب الساعة يتجه نحو الشمال أولًا.","هذه $30^\\circ$ جنوب الغرب، لا جنوب الشرق.","هذه $30^\\circ$ شمال الغرب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-20T17:53:29.940Z"}'::jsonb),
('mcq', 5, 3, 'الإزاحة في الربع الثاني وتصنع $40.0^\circ$ مع الغرب (محور $-x$)، فاتجاهها $180.0^\circ - 40.0^\circ = 140.0^\circ$.', '["هذه الزاوية مقيسة من الغرب لا من محور $+x$ (الشرق).","أُضيفت $40.0^\\circ$ إلى $90^\\circ$ كأن الزاوية مقيسة من الشمال.","هذه $40.0^\\circ$ جنوب الغرب؛ الإزاحة فوق محور x.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-20T17:53:29.941Z"}'::jsonb),
('mcq', 6, 1, 'المتجه في الربع الثالث، تحت محور $-x$ بزاوية $35.0^\circ$، فاتجاهه $180^\circ + 35.0^\circ = 215.0^\circ$.', '["هذه الزاوية مع محور $-x$ لا مع محور $+x$.","","طُرحت $35.0^\\circ$ من $180^\\circ$ فوُضع المتجه فوق محور x في الربع الثاني.","طُرحت $35.0^\\circ$ من $360^\\circ$ فوُضع المتجه في الربع الرابع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-20T17:53:29.941Z"}'::jsonb),
('mcq', 7, 0, 'يُرسم محور $+y$ بحيث يصنع $90^\circ$ مع محور $+x$ في عكس اتجاه حركة عقارب الساعة، فيصنع $30^\circ + 90^\circ = 120^\circ$ مع الأفقي، والزاوية بين المحورين $90^\circ$.', '["","الرأسي يصنع $60^\\circ$ فقط مع المحور x المائل، والمحوران يجب أن يتعامدا.","الأفقي يصنع $30^\\circ$ مع المحور x، لا $90^\\circ$.","هذا الاتجاه يصنع $30^\\circ$ فقط مع المحور x، والمطلوب $90^\\circ$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-20T17:53:29.941Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) نقطة الأصل عند موقع بدء السيارة، والمحور $+x$ نحو الشرق و$+y$ نحو الشمال، لأن الحركة محصورة في سطح الأرض. (ب) نقطة الأصل عند نقطة القذف، والمحور x أفقي والمحور $+y$ رأسي إلى أعلى، لأن الحركة في الهواء رأسية. (ج) نقطة الأصل عند بداية الانزلاق، والمحور $+x$ موازٍ لسطح التل في اتجاه الحركة والمحور y عمودي على السطح، فتصبح الحركة على محور واحد.', '["نظام (أ) مع التعليل","نظام (ب) مع التعليل","نظام (ج) مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة (أ)","marks":1},{"element":"الحالة (ب)","marks":1},{"element":"الحالة (ج)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"درجتان","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار محورين غير متعامدين","عدم تحديد نقطة الأصل","اختيار المحور x أفقيًّا في حالة التل دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-20T17:53:29.941Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $180.0^\circ - 25.0^\circ = 155.0^\circ$. (ب) $270^\circ$. (ج) $360.0^\circ - 60.0^\circ = 300.0^\circ$. (د) $90.0^\circ + 15.0^\circ = 105.0^\circ$.', '["$155.0^\\circ$","$270^\\circ$","$300.0^\\circ$","$105.0^\\circ$"]'::jsonb, '["(أ) الربع الثاني: $180.0^\\circ - 25.0^\\circ = 155.0^\\circ$","(ب) محور $-y$: $270^\\circ$","(ج) الربع الرابع: $360.0^\\circ - 60.0^\\circ = 300.0^\\circ$","(د) الربع الثاني: $90.0^\\circ + 15.0^\\circ = 105.0^\\circ$"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"3 درجات","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجتان","description":"عنصران صحيحان فقط أو طريقة صحيحة مع أخطاء متعددة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القياس في اتجاه حركة عقارب الساعة","قياس الزاوية من الشمال بدل الشرق","الخلط بين «شمال الغرب» و«غرب الشمال»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-20T17:53:29.942Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $d_x = 10.0\cos 30.0^\circ = 8.66\ \text{m}$، $d_y = 10.0\sin 30.0^\circ = 5.00\ \text{m}$. (ب) الإزاحة على المحور x نفسه: $d_x = 10.0\ \text{m}$، $d_y = 0$. (ج) المتجه نفسه (مقداره واتجاهه في الفضاء) لا يتغير باختيار النظام الإحداثي، لكن مركّبتيه وزاويته تتغير بحسب توجيه المحورين؛ ولا توجد إجابة واحدة صحيحة، لكن النظام الثاني أسهل لأنه يجعل المتجه على محور واحد.', '["مركّبتا النظام الأول 8.66 m و5.00 m","مركّبتا النظام الثاني 10.0 m و0","الاستنتاج: المتجه ثابت والمركّبات تتغير، والنظام الثاني أسهل"]'::jsonb, '["$d_x = 8.66\\ \\text{m}$، $d_y = 5.00\\ \\text{m}$","$d_x'' = 10.0\\ \\text{m}$، $d_y'' = 0$","$\\sqrt{(8.66)^2 + (5.00)^2} = 10.0\\ \\text{m}$ في الحالتين"]'::jsonb, '[{"element":"النظام الأول","marks":1},{"element":"النظام الثاني","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة بخطوات ووحدات صحيحة"},{"level":"درجتان","description":"إجابة صحيحة في معظمها مع نقص عنصر واحد أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المتجه نفسه يتغير بتغير النظام","تبديل $\\sin$ و$\\cos$ في (أ)","عدّ أحد النظامين خطأ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-20T17:53:29.942Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
