from (values
('mcq', 1, 'عند تحريك يدك فوق سطح مقعد تشعر بقوة تمانع هذه الحركة الانزلاقية. ما اسم هذه القوة؟', null, null, '["قوة الاحتكاك","القوة العمودية","قوة الشد","قوة الجاذبية (الوزن)"]'::jsonb, 'تذكر', 'تسمية مصطلح', 'سهل', 'الكتاب ص 139 — قوة الاحتكاك'),
('mcq', 2, 'ما نوعا الاحتكاك اللذان يمانعان الحركة دائمًا؟', null, null, '["الاحتكاك العمودي والاحتكاك الأفقي","الاحتكاك السكوني والاحتكاك الحركي","الاحتكاك السكوني والوزن الظاهري","الاحتكاك الحركي والقوة العمودية"]'::jsonb, 'تذكر', 'تذكر أنواع', 'سهل', 'الكتاب ص 139 — الاحتكاك السكوني والاحتكاك الحركي'),
('mcq', 3, 'ينزلق كتاب على سطح طاولة أفقي، ويؤثر سطح الطاولة في الكتاب بقوتي تلامس. أيّ وصف مما يأتي يطابق قوة الاحتكاك منهما؟', null, null, '["عمودية على سطح الطاولة وتتجه إلى أعلى","موازية لسطح الطاولة وفي اتجاه انزلاق الكتاب","موازية لسطح الطاولة وتعاكس انزلاق الكتاب","عمودية على سطح الطاولة وتتجه إلى أسفل"]'::jsonb, 'فهم', 'تمييز القوة', 'سهل', 'الكتاب ص 139، 141 — قوة الاحتكاك، والزاوية بين القوتين F_N و f قائمة'),
('mcq', 4, 'في أيّ المواقف الآتية نحتاج إلى قوة الاحتكاك لكي يتم العمل؟', null, null, '["تشغيل آلة فيها قطعتا فولاذ تُدلك إحداهما بالأخرى","سقوط حجر سقوطًا حرًا في الفراغ","دوران عجلة حول محور مُعالَج بالزيت","المشي على أرض دون أن تنزلق القدمان"]'::jsonb, 'فهم', 'تطبيق في الحياة', 'متوسط', 'الكتاب ص 139 — قوة الاحتكاك (أهمية الاحتكاك)'),
('mcq', 5, 'ما أصل قوتي الاحتكاك السكوني والحركي عند النظر إلى السطوح على مستوى الذرات؟', null, null, '["تلامس النتوءات البارزة من السطحين وتشكّل روابط مؤقتة بينها","تجاذب كتلتي الجسمين تجاذبًا كتليًا عن بعد","ضغط الهواء المحصور بين السطحين المتلامسين عند تقاربهما الشديد","خلوّ السطوح التي تبدو ملساء من أي نتوءات"]'::jsonb, 'تذكر', 'تفسير مجهري', 'متوسط', 'الكتاب ص 144 — تطبيق الفيزياء: أسباب الاحتكاك'),
('mcq', 6, 'دفع طالب أريكة ثقيلة على أرضية أفقية فلم تتحرك، ثم زاد قوة دفعه فانزلقت الأريكة على الأرضية. أيّ العبارات الآتية تصف قوة الاحتكاك بين الأريكة والأرضية في الحالتين وصفًا صحيحًا؟', null, null, '["لا احتكاك في الأولى لأنها لم تتحرك، واحتكاك حركي في الثانية","احتكاك سكوني في الأولى، واحتكاك حركي في الثانية","احتكاك حركي في الأولى، واحتكاك سكوني في الثانية","احتكاك سكوني في الحالتين؛ لأن السطحين لم يتغيرا"]'::jsonb, 'فهم', 'تمييز نوعي الاحتكاك', 'متوسط', 'الكتاب ص 139 — الاحتكاك السكوني والاحتكاك الحركي (الشكل 5-8)'),
('mcq', 7, 'وُضعت خزانة على أرضية صندوق شاحنة، ثم تسارعت الشاحنة إلى الأمام على طريق أفقي فتسارعت الخزانة معها دون أن تنزلق على أرضية الصندوق. ما القوة الأفقية التي تُكسب الخزانة تسارعها؟', null, null, '["قوة احتكاك من أرضية الصندوق نحو الخلف؛ لأن الاحتكاك يعاكس الحركة","القوة العمودية من أرضية الصندوق نحو الأمام","قوة احتكاك سكوني من أرضية الصندوق نحو الأمام","لا تؤثر فيها قوة أفقية؛ لأنها ساكنة بالنسبة إلى الشاحنة"]'::jsonb, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 145 — المراجعة 27 (تسارع)'),
('essay', 1, 'عرّف قوة الاحتكاك، واذكر نوعيها مع مثال لكل نوع، ثم فسّر لماذا يتوقف كتاب دُفع فوق سطح طاولة أفقي بعد أن يتحرك فترة قصيرة.', null, null, null, 'فهم', 'تعريف وتفسير', 'متوسط', 'الكتاب ص 139 — قوة الاحتكاك'),
('essay', 2, 'يصعب المشي على أرض جليدية زلقة. فسّر ذلك مستعملًا مفهوم قوة الاحتكاك، ثم اذكر موقفين من الحياة نحتاج فيهما إلى الاحتكاك، وموقفًا نسعى فيه إلى تقليله مع بيان السبب.', null, null, null, 'تحليل', 'تفسير ظاهرة', 'صعب', 'الكتاب ص 139 — قوة الاحتكاك؛ ص 158 السؤال 73'),
('essay', 3, 'تُعرَّف قوة الاحتكاك بأنها قوة تلامس تؤثر في اتجاه معاكس للحركة الانزلاقية بين السطوح. (a) حلّل هذا التعريف إلى عناصره: نوع القوة، وشرط وجودها، واتجاهها. (b) طبّق هذه العناصر لتحدد هل تؤثر قوة احتكاك في كل حالة مما يأتي، وما نوعها إن وُجدت، مع التعليل: (1) كتاب ساكن على طاولة أفقية لا تؤثر فيه قوة أفقية. (2) صندوق يُدفع أفقيًا على أرضية فلا يتحرك. (3) زلاجة تنزلق على ثلج أفقي. (4) كرة تسقط سقوطًا حرًا في الهواء (أهمل مقاومة الهواء).', null, null, null, 'تحليل', 'تحليل تعريف وتطبيقه', 'صعب', 'الكتاب ص 139، 141 — قوة الاحتكاك، والاحتكاك السكوني والحركي')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
