select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'القوة التي يؤثر بها سطح المقعد في اليد وتمانع انزلاقها عليه هي قوة الاحتكاك؛ فقوة الاحتكاك قوة تلامس تؤثر في اتجاه معاكس للحركة الانزلاقية بين السطوح.', '["","القوة العمودية يؤثر بها السطح عموديًا عليه، فلا تمانع الانزلاق الموازي للسطح.","قوة الشد تؤثر بها الحبال والخيوط المشدودة، ولا يوجد حبل هنا.","الوزن قوة مجال رأسية تؤثر بها الأرض، ولا تنشأ من انزلاق اليد على سطح المقعد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-20T17:53:29.942Z"}'::jsonb),
('mcq', 2, 1, 'هناك نوعان من الاحتكاك يمانعان الحركة دائمًا: الاحتكاك السكوني بين سطحين لا ينزلق أحدهما على الآخر، والاحتكاك الحركي بين سطحين ينزلق أحدهما على الآخر.', '["لا يُقسَّم الاحتكاك إلى عمودي وأفقي؛ فقوة الاحتكاك موازية دائمًا لسطح التلامس.","","الوزن الظاهري ليس نوعًا من الاحتكاك؛ بل هو القوة التي يؤثر بها الميزان في الجسم.","القوة العمودية ليست احتكاكًا؛ فهي عمودية على سطح التلامس، أما الاحتكاك فموازٍ له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-20T17:53:29.943Z"}'::jsonb),
('mcq', 3, 2, 'قوة الاحتكاك قوة تلامس تؤثر في اتجاه معاكس للحركة الانزلاقية بين السطحين، فهي موازية لسطح التلامس وتعاكس انزلاق الكتاب؛ أما قوة التلامس الأخرى العمودية على السطح إلى أعلى فهي القوة العمودية، والزاوية بين القوتين قائمة.', '["هذه القوة العمودية التي يؤثر بها سطح الطاولة في الكتاب، لا قوة الاحتكاك.","الاحتكاك يمانع الانزلاق، فلا يكون في اتجاهه.","","سطح الطاولة لا يؤثر في الكتاب بقوة إلى أسفل؛ والقوة الرأسية إلى أسفل المؤثرة في الكتاب هي وزنه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-20T17:53:29.943Z"}'::jsonb),
('mcq', 4, 3, 'نحتاج إلى الاحتكاك عند المشي وعند بدء حركة السيارة أو الدراجة وعند الوقوف؛ ولذلك يصعب المشي على الجليد أو على أرض زلقة حيث يكون الاحتكاك صغيرًا.', '["في الآلات نسعى إلى تقليل الاحتكاك بين القطع المعدنية، ولذلك تُعالَج بالزيت.","السقوط الحر في الفراغ لا يتضمن تلامس سطوح، فلا احتكاك فيه أصلًا.","الزيت يقلل الاحتكاك ليسهل الدوران، فالاحتكاك هنا غير مرغوب فيه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-20T17:53:29.943Z"}'::jsonb),
('mcq', 5, 0, 'جميع السطوح خشنة عند النظر إليها بالمجهر حتى التي تبدو ملساء، وعندما يتلامس سطحان تتلامس النتوءات البارزة منهما وتتشكل بينها روابط مؤقتة، وهذا أصل الاحتكاك السكوني والحركي.', '["","التجاذب الكتلي قوة مجال صغيرة جدًا بين الأجسام العادية، وليس أصل الاحتكاك.","الاحتكاك ينشأ من تلامس السطحين نفسيهما لا من الهواء المحصور بينهما.","السطوح الملساء ظاهريًا خشنة على مستوى الذرات، ولو خلت من النتوءات لما نشأ هذا النوع من الروابط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-20T17:53:29.943Z"}'::jsonb),
('mcq', 6, 1, 'قوة الاحتكاك تمانع الحركة الانزلاقية بين السطحين؛ فإذا لم تنزلق الأريكة رغم الدفع أثّر فيها احتكاك سكوني يمنعها من الحركة، وعندما انزلقت أثّر فيها احتكاك حركي بدلًا من الاحتكاك السكوني.', '["الأريكة لم تتحرك لأن قوة أفقية من الأرضية (الاحتكاك السكوني) عاكست الدفع وساوته، فالاحتكاك موجود في الحالة الأولى.","","عكس النوعين: الحركي يتطلب الانزلاق، والسكوني يكون دون انزلاق.","نوع الاحتكاك يحدده انزلاق السطحين أو عدمه لا نوع مادتيهما، والأريكة انزلقت في الحالة الثانية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-20T17:53:29.943Z"}'::jsonb),
('mcq', 7, 2, 'الخزانة تتسارع إلى الأمام، فالقوة المحصلة عليها إلى الأمام وفق القانون الثاني لنيوتن، والجسم الوحيد الذي يلامسها أفقيًا أرضية الصندوق. الخزانة لا تنزلق على الأرضية فالاحتكاك سكوني، وهو يعاكس الحركة الانزلاقية بين السطحين؛ فلولاه لانزلقت الخزانة إلى الخلف بالنسبة إلى الأرضية، لذلك يتجه إلى الأمام ويُكسبها تسارعها.', '["الاحتكاك يعاكس الانزلاق بين السطحين لا حركة الجسم بالنسبة إلى الأرض؛ ولو كانت القوة نحو الخلف لما تسارعت الخزانة إلى الأمام.","القوة العمودية عمودية على أرضية الصندوق فهي رأسية، ولا تُكسب الخزانة تسارعًا أفقيًا.","","الخزانة تتسارع بالنسبة إلى الأرض، فلا بد من قوة محصلة أفقية تؤثر فيها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-20T17:53:29.943Z"}'::jsonb),
('essay', 1, null::int, null, null, 'قوة الاحتكاك قوة تلامس تؤثر في اتجاه معاكس للحركة الانزلاقية بين السطوح. نوعاها: الاحتكاك السكوني، مثل القوة التي تمنع أريكة من الحركة عند دفعها بقوة صغيرة؛ والاحتكاك الحركي، مثل القوة المؤثرة في صندوق ينزلق على أرضية. يتوقف الكتاب لأن قوة الاحتكاك الحركي من سطح الطاولة تؤثر فيه في اتجاه يعاكس حركته، فتُكسبه تسارعًا معاكسًا لاتجاه حركته فتتناقص سرعته حتى تصبح صفرًا.', '["تعريف قوة الاحتكاك: قوة تلامس تعاكس الحركة الانزلاقية بين السطوح","ذكر الاحتكاك السكوني مع مثال صحيح","ذكر الاحتكاك الحركي مع مثال صحيح","تفسير التوقف: الاحتكاك يُكسب الكتاب تسارعًا معاكسًا لحركته"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الاحتكاك السكوني ومثاله","marks":1},{"element":"الاحتكاك الحركي ومثاله","marks":1},{"element":"تفسير توقف الكتاب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح ونوعان بمثالين وتفسير صحيح للتوقف"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكتاب يتوقف لأن قوة الدفع «نفدت» منه.","وصف الاحتكاك بأنه قوة مجال.","الخلط بين مثال الاحتكاك السكوني والحركي."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-20T17:53:29.944Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عند المشي تحتاج القدمان إلى قوة احتكاك بينهما وبين الأرض تمنعهما من الانزلاق؛ والاحتكاك بين الحذاء والجليد صغير جدًا، فتنزلق القدمان ويصعب المشي. نحتاج إلى الاحتكاك مثلًا عند بدء حركة السيارة أو الدراجة، وعند الوقوف (الكبح). ونسعى إلى تقليله بين أجزاء الآلات المتحركة (كقطعتي فولاذ تُدلك إحداهما بالأخرى) بمعالجتها بالزيت؛ لأن الاحتكاك يعيق حركتها ويتطلب قوة أكبر لتشغيلها.', '["المشي يتطلب احتكاكًا بين القدم والأرض يمنع الانزلاق","الاحتكاك على الجليد صغير فتنزلق القدمان","موقفان صحيحان نحتاج فيهما إلى الاحتكاك","موقف صحيح لتقليل الاحتكاك مع السبب"]'::jsonb, '[]'::jsonb, '[{"element":"دور الاحتكاك في المشي","marks":1},{"element":"صغر الاحتكاك على الجليد","marks":1},{"element":"موقفان يحتاجان الاحتكاك","marks":1},{"element":"موقف لتقليله مع السبب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل وأمثلة صحيحة"},{"level":"3 درجات","description":"تفسير صحيح مع نقص في الأمثلة"},{"level":"درجتان","description":"تفسير ناقص أو أمثلة فقط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الاحتكاك ضار دائمًا يجب التخلص منه.","إرجاع صعوبة المشي إلى نقص الوزن على الجليد."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-20T17:53:29.944Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) نوع القوة: قوة تلامس، فلا تنشأ إلا بين سطحين متلامسين. شرط وجودها: انزلاق أحد السطحين على الآخر أو وجود قوة تحاول أن تسبب هذا الانزلاق. اتجاهها: موازٍ لسطح التلامس ومعاكس للحركة الانزلاقية (أو للحركة التي يوشك الجسم أن يبدأها). (b) (1) لا تؤثر قوة احتكاك؛ فالسطحان متلامسان لكن لا انزلاق ولا قوة تحاول تحريك الكتاب، فالاحتكاك السكوني يساوي صفرًا. (2) يؤثر احتكاك سكوني؛ فالسطحان متلامسان ولا انزلاق رغم وجود قوة تحاول تحريك الصندوق، وهو يعاكس الدفع ويساويه مقدارًا. (3) يؤثر احتكاك حركي؛ فالزلاجة تنزلق على الثلج، وهو معاكس لاتجاه انزلاقها. (4) لا تؤثر قوة احتكاك؛ فالكرة لا تلامس أي سطح، والاحتكاك قوة تلامس.', '["تحليل التعريف: قوة تلامس، شرط الانزلاق أو محاولته، الاتجاه موازٍ للسطح معاكس للانزلاق","الحالة (1): لا احتكاك (الاحتكاك السكوني صفر) مع التعليل","الحالة (2): احتكاك سكوني يعاكس الدفع مع التعليل","الحالة (3): احتكاك حركي يعاكس الانزلاق مع التعليل","الحالة (4): لا احتكاك لعدم التلامس"]'::jsonb, '[]'::jsonb, '[{"element":"تحليل التعريف","marks":1},{"element":"الحالة (1)","marks":1},{"element":"الحالة (2)","marks":1},{"element":"الحالة (3)","marks":1},{"element":"الحالة (4)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحليل صحيح للتعريف والحالات الأربع صحيحة مع التعليل"},{"level":"4 درجات","description":"خطأ في عنصر واحد"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن على الكتاب الساكن في الحالة (1) احتكاكًا سكونيًا يساوي قيمته القصوى.","القول إنه لا احتكاك في الحالة (2) لأن الصندوق لم يتحرك.","عدّ الاحتكاك قوة تؤثر في الكرة الساقطة سقوطًا حرًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-20T17:53:29.944Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
