('mcq', 1, 'ما المقصود بالاحتكاك السكوني؟', null, null, '["قوة تنشأ بين سطحين متلامسين عند انزلاق أحدهما على الآخر","قوة يؤثر بها السطح في جسم ساكن فوقه في اتجاه عمودي على سطح التلامس","قوة تنشأ بين سطحين متلامسين بالرغم من عدم انزلاق أي منهما على الآخر","قوة تجاذب تنشأ بين جسمين ساكنين متباعدين"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 139 — الاحتكاك السكوني'),
('mcq', 2, 'تدفع أريكة أفقيًا بقوة صغيرة فلا تتحرك. ما اسم القوة الأفقية التي تؤثر بها الأرضية في الأريكة فتمنع حركتها؟', null, null, '["الاحتكاك السكوني","الاحتكاك الحركي","القوة العمودية","قوة الشد"]'::jsonb, 'تذكر', 'تسمية مصطلح', 'سهل', 'الكتاب ص 139 — الاحتكاك السكوني'),
('mcq', 3, 'في أيّ المواقف الآتية يؤثر احتكاك سكوني في الجسم؟', null, null, '["صندوق ينزلق على أرضية بسرعة ثابتة","كتاب ساكن على سطح مائل لا ينزلق عليه","قرص ينزلق على الجليد ويتباطأ","كتاب ساكن على طاولة أفقية لا تؤثر فيه قوة أفقية"]'::jsonb, 'فهم', 'تمييز حالات', 'متوسط', 'الكتاب ص 139، 141، 144 — الاحتكاك السكوني'),
('mcq', 4, 'يستقر صندوق ساكنًا على سطح مائل خشن كما في الشكل الآتي. ما اتجاه قوة الاحتكاك السكوني المؤثرة في الصندوق؟', null, '[{"src":"qimg/phys1/c5l2-o02-incline-rest.svg","alt":"سطح مائل على شكل مثلث قائم، زاوية ميله θ عند قاعدته اليسرى، وعليه صندوق ساكن في منتصف السطح تقريبًا، ولا توجد أي أسهم في الشكل."}]'::jsonb, '["موازية للسطح المائل نحو أسفله","عمودية على السطح المائل","رأسيًا إلى أعلى","موازية للسطح المائل نحو أعلاه"]'::jsonb, 'فهم', 'تحديد اتجاه قوة', 'متوسط', 'الكتاب ص 144 — أولًا: عندما يكون الجسم على وشك الحركة في حالة الاحتكاك السكوني'),
('mcq', 5, 'تقف سيارة على طريق منحدر وفراملها مشدودة، وإطاراتها لا تنزلق على الطريق. ما القوة التي يؤثر بها الطريق في الإطارات فتمنعها من الانزلاق إلى أسفل المنحدر؟', null, null, '["قوة الاحتكاك الحركي","وزن السيارة إلى أسفل","قوة الاحتكاك السكوني","القوة العمودية من الطريق"]'::jsonb, 'فهم', 'تطبيق في الحياة', 'متوسط', 'الكتاب ص 139 — الاحتكاك السكوني'),
('mcq', 6, 'ماذا يحدث لقوة الاحتكاك السكوني المؤثرة في جسم ساكن إذا لم تؤثر فيه أي قوة تحاول أن تجعله يبدأ الحركة؟', null, null, '["تساوي صفرًا","تساوي قيمتها القصوى","تساوي وزن الجسم","تساوي القوة العمودية"]'::jsonb, 'تذكر', 'خاصية المفهوم', 'صعب', 'الكتاب ص 141 — الاحتكاك السكوني استجابة لقوة أخرى'),
('mcq', 7, 'عندما تمشي على رصيف دون أن تنزلق قدماك، ما نوع الاحتكاك بين نعل الحذاء والرصيف لحظة ملامسة القدم له؟', null, null, '["حركي؛ لأن الشخص يتحرك إلى الأمام","حركي؛ لأن القدم ترتفع ثم تهبط","سكوني؛ لأن الشخص ساكن بالنسبة إلى الأرض","سكوني؛ لأن النعل لا ينزلق على الرصيف"]'::jsonb, 'تحليل', 'تمييز حالة', 'صعب', 'الكتاب ص 139–140 — الاحتكاك السكوني (بين الحذاء والرصيف)'),
('essay', 1, 'عرّف الاحتكاك السكوني. ثم وضّح، من خلال موقف دفع أريكة ثقيلة على أرضية غرفة دون أن تتحرك، كيف نستنتج وجود هذه القوة باستعمال القانون الثاني لنيوتن.', null, null, null, 'فهم', 'تعريف وتوضيح', 'سهل', 'الكتاب ص 139 — الاحتكاك السكوني'),
('essay', 2, 'يستقر كتاب ساكنًا على سطح مائل خشن. (a) ارسم مخطط الجسم الحر للكتاب. (b) حدد القوة التي تمنعه من الانزلاق ونوعها واتجاهها. (c) لماذا لا يمكن أن تكون هذه القوة احتكاكًا حركيًا؟', null, null, null, 'تطبيق', 'رسم مخطط الجسم الحر', 'متوسط', 'الكتاب ص 139، 144 — الاحتكاك السكوني، أولًا وثانيًا'),
('essay', 3, 'كتاب كتلته 1.5 kg ساكن على طاولة أفقية. صف قوة الاحتكاك السكوني المؤثرة فيه (وجودها، ومقدارها، واتجاهها) في كل حالة مما يأتي، مع التعليل: (a) لا تؤثر فيه أي قوة أفقية. (b) يُدفع أفقيًا نحو اليمين بقوة 2.0 N فيبقى ساكنًا. (c) يُدفع أفقيًا نحو اليسار بقوة 3.0 N فيبقى ساكنًا.', null, null, null, 'تحليل', 'تحليل حالات', 'صعب', 'الكتاب ص 139، 141 — الاحتكاك السكوني')
