('mcq', 2, 0, 'لأن الأريكة لا تتحرك، توجد قوة أفقية من الأرضية تعاكس قوة الدفع وتساويها مقدارًا، وهذه القوة هي الاحتكاك السكوني؛ إذ لا ينزلق السطحان.', '["","الاحتكاك الحركي يتطلب انزلاق الأريكة على الأرضية، وهي لم تتحرك.","القوة العمودية رأسية، ولا يمكنها موازنة قوة الدفع الأفقية.","قوة الشد تؤثر بها الحبال والخيوط، ولا يوجد حبل هنا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-20T17:53:29.945Z"}'::jsonb),
('mcq', 3, 1, 'الكتاب على السطح المائل يميل إلى الانزلاق إلى أسفل، ولكنه لا ينزلق؛ فالسطح يؤثر فيه بقوة احتكاك سكوني موازية للسطح نحو أعلاه تمنعه من الانزلاق.', '["الصندوق ينزلق، فالاحتكاك المؤثر فيه حركي لا سكوني.","","القرص ينزلق، فالاحتكاك المؤثر فيه حركي.","إذا لم تؤثر في الجسم الساكن قوة تحاول تحريكه فإن قوة الاحتكاك السكوني تساوي صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-20T17:53:29.945Z"}'::jsonb),
('mcq', 4, 3, 'يميل الصندوق إلى الانزلاق إلى أسفل السطح، والاحتكاك السكوني يعاكس الاتجاه الذي يكون الجسم على وشك الحركة فيه، فهو موازٍ للسطح نحو أعلاه.', '["هذا اتجاه ميل الصندوق إلى الحركة، والاحتكاك يعاكسه.","القوة العمودية على السطح هي القوة العمودية، أما الاحتكاك فموازٍ للسطح.","قوة الاحتكاك موازية لسطح التلامس، والسطح هنا مائل لا أفقي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.945Z"}'::jsonb),
('mcq', 5, 2, 'الإطارات لا تنزلق على الطريق مع أنها تميل إلى الانزلاق، فالقوة الموازية للطريق التي تمنعها هي قوة الاحتكاك السكوني.', '["الاحتكاك الحركي يتطلب انزلاق الإطارات على الطريق، وهي لا تنزلق.","الوزن تؤثر به الأرض بالجاذبية، وهو الذي يسبب الميل إلى الانزلاق لا الذي يمنعه.","","القوة العمودية عمودية على الطريق، فلا تمنع الانزلاق الموازي له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-20T17:53:29.946Z"}'::jsonb),
('mcq', 6, 0, 'قوة الاحتكاك السكوني استجابة لقوة أخرى تحاول أن تجعل الجسم الساكن يبدأ حركته؛ فإذا لم تكن هناك قوة كهذه فإن قوة الاحتكاك السكوني تساوي صفرًا.', '["","تبلغ قيمتها القصوى فقط لحظة كون الجسم على وشك الحركة، لا عند غياب أي قوة.","الوزن قوة رأسية، والاحتكاك السكوني قوة موازية للسطح ولا يساويه في هذه الحالة.","القوة العمودية عمودية على السطح، والاحتكاك هنا صفر لا يساويها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-20T17:53:29.946Z"}'::jsonb),
('mcq', 7, 3, 'العبرة في نوع الاحتكاك بانزلاق السطحين المتلامسين أحدهما على الآخر لا بحركة الجسم ككل؛ والنعل لا ينزلق على الرصيف، فالاحتكاك بينهما سكوني.', '["حركة الشخص لا تعني انزلاق النعل على الرصيف، والاحتكاك الحركي يشترط الانزلاق.","ارتفاع القدم وهبوطها لا يعني انزلاقها على السطح.","التعليل خاطئ: الشخص يتحرك بالنسبة إلى الأرض، والسبب الصحيح عدم انزلاق النعل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-20T17:53:29.946Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الاحتكاك السكوني قوة تنشأ بين سطحين متلامسين بالرغم من عدم انزلاق أي منهما على الآخر. عند دفع الأريكة أفقيًا دون أن تتحرك يكون تسارعها صفرًا، فالقوة المحصلة عليها صفر وفق القانون الثاني لنيوتن؛ ولذلك لا بد من وجود قوة أفقية أخرى تؤثر في الأريكة تعاكس قوة الدفع وتساويها مقدارًا، وهذه القوة هي الاحتكاك السكوني من الأرضية.', '["تعريف الاحتكاك السكوني","الأريكة ساكنة فتسارعها صفر والقوة المحصلة صفر","وجود قوة أفقية تساوي الدفع مقدارًا وتعاكسه اتجاهًا","تسمية هذه القوة احتكاكًا سكونيًا من الأرضية"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"القوة المحصلة صفر","marks":1},{"element":"قوة مساوية معاكسة","marks":1},{"element":"تسميتها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف وتفسير كاملان"},{"level":"3 درجات","description":"تعريف مع تفسير ينقصه عنصر"},{"level":"درجتان","description":"تعريف فقط أو تفسير فقط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن قوة الدفع أصغر من وزن الأريكة فلا تتحرك.","الخلط بين الاحتكاك السكوني والقوة العمودية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-20T17:53:29.946Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) نقطة تمثل الكتاب، تخرج منها: الوزن $\boldsymbol{F}_g$ رأسيًا إلى أسفل، والقوة العمودية $\boldsymbol{F}_{\text{N}}$ عمودية على السطح المائل نحو الخارج، وقوة الاحتكاك السكوني $\boldsymbol{f}_{\text{s}}$ موازية للسطح نحو أعلاه. (b) القوة التي تمنعه من الانزلاق قوة الاحتكاك السكوني، واتجاهها موازٍ للسطح المائل نحو أعلاه، أي عكس الاتجاه الذي يميل الكتاب إلى الحركة فيه. (c) لأن الاحتكاك الحركي لا ينشأ إلا عند انزلاق أحد السطحين على الآخر، والكتاب ساكن لا ينزلق.', '["رسم الوزن رأسيًا إلى أسفل","رسم القوة العمودية عمودية على السطح المائل","رسم الاحتكاك السكوني موازيًا للسطح نحو أعلاه وتسميته","تعليل عدم كونه حركيًا: لا يوجد انزلاق"]'::jsonb, '[]'::jsonb, '[{"element":"الوزن","marks":1},{"element":"القوة العمودية","marks":1},{"element":"الاحتكاك السكوني واتجاهه","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مخطط صحيح وتحديد وتعليل صحيحان"},{"level":"3 درجات","description":"خطأ في اتجاه قوة واحدة"},{"level":"درجتان","description":"قوتان صحيحتان فقط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم القوة العمودية رأسية إلى أعلى بدل عموديتها على السطح.","رسم الاحتكاك نحو أسفل السطح."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.946Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) قوة الاحتكاك السكوني صفر؛ لأنه لا توجد قوة تحاول تحريك الكتاب، والاحتكاك السكوني استجابة لقوة أخرى. (b) قوة احتكاك سكوني مقدارها 2.0 N نحو اليسار؛ لأن الكتاب ساكن فالقوة المحصلة صفر، فالاحتكاك يساوي الدفع مقدارًا ويعاكسه اتجاهًا. (c) قوة احتكاك سكوني مقدارها 3.0 N نحو اليمين؛ للسبب نفسه. نستنتج أن الاحتكاك السكوني ليس قيمة ثابتة، بل يتغير مقداره واتجاهه بحسب القوة المؤثرة ما دام الجسم ساكنًا.', '["الحالة (a): الاحتكاك السكوني صفر مع التعليل","الحالة (b): 2.0 N نحو اليسار","الحالة (c): 3.0 N نحو اليمين","التعليل بأن القوة المحصلة على الجسم الساكن صفر"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة a","marks":1},{"element":"الحالة b","marks":1},{"element":"الحالة c","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحالات الثلاث صحيحة مع التعليل"},{"level":"3 درجات","description":"حالتان صحيحتان مع التعليل"},{"level":"درجتان","description":"حالتان صحيحتان دون تعليل"},{"level":"درجة واحدة","description":"حالة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الاحتكاك السكوني في الحالة (a) مساويًا قيمة ثابتة.","حساب الاحتكاك من الكتلة (1.5 × 9.80) بدل مساواته بقوة الدفع.","إبقاء اتجاه الاحتكاك نحو اليسار في الحالة (c)."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-20T17:53:29.947Z"}'::jsonb)
