('mcq', 6, 'يمثل مخطط الحركة الآتي قرصًا ينزلق على أرضية أفقية بعد إفلاته، حيث النقاط مواقعه على فترات زمنية متساوية والأسهم الحمراء متجهات سرعته. ما نوع قوة الاحتكاك المؤثرة في القرص واتجاهها؟', null, '[{"src":"qimg/phys1/c5l2-o03-puck-motion.svg","alt":"مخطط حركة بنموذج الجسيم النقطي: ثماني نقاط على خط أفقي، تبدأ من اليسار عند كلمة «البداية»، والمسافات بين النقاط المتتالية تتناقص تدريجيًا نحو اليمين حتى تكاد النقطتان الأخيرتان تتلاصقان. فوق النقاط أسهم حمراء نحو اليمين تمثل السرعة، أطوالها تتناقص من سهم إلى الذي يليه. في أعلى اليسار سهم نحو اليمين مكتوب عنده +x."}]'::jsonb, '["احتكاك سكوني في الاتجاه السالب","احتكاك حركي في الاتجاه الموجب","احتكاك حركي في الاتجاه السالب","احتكاك سكوني في الاتجاه الموجب"]'::jsonb, 'تحليل', 'تفسير مخطط الحركة', 'صعب', 'الكتاب ص 139، 144 — الاحتكاك الحركي؛ ص 144 المسألة 21'),
('mcq', 7, 'أيّ العبارات الآتية صحيحة عن قوة الاحتكاك الحركي المؤثرة في صندوق ينزلق على أرضية؟', null, null, '["تؤثر فقط عندما يتباطأ الصندوق","تؤثر ما دام الصندوق ينزلق، حتى لو كانت سرعته ثابتة","تنعدم عندما تصبح سرعة الصندوق ثابتة","تؤثر في اتجاه حركة الصندوق إذا كان يُدفع إلى الأمام بقوة كبيرة"]'::jsonb, 'تحليل', 'تقويم عبارات', 'صعب', 'الكتاب ص 140، 142 — الاحتكاك الحركي، المثال 3 (قوى احتكاك موازنة)'),
('essay', 1, 'عرّف الاحتكاك الحركي، واذكر موقفين من الحياة اليومية يؤثر فيهما، ثم بيّن الشرط الذي يميّز نشوءه.', null, null, null, 'تذكر', 'تعريف وأمثلة', 'سهل', 'الكتاب ص 139 — الاحتكاك الحركي'),
('essay', 2, 'يدفع عامل صندوقًا أفقيًا على أرضية خشبية فيتحرك بسرعة منتظمة نحو اليمين. (a) ارسم مخطط الجسم الحر للصندوق. (b) ما نوع الاحتكاك المؤثر فيه؟ (c) قارن بين مقداري قوة الدفع وقوة الاحتكاك مع التعليل.', null, null, null, 'فهم', 'رسم مخطط الجسم الحر', 'متوسط', 'الكتاب ص 142 — المثال 3 قوى احتكاك موازنة'),
('essay', 3, 'صندوق كتلته 20.0 kg ينزلق على أرضية أفقية نحو اليمين (الاتجاه الموجب)، ومعامل الاحتكاك الحركي بينهما 0.25. مرّ الصندوق بثلاث مراحل: (1) دُفع أفقيًا بقوة 80.0 N فتسارع. (2) دُفع أفقيًا بقوة 49.0 N فتحرك بسرعة ثابتة. (3) تُرك دون دفع فتباطأ حتى توقف. (a) حدد نوع قوة الاحتكاك واحسب مقدارها في كل مرحلة، مفسرًا لماذا يبقى مقدارها كما هو. (b) احسب تسارع الصندوق في المرحلتين (1) و(3). (c) ماذا يحدث لقوة الاحتكاك بعد أن يتوقف الصندوق؟', null, null, null, 'تحليل', 'تحليل مراحل الحركة', 'صعب', 'الكتاب ص 139–143 — الاحتكاك الحركي، المثالان 3 و4')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
