select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الاحتكاك الحركي قوة تنشأ بين سطحين متلامسين عند انزلاق أحدهما على الآخر.', '["","هذا تعريف الاحتكاك السكوني.","الاحتكاك يؤثر في اتجاه يعاكس الحركة الانزلاقية لا في اتجاهها.","هذه القوة المعيقة من الهواء، أما الاحتكاك الحركي فبين سطحين صلبين ينزلق أحدهما على الآخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-20T17:53:29.947Z"}'::jsonb),
('mcq', 2, 1, 'الصندوق ينزلق على الأرضية، والاحتكاك الذي يؤثر في الأجسام المنزلقة هو الاحتكاك الحركي.', '["الاحتكاك السكوني يؤثر عندما لا ينزلق السطحان، والصندوق هنا ينزلق.","","القيمة القصوى للاحتكاك السكوني تكون لحظة كون الجسم على وشك الحركة، لا أثناء الانزلاق.","الحركة لا تلغي الاحتكاك؛ بل يؤثر الاحتكاك الحركي ما دام الانزلاق مستمرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-20T17:53:29.947Z"}'::jsonb),
('mcq', 3, 2, 'إطارات السيارة التي تنزلق على الطريق بعد ضغط شديد على المكابح يؤثر فيها احتكاك حركي؛ لأن هناك انزلاقًا بين سطحين متلامسين.', '["الإطارات لا تنزلق، فالاحتكاك سكوني.","الصندوق لا يتحرك، فالاحتكاك سكوني.","","الكتاب ساكن لا ينزلق، فالاحتكاك سكوني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-20T17:53:29.947Z"}'::jsonb),
('mcq', 4, 3, 'السرعة منتظمة فالتسارع صفر، والقوة المحصلة صفر؛ لذلك تساوي قوة الاحتكاك الحركي قوة السحب مقدارًا وتعاكسها اتجاهًا.', '["لو كان الاحتكاك أكبر لكانت القوة المحصلة معاكسة للحركة ولتباطأ الجسم.","لو كان الاحتكاك أصغر لتسارع الجسم، والاحتكاك يعاكس الحركة لا يوافقها.","الجسم ينزلق، فيؤثر فيه احتكاك حركي لا يساوي صفرًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-20T17:53:29.948Z"}'::jsonb),
('mcq', 5, 0, 'عندما تصبح قوة الدفع أكبر من القيمة القصوى للاحتكاك السكوني تبدأ الأريكة الحركة، ويبدأ الاحتكاك الحركي في التأثير بدلًا من الاحتكاك السكوني.', '["","القيمة القصوى للاحتكاك السكوني تكون قبيل بدء الحركة، وبعد الانزلاق يحل الاحتكاك الحركي محله.","بين السطحين المتلامسين نوع واحد في كل لحظة: سكوني عند عدم الانزلاق، وحركي عند الانزلاق.","الأريكة ما زالت تلامس الأرضية وتنزلق عليها، فيؤثر فيها الاحتكاك الحركي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-20T17:53:29.948Z"}'::jsonb),
('mcq', 6, 2, 'المسافات بين النقاط تتناقص فالقرص يتباطأ وهو ينزلق في الاتجاه الموجب؛ والانزلاق يعني أن الاحتكاك حركي، وهو يعاكس الحركة، فهو في الاتجاه السالب، ولهذا يكون التسارع معاكسًا لاتجاه الحركة.', '["النوع خاطئ: القرص ينزلق على الأرضية، فالاحتكاك حركي لا سكوني.","الاتجاه خاطئ: الاحتكاك في اتجاه الحركة كان سيزيد سرعة القرص، والمخطط يبين تباطؤه.","","الخطأ مزدوج: القرص ينزلق فالاحتكاك حركي، واتجاهه معاكس للحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-20T17:53:29.948Z"}'::jsonb),
('mcq', 7, 1, 'ينشأ الاحتكاك الحركي ما دام أحد السطحين ينزلق على الآخر؛ فإذا كانت سرعة الصندوق ثابتة فهذا يعني أن قوة أخرى (الدفع) توازن الاحتكاك، لا أن الاحتكاك انعدم.', '["الاحتكاك الحركي يؤثر أثناء الانزلاق سواء تباطأ الصندوق أم تحرك بسرعة ثابتة أم تسارع.","","السرعة الثابتة تعني أن القوة المحصلة صفر، أي أن الدفع يوازن الاحتكاك لا أن الاحتكاك صفر.","الاحتكاك يعاكس الحركة الانزلاقية دائمًا مهما كانت القوى الأخرى المؤثرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-20T17:53:29.949Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الاحتكاك الحركي قوة تنشأ بين سطحين متلامسين عند انزلاق أحدهما على الآخر. من أمثلته: صندوق يُدفع فينزلق على أرضية خشبية، وإطارات سيارة تنزلق على الطريق عند الكبح الشديد (أو قرص ينزلق على أرضية خرسانية). شرط نشوئه وجود انزلاق بين السطحين المتلامسين.', '["تعريف الاحتكاك الحركي","مثال أول صحيح","مثال ثانٍ صحيح","شرط النشوء: انزلاق أحد السطحين على الآخر"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1},{"element":"الشرط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف ومثالان وشرط صحيح"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر مثال لجسم ساكن (احتكاك سكوني) على أنه احتكاك حركي.","جعل شرط النشوء «حركة الجسم» بدل انزلاق السطحين."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-20T17:53:29.949Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) نقطة تمثل الصندوق تخرج منها أربع قوى: $\boldsymbol{F}_{\text{N}}$ رأسيًا إلى أعلى، و$\boldsymbol{F}_g$ رأسيًا إلى أسفل بالطول نفسه، و$\boldsymbol{F}_{\text{الدفع}}$ أفقيًا نحو اليمين، و$\boldsymbol{f}_{\text{k}}$ أفقيًا نحو اليسار بطول قوة الدفع نفسه. (b) احتكاك حركي؛ لأن الصندوق ينزلق على الأرضية. (c) قوة الدفع تساوي قوة الاحتكاك الحركي مقدارًا وتعاكسها اتجاهًا؛ لأن السرعة منتظمة فالتسارع صفر والقوة المحصلة صفر.', '["رسم القوتين الرأسيتين متساويتين","رسم الدفع والاحتكاك أفقيين متعاكسين ومتساويين","تحديد النوع: احتكاك حركي","تساوي الدفع والاحتكاك مع التعليل بالقوة المحصلة الصفرية"]'::jsonb, '[]'::jsonb, '[{"element":"القوتان الرأسيتان","marks":1},{"element":"القوتان الأفقيتان","marks":1},{"element":"نوع الاحتكاك","marks":1},{"element":"المقارنة والتعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مخطط صحيح وإجابات صحيحة"},{"level":"3 درجات","description":"خطأ في طول سهمين أو نقص التعليل"},{"level":"درجتان","description":"مخطط ناقص مع نوع صحيح"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل قوة الدفع أكبر من الاحتكاك لأن الصندوق يتحرك.","تسمية الاحتكاك سكونيًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-20T17:53:29.949Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) في المراحل الثلاث ينزلق الصندوق على الأرضية، فالاحتكاك حركي نحو اليسار، ومقداره $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}} = \mu_{\text{k}} mg = (0.25)(20.0\ \text{kg})(9.80\ \text{m/s}^2) = 49\ \text{N}$ في كل مرحلة؛ لأنه يعتمد على معامل الاحتكاك الحركي والقوة العمودية فقط، وهما لم يتغيرا، ولا يعتمد على قوة الدفع ولا على السرعة. (b) المرحلة (1): $a = \frac{80.0\ \text{N} - 49\ \text{N}}{20.0\ \text{kg}} = +1.6\ \text{m/s}^2$. المرحلة (3): القوة الأفقية الوحيدة الاحتكاك، $a = \frac{-49\ \text{N}}{20.0\ \text{kg}} = -2.5\ \text{m/s}^2$، أي معاكس لاتجاه الحركة فيتباطأ. (c) بعد التوقف لا يوجد انزلاق، فلا يؤثر احتكاك حركي؛ ولأنه لا توجد قوة أفقية تحاول تحريك الصندوق فإن قوة الاحتكاك السكوني تساوي صفرًا.', '["الاحتكاك حركي في المراحل الثلاث ومقداره 49 N","تفسير ثبات المقدار: يعتمد على المعامل والقوة العمودية فقط","تسارع المرحلة (1): +1.6 m/s²","تسارع المرحلة (3): $-2.5\\ \\text{m/s}^2$ معاكس للحركة","بعد التوقف: لا احتكاك حركي، والاحتكاك السكوني صفر"]'::jsonb, '["$F_{\\text{N}} = mg = 20.0 \\times 9.80 = 196\\ \\text{N}$","$f_{\\text{k}} = 0.25 \\times 196 = 49\\ \\text{N}$","(1) $a = (80.0 - 49) \\div 20.0 = 1.55 \\approx 1.6\\ \\text{m/s}^2$","(3) $a = -49 \\div 20.0 = -2.45 \\approx -2.5\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"نوع الاحتكاك ومقداره","marks":1},{"element":"تفسير ثبات المقدار","marks":1},{"element":"تسارع المرحلة 1","marks":1},{"element":"تسارع المرحلة 3","marks":1},{"element":"ما بعد التوقف","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"4 درجات","description":"خطأ في عنصر واحد"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الاحتكاك في المرحلة (1) أكبر لأن الدفع أكبر، أو في المرحلة (3) صفرًا لعدم وجود دفع.","جعل تسارع المرحلة (3) موجبًا لأن الصندوق يتحرك نحو اليمين.","القول إن الاحتكاك الحركي يبقى مؤثرًا بعد توقف الصندوق."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-20T17:53:29.949Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
