from (values
('mcq', 1, 'في منحنى (قوة الاحتكاك الحركي – القوة العمودية) لجسم يُسحب على سطح معين، ماذا يمثل ميل الخط المستقيم؟', null, null, '["كتلة الجسم المسحوب","معامل الاحتكاك الحركي $\\mu_{\\text{k}}$","معامل الاحتكاك السكوني $\\mu_{\\text{s}}$","تسارع الجسم المسحوب"]'::jsonb, 'فهم', 'تفسير ميل', 'سهل', 'الكتاب ص 140 — الشكل 5-10 العلاقة بين قوة الاحتكاك والقوة العمودية'),
('mcq', 2, 'يمثل المنحنى الآتي نتائج تجربة سُحبت فيها قطعة خشبية بسرعة منتظمة على سطح طاولة، مع تغيير القوة العمودية في كل مرة. ما معامل الاحتكاك الحركي بين القطعة والسطح؟', null, '[{"src":"qimg/phys1/c5l2-o04-slope-points.svg","alt":"منحنى بياني: المحور الأفقي «القوة العمودية (N)» من 0 إلى 50 بتدريجات كل 10، والمحور الرأسي «قوة الاحتكاك الحركي (N)» من 0 إلى 16 بتدريجات كل 2. خط مستقيم يبدأ من نقطة الأصل ويمر بأربع نقاط مرسومة: (10، 3) و(20، 6) و(30، 9) و(40، 12)، ويمتد حتى (50، 15)."}]'::jsonb, '["3.3","12","0.075","0.30"]'::jsonb, 'تطبيق', 'حساب ميل من منحنى', 'متوسط', 'الكتاب ص 140 — الشكل 5-10 العلاقة بين قوة الاحتكاك والقوة العمودية'),
('mcq', 3, 'يمثل المنحنى الآتي نتائج سحب القطعة نفسها على ثلاثة أسطح مختلفة A وB وC. أيّ الخطوط يمثل السطح الأملس الذي تكون قوة الاحتكاك عليه أصغر؟ ولماذا؟', null, '[{"src":"qimg/phys1/c5l2-o04-three-lines.svg","alt":"منحنى بياني: المحور الأفقي «القوة العمودية (N)» من 0 إلى 50 بتدريجات كل 10، والمحور الرأسي «قوة الاحتكاك الحركي (N)» من 0 إلى 30 بتدريجات كل 5. ثلاثة خطوط مستقيمة تبدأ جميعها من نقطة الأصل: الخط A ينتهي عند (50، 30) وهو الأشد ميلًا، والخط B ينتهي عند (50، 20)، والخط C ينتهي عند (50، 7.5) وهو الأقل ميلًا."}]'::jsonb, '["الخط C؛ لأن ميله أصغر فمعامل الاحتكاك الحركي له أصغر","الخط A؛ لأن ميله أكبر فالقطعة تنزلق عليه بسهولة","الخط B؛ لأنه يقع في الوسط بين الخطين الآخرين","الخط A؛ لأن قوة الاحتكاك عليه أكبر عند كل قوة عمودية"]'::jsonb, 'فهم', 'مقارنة ميول', 'سهل', 'الكتاب ص 140 — الشكل 5-10 العلاقة بين قوة الاحتكاك والقوة العمودية'),
('mcq', 4, 'عند رسم بيانات قوة الاحتكاك الحركي مقابل القوة العمودية لسطح معين نحصل على خط مستقيم يمر بنقطة الأصل. ماذا تدل عليه هذه النتيجة؟', null, null, '["قوة الاحتكاك الحركي ثابتة لا تتغير بتغير القوة العمودية","قوة الاحتكاك الحركي تتناسب عكسيًا مع القوة العمودية","قوة الاحتكاك الحركي تتناسب طرديًا مع القوة العمودية","معامل الاحتكاك الحركي يزداد بزيادة القوة العمودية"]'::jsonb, 'فهم', 'تفسير شكل منحنى', 'متوسط', 'الكتاب ص 140 — «لاحظ أن هناك تناسبًا طرديًا بين قوة الاحتكاك الحركي والقوة العمودية»'),
('mcq', 5, 'يمثل المنحنى الآتي العلاقة بين قوة الاحتكاك الحركي والقوة العمودية لقطعة على سطحين A وB. باستعمال ميل الخط، ما قوة الاحتكاك الحركي على السطح B عندما تكون القوة العمودية 80 N؟', null, '[{"src":"qimg/phys1/c5l2-o04-line-b.svg","alt":"منحنى بياني: المحور الأفقي «القوة العمودية (N)» من 0 إلى 50 بتدريجات كل 10، والمحور الرأسي «قوة الاحتكاك الحركي (N)» من 0 إلى 25 بتدريجات كل 5. خطان مستقيمان يبدآن من نقطة الأصل: الخط A يمر بالنقطة المعلّمة (40، 20) وينتهي عندها، والخط B يمر بالنقطة المعلّمة (40، 10) ويمتد حتى (50، 12.5)."}]'::jsonb, '["40 N","20 N","320 N","10 N"]'::jsonb, 'تطبيق', 'استعمال ميل للتنبؤ', 'صعب', 'الكتاب ص 140 — الشكل 5-10 العلاقة بين قوة الاحتكاك والقوة العمودية'),
('mcq', 6, 'في تجربة للحصول على منحنى (قوة الاحتكاك الحركي – القوة العمودية)، تُسحب قطعة بميزان نابضي بسرعة منتظمة على سطح طاولة. كيف تُغيَّر القوة العمودية من قياس إلى آخر؟', null, null, '["بوضع كتل إضافية فوق القطعة","بزيادة سرعة سحب القطعة","بتغيير وجه القطعة الملامس للطاولة","بسحب القطعة بقوة أكبر من قراءة الميزان"]'::jsonb, 'فهم', 'إجراء تجريبي', 'سهل', 'الكتاب ص 140 — نموذج لقوى الاحتكاك (الشكل 5-9)'),
('mcq', 7, 'رُسم منحنى (قوة الاحتكاك الحركي – القوة العمودية) لقطعة على سطحين P وQ، فكان ميل خط P ضعف ميل خط Q. إذا سُحبت القطعة على كل من السطحين بالقوة العمودية نفسها، فما العلاقة بين قوتي الاحتكاك الحركي عليهما؟', null, null, '["قوة الاحتكاك على P نصف قوة الاحتكاك على Q","قوتا الاحتكاك متساويتان؛ لأن القوة العمودية واحدة","قوة الاحتكاك على P أربعة أمثال قوة الاحتكاك على Q","قوة الاحتكاك على P ضعف قوة الاحتكاك على Q"]'::jsonb, 'تحليل', 'استدلال من الميل', 'صعب', 'الكتاب ص 140 — الشكل 5-10 العلاقة بين قوة الاحتكاك والقوة العمودية'),
('essay', 1, 'سُحبت قطعة خشبية بميزان نابضي بسرعة منتظمة على سطح طاولة أفقي، ووُضعت فوقها كتل مختلفة، فسُجلت النتائج في الجدول. (a) صف شكل منحنى (قوة الاحتكاك الحركي – القوة العمودية). (b) احسب ميله. (c) ماذا يمثل هذا الميل؟ ولماذا لا وحدة له؟', '{"headers":["القوة العمودية $F_{\\text{N}}$ (N)","قوة الاحتكاك الحركي $f_{\\text{k}}$ (N)"],"rows":[["5.0","1.5"],["10.0","3.0"],["15.0","4.5"],["20.0","6.0"]]}'::jsonb, null, null, 'فهم', 'تحليل بيانات', 'متوسط', 'الكتاب ص 140 — الشكل 5-10 العلاقة بين قوة الاحتكاك والقوة العمودية'),
('essay', 2, 'يمثل المنحنى الآتي نتائج سحب القطعة نفسها على ورق صنفرة وعلى سطح طاولة أملس. (a) احسب معامل الاحتكاك الحركي لكل سطح. (b) على أي السطحين يكون سحب القطعة أصعب؟ علل. (c) احسب قوة الاحتكاك الحركي على كل سطح عندما تكون القوة العمودية 30 N.', null, '[{"src":"qimg/phys1/c5l2-o04-essay-two.svg","alt":"منحنى بياني: المحور الأفقي «القوة العمودية (N)» من 0 إلى 50 بتدريجات كل 10، والمحور الرأسي «قوة الاحتكاك الحركي (N)» من 0 إلى 25 بتدريجات كل 5. خطان مستقيمان يبدآن من نقطة الأصل: خط «ورق صنفرة» يمر بالنقطة المعلّمة (20، 12) ويمتد حتى (40، 24)، وخط «سطح طاولة أملس» يمر بالنقطة المعلّمة (40، 6) ويمتد حتى (50، 7.5)."}]'::jsonb, null, 'تحليل', 'تفسير منحنى بياني', 'صعب', 'الكتاب ص 140 — الشكل 5-10 العلاقة بين قوة الاحتكاك والقوة العمودية'),
('essay', 3, 'اعتمادًا على منحنى (قوة الاحتكاك الحركي – القوة العمودية) أجب: (a) لماذا يمر الخط بنقطة الأصل؟ (b) لو رسم طالب البيانات نفسها بعد تبديل المحورين (القوة العمودية على المحور الرأسي)، فماذا يمثل ميل الخط الجديد؟ وما قيمته إذا كان $\mu_{\text{k}} = 0.25$؟ (c) هل يتغير ميل الخط الأصلي إذا زادت الكتل الموضوعة على القطعة؟ علل.', null, null, null, 'تحليل', 'استدلال من منحنى', 'متوسط', 'الكتاب ص 140 — الشكل 5-10 العلاقة بين قوة الاحتكاك والقوة العمودية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C5-L2-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'ميل الخط = التغير في قوة الاحتكاك الحركي ÷ التغير في القوة العمودية، وهذا الميل يُسمى معامل الاحتكاك الحركي $\mu_{\text{k}}$.', '["الميل نسبة قوة إلى قوة فلا وحدة له، أما الكتلة فوحدتها kg.","","المنحنى للاحتكاك الحركي أثناء الانزلاق، أما $\\mu_{\\text{s}}$ فيرتبط بالقيمة القصوى للاحتكاك السكوني قبل الحركة.","التسارع وحدته m/s²، والميل هنا نسبة بين قوتين لا وحدة لها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-20T17:53:29.950Z"}'::jsonb),
('mcq', 2, 3, 'الميل = $\frac{\Delta f_{\text{k}}}{\Delta F_{\text{N}}} = \frac{12\ \text{N} - 3\ \text{N}}{40\ \text{N} - 10\ \text{N}} = 0.30$، والميل يساوي $\mu_{\text{k}}$.', '["قسم القوة العمودية على قوة الاحتكاك (مقلوب الميل).","قرأ قيمة قوة الاحتكاك عند 40 N بدل حساب الميل.","قسم قوة الاحتكاك عند النقطة الأولى (3 N) على القوة العمودية عند النقطة الأخيرة (40 N)، أي أخذ إحداثيين من نقطتين مختلفتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-20T17:53:29.950Z"}'::jsonb),
('mcq', 3, 0, 'ميل الخط يساوي معامل الاحتكاك الحركي؛ والسطح الأملس معامل احتكاكه أصغر، فخطه أقل الخطوط ميلًا، وهو الخط C.', '["","الميل الأكبر يعني معامل احتكاك أكبر، فيكون الانزلاق أصعب لا أسهل.","موقع الخط بين الخطين الآخرين لا يجعل الاحتكاك عليه أصغر؛ فميله متوسط.","العبارة عن الخط A صحيحة، لكنها تجعله السطح الأخشن لا الأملس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-20T17:53:29.950Z"}'::jsonb),
('mcq', 4, 2, 'الخط المستقيم المار بنقطة الأصل يعني تناسبًا طرديًا: إذا تضاعفت القوة العمودية تضاعفت قوة الاحتكاك الحركي، وثابت التناسب (الميل) هو $\mu_{\text{k}}$.', '["لو كانت قوة الاحتكاك ثابتة لكان الخط أفقيًا لا مائلًا.","التناسب العكسي لا يُمثَّل بخط مستقيم صاعد يمر بالأصل.","","الميل ثابت على طول الخط المستقيم، فمعامل الاحتكاك الحركي لا يتغير بتغير القوة العمودية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-20T17:53:29.951Z"}'::jsonb),
('mcq', 5, 1, 'ميل الخط B = $\frac{10\ \text{N}}{40\ \text{N}} = 0.25 = \mu_{\text{k}}$، ومنه $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}} = (0.25)(80\ \text{N}) = 20\ \text{N}$.', '["استعمل ميل الخط A (0.50) بدل ميل الخط B.","","قسم القوة العمودية على الميل بدل ضربها فيه.","قرأ قيمة قوة الاحتكاك على الخط B عند 40 N دون استعمال الميل للقوة العمودية المطلوبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-20T17:53:29.951Z"}'::jsonb),
('mcq', 6, 0, 'وضع كتل إضافية فوق القطعة يزيد القوة العمودية بين القطعة والطاولة، ثم يُعاد قياس قوة الاحتكاك الحركي بالميزان النابضي.', '["","سرعة السحب لا تغير القوة العمودية، ويجب أن تبقى السرعة منتظمة.","تغيير الوجه يغير مساحة التلامس فقط، ولا يغير القوة العمودية.","السحب الأفقي لا يغير القوة العمودية، وسحب القطعة بقوة أكبر من الاحتكاك يجعلها تتسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-20T17:53:29.951Z"}'::jsonb),
('mcq', 7, 3, 'الميل هو $\mu_{\text{k}}$، فمعامل الاحتكاك على P ضعف معامله على Q؛ ولأن $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}}$ والقوة العمودية واحدة، تكون قوة الاحتكاك على P ضعف قوتها على Q.', '["عكس العلاقة: الميل الأكبر يعني قوة احتكاك أكبر لا أصغر.","تساوي القوة العمودية لا يكفي؛ فقوة الاحتكاك تعتمد أيضًا على معامل الاحتكاك (الميل).","العلاقة خطية؛ فمضاعفة المعامل تضاعف القوة مرة واحدة لا أربع مرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-20T17:53:29.951Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) خط مستقيم يمر بنقطة الأصل، أي تتناسب قوة الاحتكاك الحركي طرديًا مع القوة العمودية. (b) الميل = $\frac{6.0\ \text{N} - 1.5\ \text{N}}{20.0\ \text{N} - 5.0\ \text{N}} = 0.30$. (c) الميل يمثل معامل الاحتكاك الحركي $\mu_{\text{k}} = 0.30$ بين القطعة والطاولة، ولا وحدة له لأنه ناتج قسمة قوة (N) على قوة (N).', '["خط مستقيم يمر بالأصل (تناسب طردي)","حساب الميل من نقطتين = 0.30","الميل يمثل معامل الاحتكاك الحركي","لا وحدة للمعامل لأنه نسبة بين قوتين"]'::jsonb, '["الميل = $\\frac{\\Delta f_{\\text{k}}}{\\Delta F_{\\text{N}}}$","$\\frac{6.0 - 1.5}{20.0 - 5.0} = \\frac{4.5}{15.0} = 0.30$","$\\mu_{\\text{k}} = 0.30$"]'::jsonb, '[{"element":"وصف المنحنى","marks":1},{"element":"حساب الميل","marks":2},{"element":"تفسير الميل","marks":1},{"element":"سبب انعدام الوحدة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"4 درجات","description":"خطأ بسيط في الحساب أو في سبب الوحدة"},{"level":"3 درجات","description":"الميل صحيح دون تفسير كامل"},{"level":"درجتان","description":"وصف صحيح للمنحنى وتفسير الميل دون حساب"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة القوة العمودية على قوة الاحتكاك.","كتابة وحدة N للمعامل.","وصف العلاقة بأنها عكسية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-20T17:53:29.952Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) ورق الصنفرة: الميل = $\frac{12\ \text{N}}{20\ \text{N}} = 0.60$؛ سطح الطاولة الأملس: الميل = $\frac{6\ \text{N}}{40\ \text{N}} = 0.15$. (b) سحب القطعة على ورق الصنفرة أصعب؛ لأن ميل خطه أكبر، أي معامل احتكاكه الحركي أكبر، فقوة الاحتكاك عند القوة العمودية نفسها أكبر (أربعة أمثالها هنا). (c) ورق الصنفرة: $f_{\text{k}} = (0.60)(30\ \text{N}) = 18\ \text{N}$؛ السطح الأملس: $f_{\text{k}} = (0.15)(30\ \text{N}) = 4.5\ \text{N}$.', '["معامل ورق الصنفرة 0.60","معامل السطح الأملس 0.15","السحب أصعب على ورق الصنفرة لأن الميل (المعامل) أكبر","قوتا الاحتكاك عند 30 N: 18 N و4.5 N"]'::jsonb, '["$\\mu_{\\text{k}}$ (صنفرة) = 12 ÷ 20 = 0.60","$\\mu_{\\text{k}}$ (أملس) = 6 ÷ 40 = 0.15","المقارنة: 0.60 > 0.15","$f_{\\text{k}} = 0.60 \\times 30 = 18\\ \\text{N}$ و$f_{\\text{k}} = 0.15 \\times 30 = 4.5\\ \\text{N}$"]'::jsonb, '[{"element":"معامل الصنفرة","marks":1},{"element":"معامل السطح الأملس","marks":1},{"element":"المقارنة والتعليل","marks":1},{"element":"قوتا الاحتكاك","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"4 درجات","description":"خطأ في قوة احتكاك واحدة"},{"level":"3 درجات","description":"المعاملان والمقارنة صحيحة فقط"},{"level":"درجتان","description":"معامل واحد مع مقارنة صحيحة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قراءة نقطتين من خطين مختلفين عند حساب الميل.","القول إن السطح الأملس أصعب لأن خطه أطول أفقيًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-20T17:53:29.952Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) لأنه عندما تكون القوة العمودية صفرًا (لا يضغط الجسم على السطح) تكون قوة الاحتكاك الحركي صفرًا، فـ $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}}$ علاقة تناسب طردي. (b) الميل الجديد = $\frac{\Delta F_{\text{N}}}{\Delta f_{\text{k}}} = \frac{1}{\mu_{\text{k}}} = \frac{1}{0.25} = 4.0$، أي مقلوب معامل الاحتكاك الحركي. (c) لا يتغير؛ لأن زيادة الكتل تزيد القوة العمودية وقوة الاحتكاك بالنسبة نفسها، فننتقل إلى نقطة أخرى على الخط نفسه، والميل يعتمد على نوع مادتي السطحين فقط.', '["انعدام الاحتكاك عند انعدام القوة العمودية (تناسب طردي)","الميل بعد تبديل المحورين يساوي مقلوب المعامل","حساب 4.0","الميل لا يتغير بزيادة الكتل مع التعليل"]'::jsonb, '["الميل الجديد = $\\frac{1}{\\mu_{\\text{k}}}$","$\\frac{1}{0.25} = 4.0$"]'::jsonb, '[{"element":"مرور الخط بالأصل","marks":1},{"element":"معنى الميل الجديد","marks":1},{"element":"قيمته","marks":1},{"element":"ثبات الميل والتعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الميل الجديد يساوي $\\mu_{\\text{k}}$ أيضًا.","القول إن زيادة الكتل تزيد الميل."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-20T17:53:29.952Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
