from (values
('mcq', 1, 'أيّ العلاقات الآتية تربط مقدار قوة الاحتكاك الحركي بمقدار القوة العمودية؟', null, null, '["$f_{\\text{k}} = \\frac{\\mu_{\\text{k}}}{F_{\\text{N}}}$","$f_{\\text{k}} = \\mu_{\\text{k}} + F_{\\text{N}}$","$f_{\\text{k}} = \\mu_{\\text{k}} F_{\\text{N}}$","$f_{\\text{k}} \\le \\mu_{\\text{k}} F_{\\text{N}}$"]'::jsonb, 'تذكر', 'تذكر علاقة', 'سهل', 'الكتاب ص 140 — معامل الاحتكاك الحركي وعلاقة قوة الاحتكاك الحركي'),
('mcq', 2, 'ما وحدة قياس معامل الاحتكاك الحركي؟', null, null, '["لا وحدة له (عدد مجرد)","وحدة القوة نيوتن (N)","نيوتن لكل كيلوجرام (N/kg)","وحدة الكتلة كيلوجرام (kg)"]'::jsonb, 'تذكر', 'وحدة القياس', 'سهل', 'الكتاب ص 140 — معامل الاحتكاك الحركي وعلاقة قوة الاحتكاك الحركي'),
('mcq', 3, 'ما الذي يمثله معامل الاحتكاك الحركي $\mu_{\text{k}}$؟', null, null, '["حاصل ضرب قوة الاحتكاك الحركي في القوة العمودية","نسبة القوة العمودية إلى قوة الاحتكاك الحركي","نسبة قوة الاحتكاك الحركي إلى كتلة الجسم","نسبة قوة الاحتكاك الحركي إلى القوة العمودية"]'::jsonb, 'تذكر', 'تذكر تعريف', 'متوسط', 'الكتاب ص 140 — معامل الاحتكاك الحركي وعلاقة قوة الاحتكاك الحركي'),
('mcq', 4, 'صندوق خشبي ينزلق على أرضية خشبية، والقوة العمودية عليه 180 N، ومعامل الاحتكاك الحركي بينهما 0.20. ما مقدار قوة الاحتكاك الحركي المؤثرة فيه؟', null, null, '["900 N","36 N","180 N","353 N"]'::jsonb, 'تطبيق', 'تعويض في علاقة', 'متوسط', 'الكتاب ص 140، 142 — قوة الاحتكاك الحركي، المثال 3'),
('mcq', 5, 'يبين الجدول الآتي معاملات الاحتكاك بين بعض السطوح. إذا انزلق جسم على كل سطح منها والقوة العمودية واحدة، فعلى أيّها تكون قوة الاحتكاك الحركي أصغر؟', '{"headers":["السطح","$\\mu_{\\text{s}}$","$\\mu_{\\text{k}}$"],"rows":[["مطاط فوق خرسانة جافة","0.80","0.65"],["خشب فوق خشب","0.50","0.20"],["فولاذ فوق فولاذ جاف","0.78","0.58"],["فولاذ فوق فولاذ (مع الزيت)","0.15","0.06"]]}'::jsonb, null, '["خشب فوق خشب","مطاط فوق خرسانة جافة","فولاذ فوق فولاذ مع الزيت","فولاذ فوق فولاذ جاف"]'::jsonb, 'فهم', 'قراءة جدول', 'متوسط', 'الكتاب ص 141 — الجدول 5-1 معاملات الاحتكاك المثالية'),
('mcq', 6, 'يسحب فتى زلاجة وزنها 75 N بقوة أفقية مقدارها 18 N على أرض أفقية فتتحرك بسرعة منتظمة. ما معامل الاحتكاك الحركي بين الزلاجة والأرض؟ (أهمل مقاومة الهواء)', null, null, '["0.24","4.2","0.024","2.4"]'::jsonb, 'تطبيق', 'حساب المعامل', 'صعب', 'الكتاب ص 142 — المسألة 15'),
('mcq', 7, 'لماذا تُكتب العلاقة $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}}$ بمقادير القوى فقط لا بمتجهاتها؟', null, null, '["لأن قوة الاحتكاك ليست كمية متجهة بل قياسية","لأن قوة الاحتكاك والقوة العمودية متعامدتان","لأن القوة العمودية تساوي وزن الجسم في كل الحالات","لأن معامل الاحتكاك الحركي كمية متجهة لها اتجاه"]'::jsonb, 'فهم', 'تفسير صياغة علاقة', 'صعب', 'الكتاب ص 141 — «كلٌّ من معادلة الاحتكاك الحركي ومعادلة الاحتكاك السكوني تحتوي على مقادير القوى فقط»'),
('essay', 1, 'عرّف معامل الاحتكاك الحركي، واكتب العلاقة التي تربط قوة الاحتكاك الحركي بالقوة العمودية، موضحًا معنى كل رمز فيها ووحدته.', null, null, null, 'تذكر', 'تعريف وعلاقة', 'سهل', 'الكتاب ص 140 — معامل الاحتكاك الحركي وعلاقة قوة الاحتكاك الحركي'),
('essay', 2, 'يُدفع صندوق خشبي كتلته 30.0 kg أفقيًا على أرضية خشبية، ومعامل الاحتكاك الحركي بينهما 0.20. (a) احسب القوة العمودية. (b) احسب قوة الاحتكاك الحركي. (c) ما مقدار قوة الدفع اللازمة لتحريك الصندوق بسرعة منتظمة؟', null, null, null, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 142 — المثال 3'),
('essay', 3, 'قطعتا فولاذ في آلة تُدلك إحداهما بالأخرى، والقوة العمودية بينهما 50.0 N. باستعمال قيم الجدول: (a) احسب قوة الاحتكاك الحركي بينهما وهما جافتان، ثم بعد معالجتهما بالزيت. (b) كم مرة تقريبًا يقلّ الاحتكاك بالمعالجة بالزيت؟ (c) فسّر لماذا تُعالَج أجزاء الآلات بالزيت.', '{"headers":["السطح","$\\mu_{\\text{s}}$","$\\mu_{\\text{k}}$"],"rows":[["فولاذ فوق فولاذ جاف","0.78","0.58"],["فولاذ فوق فولاذ (مع الزيت)","0.15","0.06"]]}'::jsonb, null, null, 'تحليل', 'مقارنة باستعمال جدول', 'صعب', 'الكتاب ص 141 — الجدول 5-1 معاملات الاحتكاك المثالية؛ ص 143 المسألة 18')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
