from (values
('mcq', 1, 2, 'قوة الاحتكاك الحركي تساوي حاصل ضرب معامل الاحتكاك الحركي في القوة العمودية: $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}}$.', '["القسمة تجعل الاحتكاك يقل بزيادة القوة العمودية، والصحيح أنه يتناسب معها طرديًا.","لا يمكن جمع عدد لا وحدة له مع قوة؛ والعلاقة ضرب لا جمع.","","إشارة (≤) خاصة بالاحتكاك السكوني؛ أما الاحتكاك الحركي فقيمته تساوي $\\mu_{\\text{k}} F_{\\text{N}}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-20T17:53:29.953Z"}'::jsonb),
('mcq', 2, 0, 'معامل الاحتكاك الحركي $\mu_{\text{k}} = \frac{f_{\text{k}}}{F_{\text{N}}}$ ناتج قسمة قوة على قوة، فتختصر الوحدتان ولا وحدة له.', '["","N وحدة القوة، والمعامل نسبة بين قوتين.","N/kg وحدة شدة مجال الجاذبية لا معامل الاحتكاك.","kg وحدة الكتلة، والمعامل لا يرتبط بالكتلة مباشرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-20T17:53:29.953Z"}'::jsonb),
('mcq', 3, 3, 'من العلاقة $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}}$ نجد $\mu_{\text{k}} = \frac{f_{\text{k}}}{F_{\text{N}}}$، أي نسبة قوة الاحتكاك الحركي إلى القوة العمودية، وهي ميل منحنى (قوة الاحتكاك الحركي – القوة العمودية).', '["الضرب يعطي كمية وحدتها N²، والمعامل نسبة لا حاصل ضرب.","هذه مقلوب المعامل.","المعامل يُنسب إلى القوة العمودية لا إلى الكتلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-20T17:53:29.953Z"}'::jsonb),
('mcq', 4, 1, '$f_{\text{k}} = \mu_{\text{k}} F_{\text{N}} = (0.20)(180\ \text{N}) = 36\ \text{N}$.', '["قسم القوة العمودية على المعامل بدل ضربها فيه.","","أهمل المعامل وجعل الاحتكاك يساوي القوة العمودية.","عامل القوة العمودية (180 N) معاملة الكتلة فضربها في g أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-20T17:53:29.954Z"}'::jsonb),
('mcq', 5, 2, 'عند تساوي القوة العمودية تتناسب قوة الاحتكاك الحركي مع $\mu_{\text{k}}$، وأصغر قيمة لـ $\mu_{\text{k}}$ في الجدول هي 0.06 لفولاذ فوق فولاذ مع الزيت.', '["معامل الاحتكاك الحركي للخشب على الخشب 0.20، وهو أكبر من 0.06.","هذا السطح له أكبر معامل احتكاك حركي (0.65)، فقوة الاحتكاك عليه أكبر.","","معامل الفولاذ الجاف 0.58، والزيت يقلله كثيرًا إلى 0.06."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.954Z"}'::jsonb),
('mcq', 6, 0, 'السرعة منتظمة، فقوة الاحتكاك الحركي تساوي قوة السحب: $f_{\text{k}} = 18\ \text{N}$، والقوة العمودية تساوي الوزن: $F_{\text{N}} = 75\ \text{N}$؛ إذن $\mu_{\text{k}} = \frac{f_{\text{k}}}{F_{\text{N}}} = \frac{18\ \text{N}}{75\ \text{N}} = 0.24$.', '["","قسم القوة العمودية على قوة الاحتكاك (مقلوب المعامل).","عامل الوزن معاملة الكتلة فضربه في g ليحصل على القوة العمودية.","قسم قوة الاحتكاك على الكتلة (75 ÷ 9.80) بدل القوة العمودية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-20T17:53:29.954Z"}'::jsonb),
('mcq', 7, 1, 'قوة الاحتكاك موازية لسطح التلامس، والقوة العمودية عمودية عليه، فالزاوية بينهما قائمة؛ ولذلك لا يمكن أن يكون متجه الاحتكاك حاصل ضرب عدد في متجه القوة العمودية، فتُكتب العلاقة بالمقادير فقط.', '["قوة الاحتكاك قوة لها مقدار واتجاه، فهي كمية متجهة.","","القوة العمودية لا تساوي الوزن دائمًا (كما على السطح المائل)، وهذا لا يفسر كتابة المقادير.","المعامل نسبة بين مقداري قوتين، فهو كمية قياسية لا متجهة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-20T17:53:29.954Z"}'::jsonb),
('essay', 1, null::int, null, null, 'معامل الاحتكاك الحركي هو ميل منحنى (قوة الاحتكاك الحركي – القوة العمودية)، أي نسبة قوة الاحتكاك الحركي إلى القوة العمودية بين سطحين ينزلق أحدهما على الآخر. العلاقة: $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}}$، حيث $f_{\text{k}}$ مقدار قوة الاحتكاك الحركي بوحدة N، و$\mu_{\text{k}}$ معامل الاحتكاك الحركي ولا وحدة له، و$F_{\text{N}}$ مقدار القوة العمودية بوحدة N.', '["تعريف المعامل نسبةً أو ميلًا","كتابة العلاقة صحيحة","معنى الرموز الثلاثة","الوحدات: N لكل من القوتين ولا وحدة للمعامل"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"العلاقة","marks":1},{"element":"معنى الرموز","marks":1},{"element":"الوحدات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إعطاء المعامل وحدة N.","كتابة العلاقة بإشارة ≤."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-20T17:53:29.954Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) الصندوق على سطح أفقي ولا تسارع رأسيًا: $F_{\text{N}} = mg = (30.0\ \text{kg})(9.80\ \text{m/s}^2) = 294\ \text{N}$. (b) $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}} = (0.20)(294\ \text{N}) = 59\ \text{N}$. (c) عند السرعة المنتظمة القوة المحصلة صفر، فقوة الدفع تساوي قوة الاحتكاك: 59 N في اتجاه الحركة.', '["القوة العمودية 294 N","قوة الاحتكاك الحركي 59 N","قوة الدفع تساوي قوة الاحتكاك عند السرعة المنتظمة: 59 N"]'::jsonb, '["$F_{\\text{N}} = mg = 30.0 \\times 9.80 = 294\\ \\text{N}$","$f_{\\text{k}} = 0.20 \\times 294 = 58.8 \\approx 59\\ \\text{N}$","$F_{\\text{الدفع}} = f_{\\text{k}} = 59\\ \\text{N}$"]'::jsonb, '[{"element":"القوة العمودية","marks":1},{"element":"قوة الاحتكاك","marks":2},{"element":"قوة الدفع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة بأرقام معنوية صحيحة"},{"level":"3 درجات","description":"خطأ في الأرقام المعنوية أو الوحدة"},{"level":"درجتان","description":"القوة العمودية والاحتكاك فقط"},{"level":"درجة واحدة","description":"القوة العمودية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب المعامل في الكتلة مباشرة (6.0 N).","جعل قوة الدفع أكبر من الاحتكاك عند السرعة المنتظمة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-20T17:53:29.955Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) جافتان: $f_{\text{k}} = (0.58)(50.0\ \text{N}) = 29\ \text{N}$؛ مع الزيت: $f_{\text{k}} = (0.06)(50.0\ \text{N}) = 3\ \text{N}$ (المعامل 0.06 برقم معنوي واحد). (b) 29 ÷ 3 ≈ 10، أي يقل الاحتكاك نحو عشر مرات (وهي نسبة المعاملين 0.58 ÷ 0.06). (c) لأن الزيت يقلل معامل الاحتكاك الحركي، فتقل قوة الاحتكاك عند القوة العمودية نفسها، فيلزم قوة أقل لتحريك الأجزاء ويقل تآكلها.', '["قوة الاحتكاك الجافة 29 N","قوة الاحتكاك مع الزيت 3 N","النسبة نحو 10 مرات","التفسير: الزيت يقلل المعامل فيقل الاحتكاك"]'::jsonb, '["$f_{\\text{k}}$ (جاف) $= 0.58 \\times 50.0 = 29\\ \\text{N}$","$f_{\\text{k}}$ (زيت) $= 0.06 \\times 50.0 = 3\\ \\text{N}$","النسبة = 29 ÷ 3 ≈ 10"]'::jsonb, '[{"element":"الاحتكاك الجاف","marks":1},{"element":"الاحتكاك مع الزيت","marks":1},{"element":"النسبة","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال $\\mu_{\\text{s}}$ بدل $\\mu_{\\text{k}}$ للقطع المنزلقة.","القول إن الزيت يقلل القوة العمودية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-20T17:53:29.955Z"}'::jsonb)
