('mcq', 3, 'يبين الجدول الآتي معاملات احتكاك بين أسطح مختلفة. إذا وُضع جسم على كل سطح والقوة العمودية واحدة، فعلى أيّ سطح يلزم أكبر قوة أفقية لبدء انزلاقه؟', '{"headers":["السطح","$\\mu_{\\text{s}}$","$\\mu_{\\text{k}}$"],"rows":[["مطاط فوق خرسانة جافة","0.80","0.65"],["مطاط فوق خرسانة رطبة","0.60","0.40"],["خشب فوق خشب","0.50","0.20"],["فولاذ فوق فولاذ جاف","0.78","0.58"]]}'::jsonb, null, '["مطاط فوق خرسانة جافة","فولاذ فوق فولاذ جاف","مطاط فوق خرسانة رطبة","خشب فوق خشب"]'::jsonb, 'فهم', 'قراءة جدول', 'متوسط', 'الكتاب ص 141 — الجدول 5-1'),
('mcq', 4, 'طاولة كتلتها 35.0 kg على أرضية أفقية، ومعامل الاحتكاك السكوني بينهما 0.450. ما أكبر قوة أفقية يمكن أن تؤثر في الطاولة دون أن تحركها؟', null, null, '["15.8 N","762 N","154 N","343 N"]'::jsonb, 'تطبيق', 'حساب القيمة القصوى', 'متوسط', 'الكتاب ص 145 — المراجعة 26'),
('mcq', 5, 'صندوق ساكن على أرضية أفقية تؤثر فيه قوة أفقية، وقوة الاحتكاك السكوني عليه أقل من $\mu_{\text{s}} F_{\text{N}}$. ماذا يعني ذلك؟', null, null, '["الصندوق ينزلق على الأرضية بسرعة ثابتة","القوة المؤثرة لم تبلغ القيمة القصوى، فيبقى ساكنًا","الصندوق على وشك أن يبدأ الحركة في اللحظة نفسها تمامًا","معامل الاحتكاك السكوني أكبر من واحد"]'::jsonb, 'فهم', 'تفسير علاقة', 'متوسط', 'الكتاب ص 141 — قوة الاحتكاك السكوني ومعامل الاحتكاك السكوني'),
('mcq', 6, 'أيّ العبارات الآتية صحيحة عن معامل الاحتكاك السكوني $\mu_{\text{s}}$؟', null, null, '["يُقاس بوحدة N لأنه يحدد قوة الاحتكاك","قيمته أقل من واحد في جميع الظروف ولجميع السطوح","يساوي قوة الاحتكاك السكوني القصوى نفسها","لا وحدة له، وقد تزيد قيمته على واحد أحيانًا"]'::jsonb, 'فهم', 'خصائص المعامل', 'صعب', 'الكتاب ص 141 — «لاحظ أن معاملات الاحتكاك المدرجة أقل من واحد، وهذا لا يعني أنها أقل من واحد دائمًا»'),
('mcq', 7, 'صندوق وزنه 240 N على أرضية أفقية، ووُجد أن أقل قوة أفقية تجعله يبدأ الحركة 96 N. ما معامل الاحتكاك السكوني بين الصندوق والأرضية؟', null, null, '["0.40","2.5","0.041","3.9"]'::jsonb, 'تطبيق', 'حساب المعامل', 'صعب', 'الكتاب ص 142 — المسألة 16'),
('essay', 1, 'عرّف معامل الاحتكاك السكوني، واكتب علاقة قوة الاحتكاك السكوني، ثم وضّح لماذا تحتوي العلاقة على إشارة (≤)، ومتى تتحقق المساواة.', null, null, null, 'تذكر', 'تعريف وعلاقة', 'سهل', 'الكتاب ص 141 — قوة الاحتكاك السكوني ومعامل الاحتكاك السكوني'),
('essay', 2, 'قرر بعض الطلاب بناء عربة خشبية كتلتها 25.0 kg فوق زلاجة، وجلس عليها راكبان كتلة كل منهما 70.0 kg على أرض ثلجية أفقية. إذا كان معامل الاحتكاك السكوني بين العربة والثلج 0.12، فما أقل قوة أفقية يجب أن يسحب بها شخص العربة لكي تبدأ الحركة؟', null, null, null, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 159 — اختبار مقنن السؤال 3'),
