from (values
('mcq', 1, 1, 'قوة الاحتكاك السكوني أقل من أو تساوي حاصل ضرب معامل الاحتكاك السكوني في القوة العمودية: $f_{\text{s}} \le \mu_{\text{s}} F_{\text{N}}$.', '["المساواة تتحقق فقط لحظة كون الجسم على وشك الحركة، لا دائمًا.","","لا يمكن أن يتجاوز الاحتكاك السكوني قيمته القصوى؛ فإذا تجاوزتها القوة المؤثرة بدأت الحركة.","القيمة القصوى حاصل ضرب المعامل في القوة العمودية لا ناتج القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-20T17:53:29.955Z"}'::jsonb),
('mcq', 2, 3, '$\mu_{\text{s}} F_{\text{N}}$ يمثل قوة الاحتكاك السكوني القصوى التي يجب التغلب عليها قبل بدء الحركة.', '["قوة الاحتكاك الحركي تساوي $\\mu_{\\text{k}} F_{\\text{N}}$ لا $\\mu_{\\text{s}} F_{\\text{N}}$.","القوة العمودية هي $F_{\\text{N}}$ وحدها دون ضربها في المعامل.","الاحتكاك السكوني يتغير بحسب القوة المؤثرة، ولا يساوي $\\mu_{\\text{s}} F_{\\text{N}}$ إلا عند قيمته القصوى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-20T17:53:29.956Z"}'::jsonb),
('mcq', 3, 0, 'بدء الحركة يتطلب التغلب على القيمة القصوى للاحتكاك السكوني $\mu_{\text{s}} F_{\text{N}}$؛ وعند تساوي القوة العمودية تكون أكبر قوة لأكبر $\mu_{\text{s}}$، وهو 0.80 لمطاط فوق خرسانة جافة.', '["","$\\mu_{\\text{s}}$ للفولاذ الجاف 0.78، وهو قريب لكنه أصغر من 0.80.","الرطوبة تقلل المعامل إلى 0.60، فالقوة اللازمة أصغر.","$\\mu_{\\text{s}}$ للخشب على الخشب 0.50، وهو من أصغر القيم في الجدول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-20T17:53:29.956Z"}'::jsonb),
('mcq', 4, 2, '$F_{\text{N}} = mg = (35.0\ \text{kg})(9.80\ \text{m/s}^2) = 343\ \text{N}$، وأكبر قوة دون حركة تساوي القيمة القصوى للاحتكاك السكوني: $\mu_{\text{s}} F_{\text{N}} = (0.450)(343\ \text{N}) = 154\ \text{N}$.', '["ضرب المعامل في الكتلة مباشرة ونسي ضربها في g.","قسم القوة العمودية على المعامل بدل ضربها فيه.","","هذه القوة العمودية (الوزن)، ونسي ضربها في معامل الاحتكاك السكوني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-20T17:53:29.956Z"}'::jsonb),
('mcq', 5, 1, 'ما دام الصندوق ساكنًا فقوة الاحتكاك السكوني تساوي القوة المؤثرة؛ وكونها أقل من $\mu_{\text{s}} F_{\text{N}}$ يعني أن القوة المؤثرة لم تصل بعد إلى القيمة القصوى، فلا يبدأ الصندوق الحركة.', '["الانزلاق يعني احتكاكًا حركيًا، أما العلاقة هنا فللاحتكاك السكوني والصندوق ساكن.","","يكون الجسم على وشك الحركة عندما يساوي الاحتكاك السكوني قيمته القصوى تمامًا، لا عندما يكون أقل منها.","قيمة المعامل لا تُستنتج من هذه المقارنة؛ فهي تعتمد على نوع السطحين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-20T17:53:29.956Z"}'::jsonb),
('mcq', 6, 3, 'المعامل نسبة بين قوتين فلا وحدة له؛ ومعاملات الاحتكاك المألوفة أقل من واحد، لكن هذا لا يعني أنها أقل من واحد دائمًا، فقد تزيد عليه في بعض الظروف الخاصة.', '["المعامل نسبة بين قوتين فتختصر الوحدتان، والقوة القصوى هي التي تقاس بـ N.","القيم المدرجة في الجداول أقل من واحد، لكنها قد تزيد على واحد في بعض الظروف.","القيمة القصوى للاحتكاك السكوني تساوي المعامل مضروبًا في القوة العمودية لا المعامل وحده.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-20T17:53:29.957Z"}'::jsonb),
('mcq', 7, 0, 'لحظة بدء الحركة تساوي القوة المؤثرة القيمة القصوى للاحتكاك السكوني: $\mu_{\text{s}} F_{\text{N}} = 96\ \text{N}$، و$F_{\text{N}} = 240\ \text{N}$، إذن $\mu_{\text{s}} = \frac{96\ \text{N}}{240\ \text{N}} = 0.40$.', '["","قسم القوة العمودية على القوة المؤثرة (مقلوب المعامل).","عامل الوزن معاملة الكتلة فضربه في g ليحصل على القوة العمودية.","قسم القوة على الكتلة (240 ÷ 9.80) بدل القوة العمودية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-20T17:53:29.957Z"}'::jsonb),
('essay', 1, null::int, null, null, 'معامل الاحتكاك السكوني $\mu_{\text{s}}$ عدد لا وحدة له يربط القيمة القصوى لقوة الاحتكاك السكوني بالقوة العمودية بين سطحين، ويعتمد على نوع مادتيهما. العلاقة: $f_{\text{s}} \le \mu_{\text{s}} F_{\text{N}}$. تحتوي على (≤) لأن قوة الاحتكاك السكوني ليست قيمة ثابتة؛ فهي استجابة للقوة التي تحاول تحريك الجسم، تبدأ من الصفر وتزداد بزيادتها. وتتحقق المساواة $f_{\text{s}} = \mu_{\text{s}} F_{\text{N}}$ عندما يكون الجسم على وشك الحركة، أي عند القيمة القصوى للاحتكاك السكوني.', '["تعريف المعامل","كتابة العلاقة","تفسير إشارة ≤ بتغير الاحتكاك السكوني مع القوة المؤثرة","المساواة لحظة كون الجسم على وشك الحركة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"العلاقة","marks":1},{"element":"تفسير الإشارة","marks":1},{"element":"شرط المساواة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الإشارة تعني أن المعامل أقل من واحد.","جعل المساواة تتحقق دائمًا ما دام الجسم ساكنًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-20T17:53:29.957Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الكتلة الكلية: $m = 25.0 + 2(70.0) = 165.0\ \text{kg}$. القوة العمودية: $F_{\text{N}} = mg = (165.0\ \text{kg})(9.80\ \text{m/s}^2) = 1617\ \text{N}$. القيمة القصوى للاحتكاك السكوني: $\mu_{\text{s}} F_{\text{N}} = (0.12)(1617\ \text{N}) = 194\ \text{N}$. إذن يجب أن تزيد القوة قليلًا على $1.9 \times 10^2\ \text{N}$ لتبدأ العربة الحركة.', '["حساب الكتلة الكلية 165.0 kg","حساب القوة العمودية","حساب القيمة القصوى للاحتكاك السكوني","التقريب للأرقام المعنوية الصحيحة 1.9 × 10² N"]'::jsonb, '["$m = 25.0 + 2 \\times 70.0 = 165.0\\ \\text{kg}$","$F_{\\text{N}} = 165.0 \\times 9.80 = 1617\\ \\text{N}$","$\\mu_{\\text{s}} F_{\\text{N}} = 0.12 \\times 1617 = 194\\ \\text{N} \\approx 1.9 \\times 10^2\\ \\text{N}$"]'::jsonb, '[{"element":"الكتلة الكلية","marks":1},{"element":"القوة العمودية","marks":1},{"element":"القيمة القصوى","marks":1},{"element":"الأرقام المعنوية والوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل صحيح"},{"level":"3 درجات","description":"خطأ في الأرقام المعنوية أو نسيان أحد الراكبين"},{"level":"درجتان","description":"القوة العمودية صحيحة فقط"},{"level":"درجة واحدة","description":"الكتلة الكلية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال كتلة أحد الراكبين أو كتلة العربة.","استعمال الكتلة بدل القوة العمودية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-20T17:53:29.957Z"}'::jsonb),
('essay', 3, null::int, null, null, 'إذا كان $\mu_{\text{s}} > 1$ فإن القيمة القصوى لقوة الاحتكاك السكوني $\mu_{\text{s}} F_{\text{N}}$ أكبر من القوة العمودية؛ فعلى سطح أفقي تلزم قوة أفقية أكبر من وزن الجسم لبدء تحريكه. مثال: على سطح أفقي والقوة المؤثرة أفقية $F_{\text{N}} = 20.0\ \text{N}$، فالقيمة القصوى $\mu_{\text{s}} F_{\text{N}} = (1.2)(20.0\ \text{N}) = 24\ \text{N}$، وهي أكبر من وزن الجسم. طريقة القياس: نعلّق الجسم بالميزان النابضي رأسيًا لقياس وزنه (يساوي القوة العمودية على السطح الأفقي)، ثم نسحبه أفقيًا بالميزان بقوة تزداد ببطء ونسجل القراءة لحظة بدء الانزلاق (القيمة القصوى للاحتكاك السكوني)، ونكرر ثلاث مرات ونأخذ المتوسط، ثم نقسم متوسط القراءة على الوزن فنحصل على $\mu_{\text{s}}$.', '["المعنى: القيمة القصوى للاحتكاك السكوني أكبر من القوة العمودية","الحساب: 24 N وهي أكبر من الوزن 20.0 N","قياس القوة العمودية بالوزن","قياس قوة بدء الانزلاق وتكرار المحاولات","حساب المعامل بالقسمة"]'::jsonb, '["$F_{\\text{N}} = 20.0\\ \\text{N}$ (سطح أفقي وقوة أفقية)","$\\mu_{\\text{s}} F_{\\text{N}} = 1.2 \\times 20.0 = 24\\ \\text{N}$","24 N > 20.0 N"]'::jsonb, '[{"element":"المعنى","marks":1},{"element":"الحساب والمقارنة بالوزن","marks":1},{"element":"قياس القوة العمودية","marks":1},{"element":"قياس قوة بدء الانزلاق","marks":1},{"element":"الحساب بالقسمة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع العناصر صحيحة"},{"level":"4 درجات","description":"أربعة عناصر صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المعامل لا يمكن أن يزيد على واحد.","القول إن قوة الاحتكاك لا يمكن أن تزيد على وزن الجسم.","قراءة الميزان أثناء الحركة بسرعة ثابتة لحساب المعامل السكوني."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-20T17:53:29.957Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C5-L2-O06') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C5-L2-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تدفع أريكة على أرضية أفقية بقوة أفقية مقدارها 120 N فلا تتحرك. ما مقدار قوة الاحتكاك السكوني المؤثرة فيها واتجاهها؟', null, null, '["120 N عكس اتجاه الدفع","120 N في اتجاه الدفع","صفر؛ لأن الأريكة ساكنة","أكبر من 120 N في عكس اتجاه الدفع"]'::jsonb, 'فهم', 'تطبيق التوازن', 'سهل', 'الكتاب ص 139، 141 — الشكل 5-8 والقيمة القصوى لقوة الاحتكاك السكوني'),
('mcq', 2, 'دفعت صندوقًا ساكنًا بقوة أفقية 50 N فلم يتحرك، ثم زدت قوة الدفع إلى 80 N فبقي ساكنًا. ماذا حدث لقوة الاحتكاك السكوني المؤثرة فيه؟', null, null, '["بقيت 50 N لأن الاحتكاك السكوني قيمة ثابتة","نقصت لأن الصندوق أوشك على الحركة","ازدادت من 50 N إلى 80 N","أصبحت صفرًا لأن قوة الدفع زادت"]'::jsonb, 'فهم', 'تتبع التغير', 'سهل', 'الكتاب ص 139 — «لأن قوة الاحتكاك السكوني تستجيب لقوى أخرى»'),
('mcq', 3, 'صندوق كتلته 20.0 kg ساكن على أرضية أفقية، ومعامل الاحتكاك السكوني بينهما 0.50. إذا دُفع الصندوق بقوة أفقية مقدارها 60 N، فما مقدار قوة الاحتكاك السكوني المؤثرة فيه؟', null, null, '["98 N","0 N","38 N","60 N"]'::jsonb, 'تطبيق', 'حساب قوة الاحتكاك السكوني', 'صعب', 'الكتاب ص 141 — قوة الاحتكاك السكوني؛ ص 145 المراجعة 26'),
('mcq', 4, 'يمثل المنحنى الآتي قوة الاحتكاك السكوني المؤثرة في صندوق ساكن على أرضية أفقية مقابل القوة الأفقية المؤثرة فيه، وقد زيدت القوة المؤثرة تدريجيًا من الصفر حتى بدأ الصندوق الحركة عند الخط المتقطع. إذا كانت القوة العمودية على الصندوق 80 N، فما مقدار قوة الاحتكاك السكوني عندما تكون القوة المؤثرة 25 N، وما معامل الاحتكاك السكوني؟', null, '[{"src":"qimg/phys1/c5l2-o07-graph-mcq.svg","alt":"منحنى بياني: المحور الأفقي «القوة الأفقية المؤثرة (N)» من 0 إلى 60 بتدريجات كل 10، والمحور الرأسي «قوة الاحتكاك السكوني (N)» من 0 إلى 50 بتدريجات كل 10. خط مستقيم يبدأ من نقطة الأصل ويصعد حتى النقطة المعلّمة (40، 40)، أي أن قوة الاحتكاك السكوني تساوي القوة المؤثرة. عند 40 N على المحور الأفقي خط رأسي متقطع مكتوب عنده «تبدأ الحركة»، ولا يُرسم المنحنى بعده."}]'::jsonb, '["25 N، و$\\mu_{\\text{s}} = 0.31$","25 N، و$\\mu_{\\text{s}} = 0.50$","40 N، و$\\mu_{\\text{s}} = 0.50$","40 N، و$\\mu_{\\text{s}} = 2.0$"]'::jsonb, 'تحليل', 'قراءة منحنى', 'صعب', 'الكتاب ص 139، 141 — الشكل 5-8 والقيمة القصوى لقوة الاحتكاك السكوني'),
('mcq', 5, 'يُدفع صندوق ساكن على أرضية أفقية بقوة أفقية تزداد تدريجيًا. متى يبدأ الصندوق الحركة؟', null, null, '["بمجرد أن تؤثر فيه أي قوة أفقية","عندما تساوي القوة المؤثرة وزن الصندوق","عندما تصبح القوة المؤثرة أكبر من $\\mu_{\\text{s}} F_{\\text{N}}$","عندما تصبح القوة المؤثرة أكبر من $\\mu_{\\text{k}} F_{\\text{N}}$"]'::jsonb, 'فهم', 'شرط بدء الحركة', 'متوسط', 'الكتاب ص 139، 141 — الشكل 5-8 والقيمة القصوى لقوة الاحتكاك السكوني'),
('mcq', 6, 'يمثل مخطط الجسم الحر الآتي صندوقًا ساكنًا على أرضية أفقية يُدفع أفقيًا، وسهما قوة الدفع وقوة الاحتكاك السكوني متساويان طولًا. ماذا يدل عليه تساوي طولي هذين السهمين؟', null, '[{"src":"qimg/phys1/c5l2-o07-fbd-rest.svg","alt":"مخطط الجسم الحر: نقطة في المركز تمثل الصندوق، تخرج منها أربعة أسهم زرقاء: سهم إلى أعلى مكتوب عنده F_N، وسهم إلى أسفل بالطول نفسه مكتوب عنده F_g، وسهم أفقي نحو اليمين مكتوب عنده F_الدفع، وسهم أفقي نحو اليسار بالطول نفسه مكتوب عنده f_s. في الزاوية اليسرى السفلى سهمان يبينان الاتجاهين الموجبين +x نحو اليمين و+y إلى أعلى."}]'::jsonb, '["القوة المحصلة صفر، فالاحتكاك يساوي الدفع ويعاكسه","الاحتكاك السكوني بلغ قيمته القصوى بالضرورة في هذه اللحظة","الصندوق يتحرك بتسارع ثابت في اتجاه الدفع","قوة الدفع تساوي القوة العمودية في المقدار"]'::jsonb, 'فهم', 'تفسير مخطط الجسم الحر', 'متوسط', 'الكتاب ص 139 — الاحتكاك السكوني (الشكل 5-8)'),
('mcq', 7, 'تُدفع طاولة وزنها 125 N على أرضية أفقية بقوة أفقية مقدارها 20 N فلا تتحرك، وعندما تُدفع بقوة أفقية مقدارها 25 N تتحرك. ما الاستنتاج الصحيح عن معامل الاحتكاك السكوني $\mu_{\text{s}}$ بين الطاولة والأرضية؟', null, null, '["$\\mu_{\\text{s}} = 0.16$ تمامًا","$\\mu_{\\text{s}} < 0.16$","$\\mu_{\\text{s}} \\ge 0.20$","$0.16 \\le \\mu_{\\text{s}} < 0.20$"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'صعب', 'الكتاب ص 145 — المراجعة 28 (التفكير الناقد)'),
('essay', 1, 'صف ما يحدث لقوة الاحتكاك السكوني المؤثرة في أريكة على أرضية أفقية بينما تزيد قوة دفعك الأفقية لها تدريجيًا من الصفر حتى تبدأ بالحركة، ثم بيّن نوع الاحتكاك بعد بدء الحركة.', null, null, null, 'فهم', 'وصف وتفسير', 'سهل', 'الكتاب ص 139، 141 — الشكل 5-8 والقيمة القصوى لقوة الاحتكاك السكوني'),
('essay', 2, 'صندوق كتلته 30.0 kg ساكن على أرضية أفقية، ومعامل الاحتكاك السكوني بينهما 0.50 ومعامل الاحتكاك الحركي 0.40. دُفع الصندوق أفقيًا بقوة: (a) 50 N، (b) 100 N، (c) 160 N. حدّد في كل حالة هل يتحرك الصندوق، ونوع قوة الاحتكاك ومقدارها، واحسب تسارعه في الحالة (c).', null, null, null, 'تطبيق', 'تحليل حالات حسابية', 'متوسط', 'الكتاب ص 141، 143 — قوة الاحتكاك السكوني، المثال 4'),
('essay', 3, 'يمثل المنحنى الآتي قوة الاحتكاك السكوني المؤثرة في جسم ساكن على سطح أفقي مقابل القوة الأفقية المؤثرة فيه، وقد زيدت القوة المؤثرة تدريجيًا حتى بدأ الجسم الحركة عند الخط المتقطع. القوة العمودية على الجسم 120 N. (a) لماذا يكون ميل الخط مساويًا 1؟ (b) ما القيمة القصوى لقوة الاحتكاك السكوني؟ احسب منها $\mu_{\text{s}}$. (c) إذا كان معامل الاحتكاك الحركي بين الجسم والسطح 0.40، فاحسب قوة الاحتكاك الحركي بعد بدء الحركة، وقارنها بالقيمة القصوى للاحتكاك السكوني، ثم استنتج القوة الأفقية اللازمة لإبقاء الجسم يتحرك بسرعة ثابتة.', null, '[{"src":"qimg/phys1/c5l2-o07-graph-essay.svg","alt":"منحنى بياني: المحور الأفقي «القوة الأفقية المؤثرة (N)» من 0 إلى 100 بتدريجات كل 20، والمحور الرأسي «قوة الاحتكاك السكوني (N)» من 0 إلى 70 بتدريجات كل 10. خط مستقيم يبدأ من نقطة الأصل ويصعد حتى النقطة المعلّمة (60، 60)، وعند 60 N على المحور الأفقي خط رأسي متقطع مكتوب عنده «تبدأ الحركة»، ولا يُرسم المنحنى بعده."}]'::jsonb, null, 'تحليل', 'تفسير منحنى بياني', 'متوسط', 'الكتاب ص 139، 141 — الشكل 5-8 والقيمة القصوى لقوة الاحتكاك السكوني')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
