insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الأريكة ساكنة فالقوة المحصلة عليها صفر، فقوة الاحتكاك السكوني مقدارها 120 N عكس اتجاه الدفع، أي تساوي قوة الدفع مقدارًا وتعاكسها اتجاهًا.', '["","الاحتكاك يعاكس القوة التي تحاول تحريك الجسم ولا يكون في اتجاهها.","سكون الأريكة مع وجود الدفع يعني وجود احتكاك سكوني يوازنه، لا انعدامه.","لو كان الاحتكاك أكبر من الدفع لكانت القوة المحصلة غير صفرية ولتحركت الأريكة عكس الدفع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-20T17:53:29.958Z"}'::jsonb),
('mcq', 2, 2, 'قوة الاحتكاك السكوني تستجيب للقوة المؤثرة؛ فما دام الصندوق ساكنًا تساوي القوة المؤثرة مقدارًا وتعاكسها اتجاهًا، فتزداد من 50 N إلى 80 N.', '["الاحتكاك السكوني ليس ثابتًا؛ ولو بقي 50 N لكانت القوة المحصلة 30 N ولتحرك الصندوق.","الاحتكاك السكوني يزداد مع الدفع حتى يبلغ قيمته القصوى، ولا ينقص.","","لو أصبح الاحتكاك صفرًا لتحرك الصندوق تحت تأثير قوة الدفع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-20T17:53:29.958Z"}'::jsonb),
('mcq', 3, 3, 'القيمة القصوى للاحتكاك السكوني: $\mu_{\text{s}} F_{\text{N}} = (0.50)(20.0\ \text{kg})(9.80\ \text{m/s}^2) = 98\ \text{N}$، وقوة الدفع 60 N أصغر منها، فيبقى الصندوق ساكنًا وتساوي قوة الاحتكاك السكوني قوة الدفع: 60 N.', '["98 N هي القيمة القصوى فقط، ولا يبلغها الاحتكاك السكوني إلا إذا بلغتها القوة المؤثرة.","الصندوق يُدفع ولا يتحرك، فلا بد من احتكاك سكوني يوازن الدفع.","طرح قوة الدفع من القيمة القصوى، وهذا الفرق لا يمثل أي قوة مؤثرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-20T17:53:29.959Z"}'::jsonb),
('mcq', 4, 1, 'ما دام الصندوق ساكنًا تساوي قوة الاحتكاك السكوني القوة المؤثرة (الخط يمر بنقاط إحداثياها متساويان)، فعند 25 N تكون 25 N. وتبدأ الحركة عندما تبلغ القوة المؤثرة 40 N، فهذه القيمة القصوى للاحتكاك السكوني: $\mu_{\text{s}} F_{\text{N}} = 40\ \text{N}$، ومنه $\mu_{\text{s}} = \frac{40\ \text{N}}{80\ \text{N}} = 0.50$.', '["قوة الاحتكاك صحيحة، لكنه حسب المعامل من 25 N، وهي ليست القيمة القصوى؛ فالمعامل يُحسب من القوة لحظة بدء الحركة.","","المعامل صحيح، لكن الاحتكاك السكوني ليس دائمًا عند قيمته القصوى؛ فهو عند 25 N يساوي 25 N فقط.","جعل الاحتكاك عند قيمته القصوى دائمًا، وقسم القوة العمودية على القيمة القصوى (مقلوب المعامل)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-20T17:53:29.959Z"}'::jsonb),
('mcq', 5, 2, 'تزداد قوة الاحتكاك السكوني مع القوة المؤثرة حتى قيمتها القصوى $\mu_{\text{s}} F_{\text{N}}$؛ وعندما تصبح القوة المؤثرة أكبر من هذه القيمة لا يستطيع الاحتكاك السكوني موازنتها فيبدأ الصندوق الحركة.', '["القوى الصغيرة يوازنها الاحتكاك السكوني فيبقى الصندوق ساكنًا.","شرط بدء الحركة يتعلق بالقيمة القصوى للاحتكاك $\\mu_{\\text{s}} F_{\\text{N}}$ لا بالوزن.","","$\\mu_{\\text{k}} F_{\\text{N}}$ أصغر من القيمة القصوى للاحتكاك السكوني، فقوة بينهما لا تحرك الصندوق الساكن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-20T17:53:29.959Z"}'::jsonb),
('mcq', 6, 0, 'الصندوق ساكن فالقوة المحصلة صفر؛ والاحتكاك السكوني يتكيف مع قوة الدفع فيساويها مقدارًا ويعاكسها اتجاهًا مهما كانت قيمتها ما دامت لم تتجاوز القيمة القصوى.', '["","التساوي يتحقق لأي قوة دفع أصغر من القيمة القصوى أو تساويها، فلا يدل حتمًا على بلوغ القيمة القصوى.","تساوي القوتين المتعاكستين يعني أن القوة المحصلة صفر، فلا تسارع.","قوة الدفع أفقية والقوة العمودية رأسية، والمخطط لا يقارن بينهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-20T17:53:29.960Z"}'::jsonb),
('mcq', 7, 3, 'الأرضية أفقية والقوة المؤثرة أفقية، فـ $F_{\text{N}} = 125\ \text{N}$. لم تتحرك الطاولة عند 20 N، فالقيمة القصوى $\mu_{\text{s}} F_{\text{N}} \ge 20\ \text{N}$، أي $\mu_{\text{s}} \ge \frac{20}{125} = 0.16$؛ وتحركت عند 25 N، فالقوة 25 N أكبر من القيمة القصوى، أي $\mu_{\text{s}} < \frac{25}{125} = 0.20$. إذن $0.16 \le \mu_{\text{s}} < 0.20$.', '["افترض أن 20 N هي القيمة القصوى، ولا دليل على ذلك؛ فقد يكون الاحتكاك السكوني عند 20 N دون قيمته القصوى.","لو كان أقل من 0.16 لكانت القيمة القصوى أقل من 20 N ولتحركت الطاولة عند 20 N.","لو كان 0.20 أو أكثر لكانت القيمة القصوى 25 N أو أكثر، ولما تحركت الطاولة عند 25 N.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-20T17:53:29.960Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عندما لا تدفع الأريكة تكون قوة الاحتكاك السكوني صفرًا. وعندما تدفعها بقوة صغيرة ولا تتحرك تنشأ قوة احتكاك سكوني تساوي قوة الدفع مقدارًا وتعاكسها اتجاهًا (القوة المحصلة صفر). وكلما زدت قوة الدفع وبقيت الأريكة ساكنة زادت قوة الاحتكاك السكوني بالمقدار نفسه، حتى تبلغ قيمتها القصوى $\mu_{\text{s}} F_{\text{N}}$. وعندما تصبح قوة الدفع أكبر من هذه القيمة القصوى تبدأ الأريكة الحركة، ويبدأ الاحتكاك الحركي في التأثير بدلًا من الاحتكاك السكوني.', '["الاحتكاك السكوني صفر عند انعدام الدفع","يساوي الدفع ويعاكسه ما دامت الأريكة ساكنة","يزداد بزيادة الدفع حتى قيمة قصوى $\\mu_{\\text{s}} F_{\\text{N}}$","تبدأ الحركة عند تجاوز القيمة القصوى ويحل الاحتكاك الحركي"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة الابتدائية","marks":1},{"element":"المساواة والتعاكس","marks":1},{"element":"الزيادة حتى القيمة القصوى","marks":1},{"element":"بدء الحركة والاحتكاك الحركي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف كامل صحيح"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الاحتكاك السكوني ثابت يساوي $\\mu_{\\text{s}} F_{\\text{N}}$ دائمًا.","القول إن الأريكة تبدأ الحركة عندما يساوي الدفع وزنها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-20T17:53:29.960Z"}'::jsonb),
('essay', 2, null::int, null, null, 'القوة العمودية: $F_{\text{N}} = (30.0)(9.80) = 294\ \text{N}$؛ القيمة القصوى للاحتكاك السكوني: $(0.50)(294) = 147\ \text{N}$. (a) 50 N < 147 N: يبقى ساكنًا، والاحتكاك سكوني مقداره 50 N عكس الدفع. (b) 100 N < 147 N: يبقى ساكنًا، والاحتكاك سكوني مقداره 100 N. (c) 160 N > 147 N: يتحرك، والاحتكاك حركي: $f_{\text{k}} = (0.40)(294) = 118\ \text{N}$ (نحو $1.2 \times 10^2\ \text{N}$)، والتسارع: $a = \frac{160 - 118}{30.0} = 1.4\ \text{m/s}^2$ في اتجاه الدفع.', '["حساب القوة العمودية والقيمة القصوى 147 N","الحالتان a وb: سكون واحتكاك سكوني يساوي الدفع","الحالة c: حركة واحتكاك حركي 118 N","التسارع 1.4 m/s²"]'::jsonb, '["$F_{\\text{N}} = 30.0 \\times 9.80 = 294\\ \\text{N}$","$\\mu_{\\text{s}} F_{\\text{N}} = 0.50 \\times 294 = 147\\ \\text{N}$","(a) و(b): $f_{\\text{s}}$ = 50 N و100 N","(c): $f_{\\text{k}} = 0.40 \\times 294 = 117.6\\ \\text{N}$","$a = (160 - 117.6) \\div 30.0 = 1.41 \\approx 1.4\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"القيمة القصوى","marks":1},{"element":"الحالتان a وb","marks":2},{"element":"الحالة c والاحتكاك الحركي","marks":1},{"element":"التسارع","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح"},{"level":"4 درجات","description":"خطأ في التسارع فقط"},{"level":"3 درجات","description":"خطأ في الحالة c"},{"level":"درجتان","description":"القيمة القصوى وحالة واحدة صحيحة"},{"level":"درجة واحدة","description":"القيمة القصوى فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الاحتكاك في الحالتين a وb مساويًا 147 N.","استعمال $\\mu_{\\text{s}}$ لحساب الاحتكاك بعد بدء الحركة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-20T17:53:29.960Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) ما دام الجسم ساكنًا فالقوة المحصلة عليه صفر، فتساوي قوة الاحتكاك السكوني القوة المؤثرة مقدارًا في كل لحظة (وتعاكسها اتجاهًا)؛ فكل زيادة في القوة المؤثرة تقابلها زيادة مساوية في الاحتكاك، فالميل 1. (b) تبدأ الحركة عندما تبلغ القوة المؤثرة 60 N، فالقيمة القصوى للاحتكاك السكوني 60 N، و$\mu_{\text{s}} = \frac{60\ \text{N}}{120\ \text{N}} = 0.50$. (c) $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}} = (0.40)(120\ \text{N}) = 48\ \text{N}$، وهي أصغر من القيمة القصوى للاحتكاك السكوني (60 N). ولإبقاء الجسم يتحرك بسرعة ثابتة يجب أن تكون القوة المحصلة صفرًا، فتلزم قوة أفقية مقدارها 48 N فقط، أي أقل من القوة اللازمة لبدء الحركة.', '["تفسير الميل 1: الاحتكاك السكوني يساوي القوة المؤثرة والجسم ساكن","القيمة القصوى 60 N","$\\mu_{\\text{s}} = 0.50$","$f_{\\text{k}} = 48\\ \\text{N}$ أصغر من 60 N","القوة اللازمة للسرعة الثابتة 48 N"]'::jsonb, '["$\\mu_{\\text{s}} = 60 \\div 120 = 0.50$","$f_{\\text{k}} = 0.40 \\times 120 = 48\\ \\text{N}$","48 N < 60 N، والقوة اللازمة للسرعة الثابتة = 48 N"]'::jsonb, '[{"element":"تفسير الميل","marks":1},{"element":"القيمة القصوى","marks":1},{"element":"معامل الاحتكاك السكوني","marks":1},{"element":"الاحتكاك الحركي والمقارنة","marks":1},{"element":"قوة السرعة الثابتة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"4 درجات","description":"أربعة عناصر صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار الجزء المائل حركة متسارعة.","حساب $\\mu_{\\text{s}}$ من قوة مؤثرة أقل من 60 N.","القول إن إبقاء الجسم متحركًا يحتاج إلى 60 N أيضًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-20T17:53:29.961Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
