('mcq', 2, 'صندوق كتلته 20.0 kg على أرضية أفقية، ومعامل الاحتكاك الحركي بينهما 0.30. إذا دُفع أفقيًا بقوة 90.0 N وهو ينزلق، فما مقدار تسارعه؟', null, null, '["1.6 m/s²","4.5 m/s²","7.4 m/s²","2.9 m/s²"]'::jsonb, 'تطبيق', 'القانون الثاني مع الاحتكاك', 'متوسط', 'الكتاب ص 143 — المثال 4 قوى احتكاك غير موازنة'),
('mcq', 3, 'تنزلق قطعة خشبية كتلتها 2.0 kg على سطح أفقي خشن دون أن تُدفع، فتتباطأ بتسارع مقداره 2.45 m/s². ما معامل الاحتكاك الحركي بين القطعة والسطح؟', null, null, '["4.0","0.13","0.50","0.25"]'::jsonb, 'تطبيق', 'حساب المعامل من التسارع', 'متوسط', 'الكتاب ص 144 — المسألة 19'),
('mcq', 4, 'ينزلق قرص على أرضية أفقية بسرعة ابتدائية 6.0 m/s، ومعامل الاحتكاك الحركي بينهما 0.40. ما المسافة التي يقطعها القرص حتى يتوقف؟', null, null, '["9.2 m","4.6 m","1.5 m","1.8 m"]'::jsonb, 'تطبيق', 'الاحتكاك ومعادلات الحركة', 'صعب', 'الكتاب ص 144 — المسألة 21'),
('mcq', 5, 'يمثل مخطط الجسم الحر الآتي صندوقًا كتلته 5.1 kg ينزلق على أرضية أفقية. ما مقدار تسارع الصندوق؟', null, '[{"src":"qimg/phys1/c5l2-o08-fbd-numbers.svg","alt":"مخطط الجسم الحر: نقطة في المركز تمثل الصندوق، تخرج منها أربعة أسهم زرقاء: سهم إلى أعلى مكتوب عنده F_N و50 N، وسهم إلى أسفل بالطول نفسه مكتوب عنده F_g و50 N، وسهم أفقي نحو اليمين مكتوب عنده F_الدفع و30 N، وسهم أفقي أقصر نحو اليسار مكتوب عنده f_k و20 N. في الزاوية اليسرى السفلى سهمان للاتجاهين الموجبين +x نحو اليمين و+y إلى أعلى."}]'::jsonb, '["5.9 m/s²","9.8 m/s²","0.20 m/s²","2.0 m/s²"]'::jsonb, 'تطبيق', 'قراءة مخطط الجسم الحر', 'سهل', 'الكتاب ص 143 — المثال 4 قوى احتكاك غير موازنة'),
('mcq', 6, 'صندوق كتلته 10.0 kg ساكن على أرضية أفقية، ومعامل الاحتكاك السكوني 0.50 والحركي 0.30. إذا دُفع أفقيًا بقوة 40 N، فماذا يحدث له؟', null, null, '["يبقى ساكنًا وتسارعه صفر","يتسارع بمقدار 1.1 m/s² في اتجاه الدفع","يتسارع بمقدار 4.0 m/s² في اتجاه الدفع","يتسارع بمقدار 0.90 m/s² عكس اتجاه الدفع"]'::jsonb, 'تحليل', 'تحقق من بدء الحركة', 'صعب', 'الكتاب ص 141 — قوة الاحتكاك السكوني؛ ص 144 ثالثًا'),
('mcq', 7, 'تؤثر قوة أفقية مقدارها 36.0 N في جسم كتلته 4.0 kg على سطح أفقي، فيتسارع بمقدار 5.0 m/s² في اتجاهها. ما معامل الاحتكاك الحركي بين الجسم والسطح؟', null, null, '["0.92","0.51","0.41","4.0"]'::jsonb, 'تطبيق', 'حساب المعامل', 'متوسط', 'الكتاب ص 157 — السؤال 64'),
('essay', 1, 'صندوق كتلته 30.0 kg على أرضية خشبية أفقية، ومعامل الاحتكاك الحركي بينهما 0.20. (a) ما قوة الدفع الأفقية اللازمة لتحريكه بسرعة منتظمة؟ (b) إذا دُفع وهو ينزلق بقوة أفقية 100 N، فما تسارعه؟', null, null, null, 'تطبيق', 'مسألة حسابية', 'سهل', 'الكتاب ص 142 — المثال 3 قوى احتكاك موازنة؛ الكتاب ص 143 — المثال 4 قوى احتكاك غير موازنة'),
('essay', 2, 'كان سائق يقود سيارته كتلتها 1500 kg بسرعة 20.0 m/s على طريق أفقي، فشاهد عائقًا على بعد 45.0 m فضغط على المكابح فانزلقت الإطارات. إذا كان معامل الاحتكاك الحركي بين الإطارات والطريق 0.50، فهل تتوقف السيارة قبل العائق؟ وضّح خطوات الحل، وبيّن هل تؤثر كتلة السيارة في النتيجة. (اعتبر اتجاه الحركة موجبًا.)', null, null, null, 'تحليل', 'مسألة متعددة الخطوات', 'صعب', 'الكتاب ص 144 — المسألة 22'),
('essay', 3, 'زلاجة كتلتها 40.0 kg على أرض أفقية مغطاة بالثلج، ومعامل الاحتكاك السكوني بينهما 0.25 والحركي 0.10. احسب: (a) وزن الزلاجة. (b) القوة اللازمة لكي تبدأ الحركة. (c) القوة اللازمة لتستمر في الحركة بسرعة ثابتة. (d) القوة الأفقية اللازمة بعد بدء الحركة لتتسارع بمقدار 2.0 m/s².', null, null, null, 'تطبيق', 'مسألة متعددة الأجزاء', 'متوسط', 'الكتاب ص 158 — السؤال 69')
