('mcq', 1, 2, 'السرعة منتظمة فالقوة المحصلة صفر: $F_{\text{الدفع}} = f_{\text{k}} = \mu_{\text{k}} mg = (0.20)(40.0\ \text{kg})(9.80\ \text{m/s}^2) = 78\ \text{N}$.', '["ضرب المعامل في الكتلة ونسي ضربها في g.","هذا وزن الصندوق (القوة العمودية)، ونسي ضربه في المعامل.","","قسم القوة العمودية على المعامل بدل ضربها فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-20T17:53:29.961Z"}'::jsonb),
('mcq', 2, 0, '$f_{\text{k}} = \mu_{\text{k}} mg = (0.30)(20.0)(9.80) = 58.8\ \text{N}$، و$a = \frac{F_{\text{الدفع}} - f_{\text{k}}}{m} = \frac{90.0\ \text{N} - 58.8\ \text{N}}{20.0\ \text{kg}} = 1.6\ \text{m/s}^2$ في اتجاه الدفع.', '["","أهمل قوة الاحتكاك وقسم قوة الدفع على الكتلة.","جمع قوة الاحتكاك مع قوة الدفع بدل طرحها، مع أنها تعاكسه.","حسب $\\mu_{\\text{k}} g$ (تسارع الاحتكاك وحده) ونسي قوة الدفع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-20T17:53:29.962Z"}'::jsonb),
('mcq', 3, 3, 'القوة المحصلة هي الاحتكاك: $\mu_{\text{k}} mg = ma$، ومنه $\mu_{\text{k}} = \frac{a}{g} = \frac{2.45\ \text{m/s}^2}{9.80\ \text{m/s}^2} = 0.25$.', '["قسم g على مقدار التسارع (مقلوب المعامل).","عدّ مقدار التسارع قوة الاحتكاك وقسمه على الوزن (2.0 × 9.80).","حسب قوة الاحتكاك ma = 4.9 N وقسمها على g بدل الوزن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-20T17:53:29.962Z"}'::jsonb),
('mcq', 4, 1, 'باعتبار اتجاه الحركة موجبًا: $a = -\mu_{\text{k}} g = -(0.40)(9.80) = -3.92\ \text{m/s}^2$. ومن $v_f^2 = v_i^2 + 2a\Delta d$ مع $v_f = 0$: $\Delta d = \frac{-v_i^2}{2a} = \frac{-(6.0)^2}{2(-3.92)} = 4.6\ \text{m}$.', '["نسي العدد 2 في المقام فحسب $\\frac{v_i^2}{a}$.","","قسم السرعة على التسارع ($v_i/a$) فحسب زمن التوقف تقريبًا لا المسافة.","أهمل معامل الاحتكاك وجعل التسارع g."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-20T17:53:29.962Z"}'::jsonb),
('mcq', 5, 3, 'القوتان الرأسيتان متوازنتان، والقوة المحصلة أفقية: $F_{\text{المحصلة}} = 30\ \text{N} - 20\ \text{N} = 10\ \text{N}$ في الاتجاه الموجب، و$a = \frac{10\ \text{N}}{5.1\ \text{kg}} = 2.0\ \text{m/s}^2$.', '["أهمل قوة الاحتكاك فقسم قوة الدفع وحدها على الكتلة.","قسم القوة العمودية على الكتلة، والقوى الرأسية متوازنة لا تسبب تسارعًا.","قسم القوة المحصلة على الوزن (50 N) بدل الكتلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-20T17:53:29.962Z"}'::jsonb),
('mcq', 6, 0, 'القيمة القصوى للاحتكاك السكوني: $\mu_{\text{s}} mg = (0.50)(10.0)(9.80) = 49\ \text{N}$، وقوة الدفع 40 N أصغر منها؛ فيوازنها احتكاك سكوني مقداره 40 N ويبقى الصندوق ساكنًا.', '["","استعمل الاحتكاك الحركي (29.4 N) مع أن الصندوق ساكن لم يبدأ الحركة بعد.","أهمل الاحتكاك تمامًا.","طرح القيمة القصوى من الدفع وكأن الاحتكاك السكوني يساوي قيمته القصوى دائمًا، فحصل على حركة عكسية مستحيلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-20T17:53:29.963Z"}'::jsonb),
('mcq', 7, 2, '$F_{\text{المحصلة}} = ma = (4.0)(5.0) = 20\ \text{N}$، و$f_{\text{k}} = 36.0 - 20 = 16\ \text{N}$، و$\mu_{\text{k}} = \frac{f_{\text{k}}}{mg} = \frac{16\ \text{N}}{(4.0)(9.80)\ \text{N}} = 0.41$.', '["قسم القوة المؤثرة كلها على القوة العمودية، وكأنها قوة الاحتكاك.","قسم القوة المحصلة (ma = 20 N) على القوة العمودية بدل قوة الاحتكاك.","","قسم قوة الاحتكاك على الكتلة بدل القوة العمودية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-20T17:53:29.963Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $F_{\text{N}} = mg = (30.0)(9.80) = 294\ \text{N}$، و$f_{\text{k}} = (0.20)(294) = 58.8\ \text{N}$؛ وعند السرعة المنتظمة $F_{\text{الدفع}} = f_{\text{k}} \approx 59\ \text{N}$. (b) $a = \frac{F_{\text{الدفع}} - f_{\text{k}}}{m} = \frac{100 - 58.8}{30.0} = 1.4\ \text{m/s}^2$ في اتجاه الدفع.', '["القوة العمودية 294 N","قوة الاحتكاك الحركي 59 N وتساوي قوة الدفع عند السرعة المنتظمة","تطبيق القانون الثاني بطرح الاحتكاك","التسارع 1.4 m/s²"]'::jsonb, '["$F_{\\text{N}} = 30.0 \\times 9.80 = 294\\ \\text{N}$","$f_{\\text{k}} = 0.20 \\times 294 = 58.8\\ \\text{N}$","(a) $F_{\\text{الدفع}} = 59\\ \\text{N}$","(b) $a = (100 - 58.8) \\div 30.0 = 1.37 \\approx 1.4\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"القوة العمودية","marks":1},{"element":"الجزء a","marks":1},{"element":"معادلة الجزء b","marks":1},{"element":"التسارع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل صحيح"},{"level":"3 درجات","description":"خطأ حسابي بسيط"},{"level":"درجتان","description":"الجزء a فقط صحيح"},{"level":"درجة واحدة","description":"القوة العمودية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال الاحتكاك في الجزء b.","جعل قوة الدفع عند السرعة المنتظمة أكبر من الاحتكاك."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-20T17:53:29.964Z"}'::jsonb),
('essay', 2, null::int, null, null, 'القوة المحصلة هي الاحتكاك الحركي: $ma = -\mu_{\text{k}} mg$، فتختصر الكتلة: $a = -\mu_{\text{k}} g = -(0.50)(9.80) = -4.9\ \text{m/s}^2$. مسافة التوقف: $\Delta d = \frac{v_f^2 - v_i^2}{2a} = \frac{0 - (20.0)^2}{2(-4.9)} = 41\ \text{m}$. ولأن 41 m < 45.0 m تتوقف السيارة قبل العائق بنحو 4 m. ولا تؤثر الكتلة في النتيجة لأنها تختصر من طرفي المعادلة.', '["التسارع $-\\mu_{\\text{k}} g = -4.9\\ \\text{m/s}^2$","استعمال معادلة الحركة لإيجاد مسافة التوقف","مسافة التوقف 41 m","المقارنة والاستنتاج: تتوقف قبل العائق","الكتلة تختصر ولا تؤثر"]'::jsonb, '["$a = -\\mu_{\\text{k}} g = -0.50 \\times 9.80 = -4.9\\ \\text{m/s}^2$","$\\Delta d = \\frac{0 - 20.0^2}{2(-4.9)} = 40.8 \\approx 41\\ \\text{m}$","41 m < 45.0 m ← تتوقف قبل العائق"]'::jsonb, '[{"element":"التسارع","marks":1},{"element":"معادلة الحركة","marks":1},{"element":"مسافة التوقف","marks":1},{"element":"الاستنتاج","marks":1},{"element":"أثر الكتلة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح"},{"level":"4 درجات","description":"خطأ في عنصر واحد"},{"level":"3 درجات","description":"التسارع والمسافة صحيحان دون استنتاج كامل"},{"level":"درجتان","description":"التسارع صحيح فقط مع معادلة صحيحة"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان العدد 2 في المعادلة فتصبح المسافة 82 m.","استعمال قوة الاحتكاك بدل التسارع في معادلة الحركة.","إهمال الإشارة السالبة للتسارع فتظهر مسافة سالبة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.964Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $F_g = mg = (40.0)(9.80) = 392\ \text{N}$. (b) يجب أن تتجاوز القوة القيمة القصوى للاحتكاك السكوني: $\mu_{\text{s}} F_{\text{N}} = (0.25)(392) = 98\ \text{N}$. (c) $f_{\text{k}} = (0.10)(392) = 39\ \text{N}$ (39.2 N)، فالقوة اللازمة 39 N. (d) القوة المحصلة اللازمة $ma = (40.0)(2.0) = 80\ \text{N}$، والقوة الأفقية = $80 + 39.2 = 119\ \text{N} \approx 1.2 \times 10^2\ \text{N}$.', '["الوزن 392 N","قوة بدء الحركة 98 N","قوة الحركة بسرعة ثابتة 39 N","القوة المحصلة 80 N","القوة الأفقية 1.2 × 10² N"]'::jsonb, '["$F_g = 40.0 \\times 9.80 = 392\\ \\text{N}$","$\\mu_{\\text{s}} F_{\\text{N}} = 0.25 \\times 392 = 98\\ \\text{N}$","$f_{\\text{k}} = 0.10 \\times 392 = 39.2\\ \\text{N}$","$F_{\\text{المحصلة}} = 40.0 \\times 2.0 = 80\\ \\text{N}$","$F = 80 + 39.2 = 119.2 \\approx 1.2 \\times 10^2\\ \\text{N}$"]'::jsonb, '[{"element":"الوزن","marks":1},{"element":"قوة بدء الحركة","marks":1},{"element":"قوة السرعة الثابتة","marks":1},{"element":"القوة اللازمة للتسارع","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"4 درجات","description":"خطأ في الجزء d فقط"},{"level":"3 درجات","description":"ثلاثة أجزاء صحيحة"},{"level":"درجتان","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"الوزن فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال $\\mu_{\\text{s}}$ في الجزء c.","جعل القوة الأفقية في الجزء d تساوي القوة المحصلة 80 N ونسيان الاحتكاك."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-20T17:53:29.964Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
