from (values
('mcq', 1, 'علامَ تعتمد قوة الاحتكاك بين سطحين بشكل أساسي؟', null, null, '["مساحة سطحي التلامس وسرعة حركة الجسم عليه","نوع مادتي السطحين والقوة العمودية بينهما","سرعة الجسم والمسافة التي يقطعها على السطح","كتلة الجسم فقط مهما كانت القوى الأخرى"]'::jsonb, 'تذكر', 'تحديد العوامل', 'سهل', 'الكتاب ص 140 — نموذج لقوى الاحتكاك'),
('mcq', 2, 'تُسحب القطعة نفسها بسرعة منتظمة على السطح نفسه مرة وهي على وجهها الكبير ومرة على وجهها الصغير، كما في الشكل الآتي. كيف تقارن قوة الاحتكاك الحركي في الحالتين؟', null, '[{"src":"qimg/phys1/c5l2-o09-brick-faces.svg","alt":"رسم لسطح أفقي عليه حالتان للقطعة نفسها: الحالة (1) القطعة موضوعة على وجهها الكبير (مستطيل طويل منخفض)، والحالة (2) القطعة موضوعة على وجهها الصغير (مستطيل ضيق مرتفع). في كل حالة خيط أفقي يصل القطعة بميزان نابضي صغير. وفي أعلى الرسم عبارة: القطعة نفسها تُسحب بميزان نابضي أفقيًا بسرعة منتظمة."}]'::jsonb, '["متساويتان؛ لأن نوع السطحين والقوة العمودية لم يتغيرا","في الحالة (1) أكبر؛ لأن مساحة التلامس أكبر","في الحالة (2) أكبر؛ لأن القطعة تضغط على مساحة أصغر","في الحالة (1) أصغر؛ لأن الوزن يتوزع على مساحة أكبر"]'::jsonb, 'فهم', 'مقارنة حالتين', 'سهل', 'الكتاب ص 140 — نموذج لقوى الاحتكاك'),
('mcq', 3, 'سُحبت قطعة خشبية على سطح أفقي بسرعة منتظمة مقدارها 0.5 m/s، ثم سُحبت على السطح نفسه بسرعة منتظمة مقدارها 1.0 m/s. كيف تتغير قوة الاحتكاك الحركي؟', null, null, '["تتضاعف؛ لأن السرعة تضاعفت فتتضاعف معها","تقل إلى النصف؛ لأن زمن التلامس يقل","تزداد قليلًا؛ لأن النتوءات تتصادم أكثر عند السرعة الأكبر","لا تتغير؛ لأن الاحتكاك لا يعتمد على السرعة"]'::jsonb, 'فهم', 'أثر عامل', 'متوسط', 'الكتاب ص 140 — نموذج لقوى الاحتكاك'),
('mcq', 4, 'تُسحب قطعة خشبية بسرعة منتظمة على سطح طاولة، ثم توضع فوقها قطعة مماثلة لها تمامًا وتُسحبان معًا على السطح نفسه. ماذا يحدث لقوة الاحتكاك الحركي على السطح؟', null, null, '["لا تتغير؛ لأن مادة السطحين لم تتغير","تقل إلى النصف؛ لأن الوزن يتوزع على قطعتين","تتضاعف؛ لأن القوة العمودية تتضاعف","تصبح أربعة أمثالها؛ لأن الكتلة تتضاعف"]'::jsonb, 'تطبيق', 'أثر القوة العمودية', 'متوسط', 'الكتاب ص 140 — نموذج لقوى الاحتكاك'),
('mcq', 5, 'لماذا تكون قوة الاحتكاك السكوني بين الحذاء والرصيف الإسمنتي أكبر منها بين الحذاء نفسه وأرضية من السيراميك، والشخص نفسه يقف عليهما؟', null, null, '["لأن وزن الشخص يزداد على الرصيف الإسمنتي","لاختلاف مادة السطح الملامس للحذاء","لأن مساحة التلامس مع الإسمنت أكبر","لأن الشخص يتحرك على الرصيف أسرع"]'::jsonb, 'فهم', 'أثر نوع المادة', 'سهل', 'الكتاب ص 140 — نموذج لقوى الاحتكاك (الحذاء والرصيف الإسمنتي والسيراميك)'),
('mcq', 6, 'يرى أحمد أن استبدال إطارات سيارته بإطارات أعرض يزيد قوة الاحتكاك بينها وبين الطريق؛ لأن مساحة التلامس تزداد. ما تقويمك لرأيه وفق نموذج الاحتكاك المدروس؟', null, null, '["صحيح؛ لأن الاحتكاك يتناسب طرديًا مع مساحة التلامس بين السطحين","صحيح؛ لأن الإطار الأعرض أثقل فيزداد معامل الاحتكاك","خطأ؛ لأن الإطار الأعرض يوزع الوزن فيقلل القوة العمودية فيقل الاحتكاك","خطأ؛ فالاحتكاك لا يعتمد على المساحة بل على نوع السطحين والقوة العمودية"]'::jsonb, 'تقويم', 'تقويم رأي', 'صعب', 'الكتاب ص 156 — السؤال 50'),
('mcq', 7, 'يُدفع صندوق وزنه 100 N أفقيًا فينزلق على أرضية أفقية، وفي الوقت نفسه تضغط عليه يد رأسيًا إلى أسفل بقوة $\boldsymbol{F}$ مقدارها 20 N، كما في مخطط الجسم الحر الآتي. إذا كان معامل الاحتكاك الحركي 0.30، فما مقدار قوة الاحتكاك الحركي؟', null, '[{"src":"qimg/phys1/c5l2-o09-press-down.svg","alt":"مخطط الجسم الحر: نقطة تمثل الصندوق تخرج منها أسهم زرقاء: سهم طويل إلى أعلى مكتوب عنده F_N دون قيمة، وسهم إلى أسفل مكتوب عنده F_g و100 N، وسهم قصير إلى أسفل بجانبه مكتوب عنده F و20 N (قوة ضغط اليد)، وسهم أفقي نحو اليمين مكتوب عنده F_الدفع، وسهم أفقي نحو اليسار مكتوب عنده f_k. في الزاوية اليسرى السفلى سهمان للاتجاهين الموجبين +x و+y."}]'::jsonb, '["36 N","30 N","24 N","6.0 N"]'::jsonb, 'تطبيق', 'القوة العمودية لا تساوي الوزن', 'صعب', 'الكتاب ص 144 — ثانيًا: القوة العمودية قد لا تساوي الوزن'),
('essay', 1, 'هل يزداد احتكاك إطار السيارة بالطريق إذا ازداد عرضه أم يقل؟ وضّح إجابتك مستعملًا معادلتي الاحتكاك، ثم اذكر عاملين يمكن أن يزيدا الاحتكاك فعلًا.', null, null, null, 'فهم', 'تفسير بالمعادلات', 'متوسط', 'الكتاب ص 156 — السؤال 50'),
('essay', 2, 'صمّم تجربة باستعمال قطعة خشبية على شكل متوازي مستطيلات وميزان نابضي وكتل إضافية، لاختبار: (a) هل تعتمد قوة الاحتكاك الحركي على مساحة سطح التلامس؟ (b) هل تعتمد على القوة العمودية؟ حدد في كل جزء المتغير المستقل والمتغير الذي تثبّته، والنتيجة المتوقعة.', null, null, null, 'إبداع', 'تصميم تجربة', 'صعب', 'الكتاب ص 140 — نموذج لقوى الاحتكاك؛ ص 152 مختبر الفيزياء'),
('essay', 3, 'قال طالب: «قوة الاحتكاك على الجسم تساوي دائمًا معامل الاحتكاك مضروبًا في وزنه، وتزداد كلما زادت سرعته». قوّم هذه العبارة بجزأيها، مع مثال يوضح كل تصحيح.', null, null, null, 'تقويم', 'تقويم عبارة', 'متوسط', 'الكتاب ص 140 — نموذج لقوى الاحتكاك؛ ص 144 ثانيًا')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C5-L2-O09') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'تعتمد قوة الاحتكاك أساسًا على نوع مادتي السطحين (عبر معامل الاحتكاك) والقوة العمودية بينهما، ولا تعتمد على مساحة التلامس أو السرعة.', '["أثبتت التجارب أن الاحتكاك لا يعتمد على مساحة التلامس ولا على سرعة الحركة.","","السرعة والمسافة لا تحددان قوة الاحتكاك؛ فالمهم القوة العمودية ونوع السطحين.","الاحتكاك يعتمد على القوة العمودية، وهي لا تساوي الوزن دائمًا، كما يعتمد على نوع السطحين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.965Z"}'::jsonb),
('mcq', 2, 0, 'قوة الاحتكاك $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}}$ لا تحتوي على المساحة؛ والمادتان والقوة العمودية (وزن القطعة نفسها) لم تتغير، فقوتا الاحتكاك متساويتان.', '["","أثبتت التجارب أن الاحتكاك لا يعتمد على مساحة سطحي التلامس.","تصغير المساحة لا يغير القوة العمودية الكلية ولا نوع السطحين، فلا يتغير الاحتكاك.","توزع الوزن على مساحة أكبر لا يغير القوة العمودية الكلية، فلا يقل الاحتكاك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-20T17:53:29.965Z"}'::jsonb),
('mcq', 3, 3, 'لا تتغير قوة الاحتكاك؛ لأن الاحتكاك لا يعتمد على السرعة كما أثبتت التجارب؛ فما دام السطحان والقوة العمودية كما هي، تبقى $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}}$ ثابتة.', '["الاحتكاك لا يتناسب مع السرعة؛ والعلاقة $f_{\\text{k}} = \\mu_{\\text{k}} F_{\\text{N}}$ لا تتضمن السرعة.","زمن التلامس لا يدخل في تحديد قوة الاحتكاك وفق النموذج المدروس.","النموذج المدروس يبين أن الاحتكاك الحركي لا يتغير بتغير السرعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-20T17:53:29.965Z"}'::jsonb),
('mcq', 4, 2, 'وضع القطعة المماثلة يضاعف القوة العمودية، ومادتا السطحين المتلامسين لم تتغيرا؛ ولأن $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}}$ تتضاعف قوة الاحتكاك.', '["مادة السطحين لم تتغير فعلًا، لكن القوة العمودية تضاعفت فتتضاعف قوة الاحتكاك.","القوة العمودية على السطح تتضاعف ولا تتوزع؛ وزيادتها تزيد الاحتكاك لا تنقصه.","","العلاقة بين الاحتكاك والقوة العمودية خطية، فمضاعفة القوة العمودية تضاعفه مرة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-20T17:53:29.965Z"}'::jsonb),
('mcq', 5, 1, 'السبب اختلاف مادة السطح الملامس للحذاء؛ فقوة الاحتكاك تعتمد على المواد التي تتكون منها السطوح، ومعامل الاحتكاك بين الحذاء والإسمنت أكبر منه بين الحذاء والسيراميك، والقوة العمودية واحدة.', '["الوزن لا يتغير بتغير السطح، فالقوة العمودية واحدة في الحالتين.","","الاحتكاك لا يعتمد على مساحة سطحي التلامس.","الاحتكاك لا يعتمد على السرعة، والسؤال عن الاحتكاك السكوني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.966Z"}'::jsonb),
('mcq', 6, 3, 'وفق العلاقتين $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}}$ و$f_{\text{s}} \le \mu_{\text{s}} F_{\text{N}}$ لا تدخل المساحة في قوة الاحتكاك؛ فإذا بقيت مادتا السطحين والقوة العمودية كما هي فلا يتغير الاحتكاك بتغير عرض الإطار.', '["التجارب أثبتت أن الاحتكاك لا يعتمد على مساحة التلامس.","معامل الاحتكاك يعتمد على نوع السطحين لا على ثقل الجسم.","عرض الإطار لا يقلل القوة العمودية؛ فالقوة العمودية الكلية تعتمد على وزن السيارة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-20T17:53:29.966Z"}'::jsonb),
('mcq', 7, 0, 'لا تسارع رأسيًا، فالقوة العمودية توازن الوزن وقوة ضغط اليد $\boldsymbol{F}$ معًا: $F_{\text{N}} = 100\ \text{N} + 20\ \text{N} = 120\ \text{N}$، ومنه $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}} = (0.30)(120\ \text{N}) = 36\ \text{N}$.', '["","افترض أن القوة العمودية تساوي الوزن دائمًا وأهمل قوة اليد.","طرح قوة اليد من الوزن مع أنها تؤثر إلى أسفل مثله.","ضرب المعامل في قوة اليد وحدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-20T17:53:29.966Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لا يزداد ولا يقل (إذا بقيت مادتا السطحين ووزن السيارة كما هي). فمعادلتا الاحتكاك $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}}$ و$f_{\text{s}} \le \mu_{\text{s}} F_{\text{N}}$ تعتمدان فقط على معامل الاحتكاك (نوع مادتي الإطار والطريق) والقوة العمودية، ولا تحتويان على مساحة التلامس. يزيد الاحتكاك فعلًا: زيادة القوة العمودية (زيادة الحمولة مثلًا)، أو تغيير مادة الإطار أو حالة الطريق إلى ما معامله أكبر (طريق جاف بدل رطب مثلًا).', '["الحكم: لا يتغير الاحتكاك بتغير العرض","كتابة المعادلتين","التعليل بغياب المساحة عن المعادلتين","ذكر عاملين صحيحين يزيدان الاحتكاك"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"المعادلتان","marks":1},{"element":"التعليل","marks":1},{"element":"العاملان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الإطار الأعرض يزيد الاحتكاك لزيادة المساحة.","ذكر السرعة عاملًا يزيد الاحتكاك."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-20T17:53:29.966Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) نسحب القطعة بالميزان النابضي أفقيًا بسرعة منتظمة على السطح نفسه مرة على وجهها الكبير ومرة على وجهها الصغير، ونسجل قراءة الميزان (تساوي قوة الاحتكاك الحركي) ونكرر المحاولات. المتغير المستقل: مساحة التلامس؛ نثبت: القوة العمودية (القطعة نفسها) ونوع السطح وسرعة السحب. النتيجة المتوقعة: القراءات متساوية تقريبًا، فالاحتكاك لا يعتمد على المساحة. (b) نسحب القطعة على الوجه نفسه بسرعة منتظمة بعد وضع كتل إضافية فوقها في كل مرة، ونقيس الوزن الكلي بالميزان (القوة العمودية) وقوة الاحتكاك. المتغير المستقل: القوة العمودية؛ نثبت: الوجه ونوع السطح. النتيجة المتوقعة: تزداد قوة الاحتكاك بزيادة القوة العمودية بتناسب طردي، ويكون منحنى (قوة الاحتكاك الحركي – القوة العمودية) خطًا مستقيمًا ميله $\mu_{\text{k}}$.', '["خطوات الجزء a مع السحب بسرعة منتظمة","تحديد المتغيرات في الجزء a والنتيجة المتوقعة","خطوات الجزء b بإضافة الكتل","تحديد المتغيرات في الجزء b والنتيجة المتوقعة (تناسب طردي)","تكرار المحاولات أو الرسم البياني"]'::jsonb, '[]'::jsonb, '[{"element":"خطوات a","marks":1},{"element":"متغيرات a ونتيجتها","marks":1},{"element":"خطوات b","marks":1},{"element":"متغيرات b ونتيجتها","marks":1},{"element":"التكرار أو التمثيل البياني","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصميم كامل صحيح"},{"level":"4 درجات","description":"نقص عنصر واحد"},{"level":"3 درجات","description":"جزء كامل وجزء ناقص"},{"level":"درجتان","description":"جزء واحد صحيح"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تثبيت القوة العمودية عند اختبار المساحة.","قراءة الميزان والقطعة تتسارع.","توقع زيادة الاحتكاك بزيادة المساحة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.967Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الجزء الأول غير دقيق: الاحتكاك يعتمد على القوة العمودية لا على الوزن، والقوة العمودية قد لا تساوي الوزن إذا أثرت قوة أخرى في اتجاهها أو عكسه، أو إذا كان الجسم على سطح مائل؛ مثال: صندوق وزنه 100 N تضغط عليه يد إلى أسفل بقوة 20 N تكون قوته العمودية 120 N لا 100 N. كما أن الاحتكاك السكوني ليس دائمًا $\mu_{\text{s}} F_{\text{N}}$ بل أقل منه أو يساويه. الجزء الثاني خطأ: الاحتكاك لا يعتمد على السرعة؛ مثال: سحب قطعة بسرعة منتظمة 0.5 m/s ثم 1.0 m/s يعطي قراءة الميزان نفسها.', '["الاحتكاك يعتمد على القوة العمودية لا الوزن","مثال على قوة عمودية لا تساوي الوزن","الاحتكاك لا يعتمد على السرعة","مثال يوضح عدم اعتماده على السرعة"]'::jsonb, '[]'::jsonb, '[{"element":"تصحيح الجزء الأول","marks":1},{"element":"مثاله","marks":1},{"element":"تصحيح الجزء الثاني","marks":1},{"element":"مثاله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم كامل بمثالين"},{"level":"3 درجات","description":"تقويم صحيح بمثال واحد"},{"level":"درجتان","description":"تقويم صحيح دون أمثلة"},{"level":"درجة واحدة","description":"تصحيح جزء واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول الجزء الأول لأن القوة العمودية تساوي الوزن «دائمًا».","قبول اعتماد الاحتكاك على السرعة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-20T17:53:29.967Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C5-L2-O09') and x.type = v.type and x.number = v.number
