insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C5-L2-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الفرق بين شرطي نشوء الاحتكاك السكوني والاحتكاك الحركي؟', null, null, '["السكوني ينشأ عند انزلاق السطحين، والحركي دون انزلاقهما","السكوني ينشأ على الأسطح الأفقية، والحركي على الأسطح المائلة","السكوني ينشأ دون انزلاق السطحين، والحركي عند انزلاقهما","السكوني قوة مجال تؤثر عن بعد، والحركي قوة تلامس بين سطحين"]'::jsonb, 'فهم', 'مقارنة شرط النشوء', 'سهل', 'الكتاب ص 145 — المراجعة 23 (قارن بين الاحتكاك السكوني والاحتكاك الحركي)'),
('mcq', 2, 'يبين الجدول الآتي معاملات الاحتكاك لبعض السطوح. ماذا تستنتج من مقارنة قيم $\mu_{\text{s}}$ بقيم $\mu_{\text{k}}$؟', '{"headers":["السطح","$\\mu_{\\text{s}}$","$\\mu_{\\text{k}}$"],"rows":[["مطاط فوق خرسانة جافة","0.80","0.65"],["مطاط فوق خرسانة رطبة","0.60","0.40"],["خشب فوق خشب","0.50","0.20"],["فولاذ فوق فولاذ جاف","0.78","0.58"],["فولاذ فوق فولاذ (مع الزيت)","0.15","0.06"]]}'::jsonb, null, '["$\\mu_{\\text{s}} > \\mu_{\\text{k}}$ لكل سطح، فبدء الحركة يتطلب قوة أكبر","$\\mu_{\\text{k}} > \\mu_{\\text{s}}$ لكل سطح، فإبقاء الحركة يتطلب قوة أكبر من بدئها","المعاملان متساويان تقريبًا، فلا فرق بين قوة بدء الحركة وقوة استمرارها","لا علاقة ثابتة بينهما، فهي تختلف من سطح إلى آخر"]'::jsonb, 'تحليل', 'استنتاج من جدول', 'متوسط', 'الكتاب ص 141 — الجدول 5-1'),
('mcq', 3, 'صندوق خشبي كتلته 50.0 kg على أرضية خشبية أفقية، حيث $\mu_{\text{s}} = 0.50$ و$\mu_{\text{k}} = 0.20$. ما مقدار القوة الأفقية اللازمة لبدء حركته، ثم اللازمة لاستمرار حركته بسرعة ثابتة، على الترتيب؟', null, null, '["98 N ثم 245 N","245 N ثم 245 N","25 N ثم 10 N","245 N ثم 98 N"]'::jsonb, 'تطبيق', 'مقارنة حسابية', 'سهل', 'الكتاب ص 140–141 — العلاقتان؛ ص 158 السؤال 69'),
('mcq', 4, 'يبين الجدول الآتي ثلاث محاولات لدفع أريكة على أرضية أفقية بقوة أفقية تزداد من محاولة إلى أخرى، والقوة العمودية واحدة. أيّ وصف لقوة الاحتكاك المؤثرة في الأريكة في المحاولات الثلاث صحيح؟', '{"headers":["المحاولة","قوة الدفع الأفقية (N)","حالة الأريكة"],"rows":[["(1)","100","ساكنة"],["(2)","200","ساكنة"],["(3)","300","تنزلق على الأرضية"]]}'::jsonb, null, '["(1) و(2): سكوني يساوي $\\mu_{\\text{s}} F_{\\text{N}}$ في كلتيهما، و(3): حركي يساوي 300 N","(1) و(2): سكوني يساوي الدفع (100 N ثم 200 N)، و(3): حركي يساوي $\\mu_{\\text{k}} F_{\\text{N}}$","(1): سكوني يساوي 100 N، و(2) و(3): حركي لأن قوة الدفع كبيرة فيهما","(1) و(2) و(3): حركي في الجميع؛ لأن الأريكة تُدفع في المحاولات كلها"]'::jsonb, 'تحليل', 'تفسير بيانات', 'متوسط', 'الكتاب ص 139، 141 — الشكل 5-8 وعلاقتا الاحتكاك السكوني والحركي'),
('mcq', 5, 'ما وجه الشبه بين الاحتكاك السكوني والاحتكاك الحركي؟', null, null, '["كلاهما يساوي قيمة ثابتة لا تتغير بتغير القوة المؤثرة","كلاهما يؤثر في اتجاه الحركة أو الميل إليها","كلاهما يتطلب انزلاق السطحين أحدهما على الآخر لينشأ","كلاهما قوة تلامس ترتبط قيمتها (القصوى) بالقوة العمودية"]'::jsonb, 'تحليل', 'إيجاد أوجه الشبه', 'متوسط', 'الكتاب ص 141 — «ترتبط قوة الاحتكاك السكوني القصوى بالقوة العمودية بطريقة مشابهة لتلك التي ترتبط بها قوة الاحتكاك الحركي»'),
('mcq', 6, 'يتوقف السائق بسيارته في مسافة أقصر عندما يضغط على المكابح بحيث تبقى العجلات تدور دون أن تنزلق على الطريق، مقارنة بانزلاقها. ما التفسير؟', null, null, '["الاحتكاك الحركي أكبر من الاحتكاك السكوني","القوة العمودية على الإطارات تزداد عندما لا تنزلق العجلات","يبقى الاحتكاك سكونيًا، وقيمته القصوى أكبر من الحركي","الاحتكاك ينعدم عندما لا تنزلق العجلات"]'::jsonb, 'تحليل', 'تفسير ظاهرة', 'صعب', 'الكتاب ص 141 — الجدول 5-1؛ ص 158 السؤال 71'),
('mcq', 7, 'أيّ مقارنة صحيحة بين الاحتكاك السكوني والحركي من حيث تغير مقدارهما بتغير القوة الأفقية المؤثرة (مع ثبات القوة العمودية)؟', null, null, '["السكوني يتغير بتغيرها حتى قيمته القصوى، والحركي لا يتغير بتغيرها","السكوني ثابت دائمًا عند قيمته القصوى، والحركي يتغير بتغير القوة المؤثرة","كلاهما يتغير بتغير القوة المؤثرة ويساويها مقدارًا","كلاهما ثابت لا يتغير مهما تغيرت القوة المؤثرة"]'::jsonb, 'تحليل', 'مقارنة العلاقة الرياضية', 'صعب', 'الكتاب ص 140–141 — علاقتا الاحتكاك الحركي والسكوني'),
('essay', 1, 'قارن بين الاحتكاك السكوني والاحتكاك الحركي في جدول من حيث: شرط النشوء، والعلاقة الرياضية، وثبات المقدار، ومثال لكل منهما.', null, null, null, 'تحليل', 'مقارنة', 'سهل', 'الكتاب ص 145 — المراجعة 23 (قارن بين الاحتكاك السكوني والاحتكاك الحركي)'),
('essay', 2, 'جسم على أرضية أفقية، والقوة العمودية عليه 60.0 N، و$\mu_{\text{s}} = 0.60$ و$\mu_{\text{k}} = 0.40$. أثرت فيه وهو ساكن قوة أفقية مقدارها: (a) 20 N، (b) 30 N، (c) 50 N. حدد في كل حالة نوع قوة الاحتكاك ومقدارها، مع التعليل.', null, null, null, 'تحليل', 'تحليل حالات', 'متوسط', 'الكتاب ص 141 — قوة الاحتكاك السكوني؛ ص 145 المراجعة 26، 28'),
('essay', 3, 'قال طالب: «قوة الاحتكاك السكوني أكبر دائمًا من قوة الاحتكاك الحركي بين السطحين نفسيهما». قوّم هذه العبارة، موضحًا متى تكون صحيحة ومتى لا تكون، مع مثال عددي.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 141 — الجدول 5-1 والاحتكاك السكوني')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
