from (values
('mcq', 1, 2, 'الاحتكاك السكوني ينشأ بين سطحين متلامسين بالرغم من عدم انزلاق أي منهما على الآخر، أما الحركي فينشأ عند انزلاق أحدهما على الآخر.', '["عكس الشرطين.","نوع الاحتكاك يحدده الانزلاق أو عدمه، لا ميل السطح.","","كلاهما قوة تلامس تنشأ بين سطحين متلامسين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-20T17:53:29.967Z"}'::jsonb),
('mcq', 2, 0, 'في كل صف $\mu_{\text{s}}$ أكبر من $\mu_{\text{k}}$ (مثلًا 0.80 و0.65)، فالقيمة القصوى للاحتكاك السكوني أكبر من الاحتكاك الحركي عند القوة العمودية نفسها، فبدء الحركة يتطلب قوة أكبر.', '["","عكس المقارنة؛ فجميع قيم $\\mu_{\\text{k}}$ في الجدول أصغر.","الفرق واضح في كل الصفوف، كـ 0.50 و0.20.","النسبة بينهما تختلف، لكن $\\mu_{\\text{s}}$ أكبر في جميع الصفوف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-20T17:53:29.967Z"}'::jsonb),
('mcq', 3, 3, '$F_{\text{N}} = (50.0)(9.80) = 490\ \text{N}$. لبدء الحركة يجب التغلب على $\mu_{\text{s}} F_{\text{N}} = (0.50)(490) = 245\ \text{N}$، ولاستمرارها بسرعة ثابتة تكفي قوة تساوي $f_{\text{k}} = (0.20)(490) = 98\ \text{N}$.', '["عكس الترتيب: القوة الأكبر لبدء الحركة لا لاستمرارها.","استعمل $\\mu_{\\text{s}}$ للحالتين، مع أن الاحتكاك بعد بدء الحركة حركي.","ضرب المعاملين في الكتلة ونسي ضربها في g.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.968Z"}'::jsonb),
('mcq', 4, 1, 'في المحاولتين (1) و(2) لا تنزلق الأريكة، فالاحتكاك سكوني، والقوة المحصلة صفر فيساوي الدفع مقدارًا ويعاكسه (100 N ثم 200 N) وفق $f_{\text{s}} \le \mu_{\text{s}} F_{\text{N}}$. وفي المحاولة (3) تنزلق الأريكة فيصبح الاحتكاك حركيًا مقداره $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}}$، وهو لا يتحدد بقوة الدفع.', '["الاحتكاك السكوني لا يساوي قيمته القصوى إلا لحظة بدء الحركة؛ والاحتكاك الحركي $\\mu_{\\text{k}} F_{\\text{N}}$ لا يساوي قوة الدفع إلا إذا كانت السرعة ثابتة، ولا دليل على ذلك.","","نوع الاحتكاك يحدده الانزلاق لا كبر قوة الدفع، والأريكة في المحاولة (2) ما زالت ساكنة.","الاحتكاك الحركي يشترط الانزلاق، والأريكة ساكنة في المحاولتين (1) و(2)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-20T17:53:29.968Z"}'::jsonb),
('mcq', 5, 3, 'كلا النوعين قوة تلامس موازية للسطح تعاكس الحركة أو الميل إليها، ويرتبط كل منهما بالقوة العمودية: $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}}$ والقيمة القصوى للسكوني $\mu_{\text{s}} F_{\text{N}}$.', '["الاحتكاك السكوني يتغير بتغير القوة المؤثرة حتى قيمته القصوى.","كلاهما يعاكس الحركة أو الميل إليها لا يوافقها.","الاحتكاك السكوني ينشأ دون انزلاق.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-20T17:53:29.968Z"}'::jsonb),
('mcq', 6, 2, 'عندما لا تنزلق العجلات على الطريق يكون الاحتكاك بينهما سكونيًا، ويمكن أن يبلغ قيمة قصوى $\mu_{\text{s}} F_{\text{N}}$ أكبر من $\mu_{\text{k}} F_{\text{N}}$؛ فتكون القوة المعيقة أكبر والتسارع المعاكس أكبر ومسافة التوقف أقصر.', '["عكس المقارنة؛ $\\mu_{\\text{s}}$ أكبر من $\\mu_{\\text{k}}$ للسطوح نفسها.","القوة العمودية على طريق أفقي تبقى مساوية للوزن تقريبًا في الحالتين.","","الاحتكاك السكوني موجود ما دام هناك ميل إلى الانزلاق، ولو انعدم لما توقفت السيارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-20T17:53:29.968Z"}'::jsonb),
('mcq', 7, 0, 'علاقة السكوني $f_{\text{s}} \le \mu_{\text{s}} F_{\text{N}}$ تعني أنه يساوي القوة المؤثرة ما دام الجسم ساكنًا حتى قيمته القصوى، أما علاقة الحركي $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}}$ فتعطي قيمة ثابتة لا تعتمد على القوة المؤثرة.', '["","عكس الصفتين.","الاحتكاك الحركي لا يعتمد على القوة المؤثرة؛ فقيمته $\\mu_{\\text{k}} F_{\\text{N}}$.","الاحتكاك السكوني يستجيب للقوة المؤثرة فيتغير معها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-20T17:53:29.968Z"}'::jsonb),
('essay', 1, null::int, null, null, 'شرط النشوء: السكوني بين سطحين متلامسين دون انزلاق، والحركي عند انزلاق أحدهما على الآخر. العلاقة: السكوني $f_{\text{s}} \le \mu_{\text{s}} F_{\text{N}}$، والحركي $f_{\text{k}} = \mu_{\text{k}} F_{\text{N}}$. ثبات المقدار: السكوني يتغير بتغير القوة المؤثرة من الصفر حتى قيمته القصوى، والحركي ثابت عند قوة عمودية معينة. مثال: السكوني على أريكة تُدفع ولا تتحرك، والحركي على صندوق ينزلق على أرضية.', '["شرط النشوء لكل منهما","العلاقتان الرياضيتان","ثبات المقدار أو تغيره","مثال صحيح لكل نوع"]'::jsonb, '[]'::jsonb, '[{"element":"شرط النشوء","marks":1},{"element":"العلاقتان","marks":1},{"element":"ثبات المقدار","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة صحيحة"},{"level":"3 درجات","description":"ثلاثة جوانب صحيحة"},{"level":"درجتان","description":"جانبان صحيحان"},{"level":"درجة واحدة","description":"جانب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة علاقة الحركي بإشارة ≤.","جعل الاحتكاك السكوني ثابتًا يساوي $\\mu_{\\text{s}} F_{\\text{N}}$."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-20T17:53:29.968Z"}'::jsonb),
('essay', 2, null::int, null, null, 'القيمة القصوى للاحتكاك السكوني: $\mu_{\text{s}} F_{\text{N}} = (0.60)(60.0) = 36\ \text{N}$. (a) 20 N < 36 N: يبقى ساكنًا، احتكاك سكوني 20 N. (b) 30 N < 36 N: يبقى ساكنًا، احتكاك سكوني 30 N. (c) 50 N > 36 N: يبدأ الحركة، احتكاك حركي $f_{\text{k}} = (0.40)(60.0) = 24\ \text{N}$، وتتسارع الكتلة لأن 50 N > 24 N.', '["القيمة القصوى 36 N","الحالة a: سكوني 20 N","الحالة b: سكوني 30 N","الحالة c: حركي 24 N مع تعليل بدء الحركة"]'::jsonb, '["$\\mu_{\\text{s}} F_{\\text{N}} = 0.60 \\times 60.0 = 36\\ \\text{N}$","مقارنة كل قوة بـ 36 N","$f_{\\text{k}} = 0.40 \\times 60.0 = 24\\ \\text{N}$"]'::jsonb, '[{"element":"القيمة القصوى","marks":1},{"element":"الحالة a","marks":1},{"element":"الحالة b","marks":1},{"element":"الحالة c","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الحالات صحيحة"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الاحتكاك في الحالتين a وb يساوي 36 N.","جعل الاحتكاك في الحالة c يساوي 36 N."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.968Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة صحيحة فقط إذا قصدنا القيمة القصوى للاحتكاك السكوني: فـ $\mu_{\text{s}} > \mu_{\text{k}}$ للسطوح المألوفة، فتكون $\mu_{\text{s}} F_{\text{N}} > \mu_{\text{k}} F_{\text{N}}$. لكنها ليست صحيحة دائمًا؛ لأن الاحتكاك السكوني يساوي القوة المؤثرة ما دام الجسم ساكنًا، وقد يكون صغيرًا بل صفرًا. مثال: خشب فوق خشب، $F_{\text{N}} = 100\ \text{N}$: القيمة القصوى للسكوني 50 N والحركي 20 N؛ لكن إذا دُفع الجسم الساكن بقوة 10 N فالاحتكاك السكوني 10 N فقط، وهو أصغر من الحركي 20 N.', '["الحكم: العبارة ليست صحيحة دائمًا","تصح عند المقارنة بالقيمة القصوى لأن $\\mu_{\\text{s}} > \\mu_{\\text{k}}$","الاحتكاك السكوني يتغير وقد يكون صغيرًا أو صفرًا","مثال عددي صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"حالة الصحة","marks":1},{"element":"حالة عدم الصحة","marks":1},{"element":"المثال العددي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم كامل بمثال صحيح"},{"level":"3 درجات","description":"تقويم صحيح دون مثال عددي"},{"level":"درجتان","description":"جانب واحد من التقويم"},{"level":"درجة واحدة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة مطلقًا.","رفض العبارة مطلقًا مع أن $\\mu_{\\text{s}} > \\mu_{\\text{k}}$."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-20T17:53:29.969Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
