select (select id from public.objectives where code = 'P1-C5-L2-O11'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في تجربة تحديد معاملي الاحتكاك لقطعة خشبية على سطح أفقي، كيف تُعيَّن القوة العمودية المؤثرة في القطعة؟', null, null, '["بقراءة الميزان لحظة بدء انزلاق القطعة","بقراءة الميزان أثناء سحب القطعة أفقيًا بسرعة ثابتة","بقياس مساحة وجه القطعة الملامس للسطح","بقياس وزن القطعة معلقة رأسيًا بالميزان"]'::jsonb, 'تطبيق', 'إجراء تجريبي', 'سهل', 'الكتاب ص 152–153 — مختبر الفيزياء: معامل الاحتكاك'),
('mcq', 2, 'في الشكل الآتي تُسحب قطعة خشبية ساكنة بميزان نابضي أفقيًا بقوة تزداد ببطء. ماذا تمثل قراءة الميزان لحظة بدء القطعة الانزلاق؟', null, '[{"src":"qimg/phys1/c5l2-o11-setup.svg","alt":"رسم لقطعة خشبية موضوعة على سطح خشبي أفقي، يتصل بها خيط أفقي يمتد نحو اليمين إلى ميزان نابضي أفقي مكتوب فوقه «ميزان نابضي»، وفي طرف الميزان حلقة للسحب."}]'::jsonb, '["قوة الاحتكاك الحركي على القطعة","القيمة القصوى للاحتكاك السكوني","القوة العمودية على القطعة","القوة المحصلة على القطعة"]'::jsonb, 'تطبيق', 'تفسير قراءة', 'سهل', 'الكتاب ص 152–153 — مختبر الفيزياء: معامل الاحتكاك'),
('mcq', 3, 'سجل طالب البيانات الآتية لقطعة خشبية على سطح أفقي، حيث $F_{\text{N}}$ القوة العمودية، و$f_{\text{s}}$ قراءة الميزان لحظة بدء الانزلاق في ثلاث محاولات. ما معامل الاحتكاك السكوني؟', '{"headers":["$F_{\\text{N}}$ (N)","المحاولة 1 (N)","المحاولة 2 (N)","المحاولة 3 (N)"],"rows":[["8.0","3.1","3.3","3.2"]]}'::jsonb, null, '["0.40","2.5","0.041","3.2"]'::jsonb, 'تطبيق', 'حساب من بيانات', 'متوسط', 'الكتاب ص 152–153 — مختبر الفيزياء: معامل الاحتكاك'),
('mcq', 4, 'عند قياس قوة الاحتكاك الحركي في المختبر، لماذا يجب سحب القطعة بالميزان النابضي بسرعة ثابتة؟', null, null, '["لكي تبقى القوة العمودية مساوية لقراءة الميزان","لكي يبلغ الاحتكاك السكوني قيمته القصوى ويبقى عندها طوال القياس","لتكون القوة المحصلة صفرًا فتساوي القراءة قوة الاحتكاك الحركي","لأن الاحتكاك الحركي ينعدم إذا تسارعت القطعة"]'::jsonb, 'فهم', 'تعليل إجراء', 'متوسط', 'الكتاب ص 152–153 — مختبر الفيزياء: معامل الاحتكاك'),
('mcq', 5, 'في تجربة معامل الاحتكاك، قيس معامل الاحتكاك السكوني لقطعة خشبية على سطح خشبي أفقي فكان 0.40. ثم وُضعت القطعة على السطح نفسه ورُفع أحد طرفيه تدريجيًا، فبدأت القطعة الانزلاق عندما بلغت زاوية الميل $22^\circ$، كما في الشكل الآتي. ما قيمة $\tan\theta$ لزاوية بدء الانزلاق، وكيف تقارن بمعامل الاحتكاك السكوني المقيس؟', null, '[{"src":"qimg/phys1/c5l2-o11-incline-22.svg","alt":"سطح مائل على شكل مثلث قائم، زاوية ميله عند قاعدته اليسرى مكتوب عندها 22°، وعليه قطعة خشبية على وشك الانزلاق، ولا توجد أسهم في الشكل."}]'::jsonb, '["0.37؛ وهي أصغر من $\\mu_{\\text{s}}$ المقيس","0.40؛ وهي تساوي $\\mu_{\\text{s}}$ المقيس تقريبًا","0.93؛ وهي أكبر كثيرًا من $\\mu_{\\text{s}}$ المقيس","2.5؛ وهي أكبر كثيرًا من $\\mu_{\\text{s}}$ المقيس"]'::jsonb, 'تطبيق', 'حساب ومقارنة', 'متوسط', 'الكتاب ص 152–153 — مختبر الفيزياء: معامل الاحتكاك (الخطوة 11 والتحليل 3)'),
('mcq', 6, 'في الجزء الأخير من تجربة معامل الاحتكاك، تُقاس الزاوية $\theta$ التي تبدأ عندها القطعة الانزلاق على سطح مائل. إذا علمت أن القوة العمودية على القطعة عندئذ تساوي $F_g \cos\theta$، وأن مركبة وزنها الموازية للسطح $F_g \sin\theta$ يوازنها الاحتكاك السكوني في قيمته القصوى، فماذا تمثل قيمة $\tan\theta$؟', null, null, '["معامل الاحتكاك الحركي بين القطعة والسطح","نسبة القوة العمودية إلى وزن القطعة","القيمة القصوى لقوة الاحتكاك السكوني بوحدة N","معامل الاحتكاك السكوني بين القطعة والسطح"]'::jsonb, 'تحليل', 'تفسير نتيجة تجريبية', 'متوسط', 'الكتاب ص 152–153 — مختبر الفيزياء: معامل الاحتكاك (الاستنتاج 3 و4)'),
('mcq', 7, 'في تجربة معامل الاحتكاك، سُحبت قطعة خشبية وزنها 5.0 N على سطح أفقي بميزان نابضي بسرعة ثابتة فكانت قراءته 1.5 N، ثم وُضعت فوقها كتلة إضافية فأصبحت القوة العمودية 12.0 N وأصبحت القراءة عند السحب بسرعة ثابتة 3.6 N. ما معامل الاحتكاك الحركي في المحاولتين، وما الاستنتاج؟', null, null, '["0.30 في المحاولتين؛ فالمعامل لا يتغير بتغير القوة العمودية","0.30 ثم 0.72؛ فالمعامل يزداد بزيادة القوة العمودية","0.30 ثم 0.13؛ فالمعامل يقل بزيادة القوة العمودية","3.3 في المحاولتين؛ فالمعامل لا يتغير بتغير القوة العمودية"]'::jsonb, 'تطبيق', 'حساب من بيانات', 'صعب', 'الكتاب ص 152–153 — مختبر الفيزياء: معامل الاحتكاك (جدول البيانات 2 و3، التحليل 4)'),
('essay', 1, 'في تجربة لتحديد معاملي الاحتكاك لقطعة خشبية على سطح أفقي، قيس وزن القطعة فكان 6.0 N، وسُجلت قراءات الميزان النابضي في الجدول. (a) احسب متوسط القيمة القصوى لقوة الاحتكاك السكوني ومتوسط قوة الاحتكاك الحركي. (b) احسب $\mu_{\text{s}}$ و$\mu_{\text{k}}$. (c) قارن بين القيمتين وتحقق من معقوليتهما.', '{"headers":["القوة المقيسة (N)","المحاولة 1","المحاولة 2","المحاولة 3"],"rows":[["قراءة الميزان لحظة بدء الانزلاق","2.7","2.9","2.8"],["قراءة الميزان أثناء السحب بسرعة ثابتة","2.0","2.2","2.1"]]}'::jsonb, null, null, 'تطبيق', 'تحليل بيانات تجربة', 'سهل', 'الكتاب ص 152–153 — مختبر الفيزياء: معامل الاحتكاك'),
('essay', 2, 'وُضعت القطعة الخشبية نفسها (معامل احتكاكها السكوني المقيس على السطح الأفقي 0.47) على السطح الخشبي نفسه، ثم رُفع طرفه تدريجيًا فبدأت القطعة الانزلاق عند الزاوية المبينة في الشكل الآتي. علمًا بأن القوة العمودية على القطعة على السطح المائل تساوي $F_g \cos\theta$، وأن مركبة وزنها الموازية للسطح تساوي $F_g \sin\theta$: (a) ارسم مخطط الجسم الحر للقطعة لحظة بدء الانزلاق. (b) بيّن أن $\mu_{\text{s}} = \tan\theta$. (c) احسب $\tan\theta$ وقارنه بالقيمة المقيسة على السطح الأفقي.', null, '[{"src":"qimg/phys1/c5l2-o11-incline-26.svg","alt":"سطح مائل على شكل مثلث قائم، زاوية ميله عند قاعدته اليسرى مكتوب عندها 26.0°، وعليه قطعة خشبية، ولا توجد أسهم في الشكل."}]'::jsonb, null, 'تحليل', 'ربط النظرية بالتجربة', 'صعب', 'الكتاب ص 152–153 — مختبر الفيزياء: معامل الاحتكاك (التحليل والاستنتاج 2–4)'),
('essay', 3, 'إذا تزلجت إلى أسفل تل مكسو بالثلج ورغبت في تحديد معامل الاحتكاك الحركي بين الزلاجة وسطح التل، فكيف يمكنك ذلك؟ اكتب خطوات دقيقة تتضمن ما تقيسه، والشرط الذي يجب تحققه، والعلاقة التي تستعملها. (يمكنك أن تستعمل أنه عندما تنزلق الزلاجة على منحدر زاوية ميله $\theta$ تكون القوة العمودية عليها $F_g \cos\theta$ ومركبة وزنها الموازية للمنحدر $F_g \sin\theta$.)', null, null, null, 'إبداع', 'تصميم إجراء', 'صعب', 'الكتاب ص 152–153 — مختبر الفيزياء: معامل الاحتكاك (الفيزياء في الحياة)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
