insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'على سطح أفقي والقوة المؤثرة أفقية، تساوي القوة العمودية وزن القطعة؛ لذلك يُقاس وزنها بتعليقها رأسيًا بالميزان النابضي وتُسجل القراءة على أنها القوة العمودية.', '["هذه القراءة القيمة القصوى لقوة الاحتكاك السكوني.","هذه القراءة قوة الاحتكاك الحركي.","المساحة لا تحدد القوة العمودية ولا تدخل في حساب المعامل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-20T17:53:29.969Z"}'::jsonb),
('mcq', 2, 1, 'قبل الحركة يساوي الاحتكاك السكوني قراءة الميزان، ولحظة بدء الانزلاق يكون قد بلغ قيمته القصوى؛ فتُسجل هذه القراءة على أنها القيمة القصوى لقوة الاحتكاك السكوني.', '["الاحتكاك الحركي يُقاس بعد بدء الحركة أثناء السحب بسرعة ثابتة.","","القوة العمودية رأسية وتُقاس بوزن القطعة، والميزان هنا يسحب أفقيًا.","القوة المحصلة على القطعة الساكنة صفر، والقراءة تمثل قوة السحب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-20T17:53:29.969Z"}'::jsonb),
('mcq', 3, 0, 'المتوسط = $\frac{3.1 + 3.3 + 3.2}{3} = 3.2\ \text{N}$، و$\mu_{\text{s}} = \frac{f_{\text{s, max}}}{F_{\text{N}}} = \frac{3.2\ \text{N}}{8.0\ \text{N}} = 0.40$.', '["","قسم القوة العمودية على متوسط القوة (مقلوب المعامل).","ضرب القوة العمودية في g وكأنها كتلة.","كتب متوسط قراءة الميزان ولم يقسمه على القوة العمودية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-20T17:53:29.969Z"}'::jsonb),
('mcq', 4, 2, 'عند السرعة الثابتة يكون التسارع صفرًا، فالقوة المحصلة صفر؛ أي أن قوة السحب (قراءة الميزان) تساوي قوة الاحتكاك الحركي مقدارًا وتعاكسها اتجاهًا.', '["القوة العمودية تساوي الوزن، وهي رأسية لا يقيسها الميزان الأفقي.","الاحتكاك السكوني يخص القطعة قبل الحركة، والقياس هنا أثناء الانزلاق.","","الاحتكاك الحركي لا ينعدم بالتسارع، لكن قراءة الميزان عندئذ تصبح أكبر منه فلا تساويه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-20T17:53:29.970Z"}'::jsonb),
('mcq', 5, 1, '$\tan 22^\circ = 0.40$، وهي تساوي تقريبًا معامل الاحتكاك السكوني المقيس على السطح الأفقي (0.40)؛ وهذا ما تهدف إليه مقارنة $\tan\theta$ لزاوية بدء الانزلاق بـ $\mu_{\text{s}}$ في التجربة.', '["حسب $\\sin 22^\\circ$ بدل $\\tan 22^\\circ$.","","حسب $\\cos 22^\\circ$ بدل $\\tan 22^\\circ$.","حسب مقلوب الظل $\\frac{1}{\\tan 22^\\circ}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-20T17:53:29.970Z"}'::jsonb),
('mcq', 6, 3, '$\tan\theta$ يمثل معامل الاحتكاك السكوني بين القطعة والسطح؛ فعند زاوية بدء الانزلاق يكون الاحتكاك السكوني في قيمته القصوى ويوازن مركبة الوزن الموازية للسطح، فـ $\tan\theta = \frac{F_g \sin\theta}{F_g \cos\theta} = \frac{f_{\text{s, max}}}{F_{\text{N}}} = \mu_{\text{s}}$.', '["زاوية بدء الانزلاق مرتبطة بالقيمة القصوى للاحتكاك السكوني لا بالحركي.","نسبة القوة العمودية إلى الوزن تساوي $\\cos\\theta$ لا $\\tan\\theta$.","$\\tan\\theta$ نسبة لا وحدة لها، فلا تمثل قوة بوحدة N.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-20T17:53:29.970Z"}'::jsonb),
('mcq', 7, 0, 'عند السحب بسرعة ثابتة تساوي قراءة الميزان قوة الاحتكاك الحركي، فـ $\mu_{\text{k}} = \frac{f_{\text{k}}}{F_{\text{N}}}$: في المحاولة الأولى $\frac{1.5\ \text{N}}{5.0\ \text{N}} = 0.30$، وفي الثانية $\frac{3.6\ \text{N}}{12.0\ \text{N}} = 0.30$. زادت قوة الاحتكاك بزيادة القوة العمودية، أما المعامل فبقي ثابتًا لأنه يعتمد على نوع السطحين.', '["","قسم القراءة الثانية 3.6 N على وزن القطعة وحدها (5.0 N) بدل القوة العمودية الجديدة 12.0 N.","قسم القراءة الأولى 1.5 N على القوة العمودية الجديدة 12.0 N، فخلط بين بيانات المحاولتين.","قسم القوة العمودية على قراءة الميزان (مقلوب المعامل)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-20T17:53:29.971Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $f_{\text{s, max}}$ (المتوسط) $= \frac{2.7 + 2.9 + 2.8}{3} = 2.8\ \text{N}$؛ $f_{\text{k}}$ (المتوسط) $= \frac{2.0 + 2.2 + 2.1}{3} = 2.1\ \text{N}$. (b) $F_{\text{N}} = 6.0\ \text{N}$، فـ $\mu_{\text{s}} = \frac{2.8}{6.0} = 0.47$ و$\mu_{\text{k}} = \frac{2.1}{6.0} = 0.35$. (c) $\mu_{\text{s}} > \mu_{\text{k}}$ كما هو متوقع، فبدء الحركة يتطلب قوة أكبر من إبقائها بسرعة ثابتة، والقيمتان أقل من واحد وقريبتان من قيم الخشب فوق الخشب، فهما معقولتان.', '["متوسط الاحتكاك السكوني 2.8 N","متوسط الاحتكاك الحركي 2.1 N","$\\mu_{\\text{s}} = 0.47$","$\\mu_{\\text{k}} = 0.35$","المقارنة: $\\mu_{\\text{s}} > \\mu_{\\text{k}}$ ومعقولية النتائج"]'::jsonb, '["متوسط $f_{\\text{s}}$ = (2.7 + 2.9 + 2.8) ÷ 3 = 2.8 N","متوسط $f_{\\text{k}}$ = (2.0 + 2.2 + 2.1) ÷ 3 = 2.1 N","$\\mu_{\\text{s}} = 2.8 \\div 6.0 = 0.47$","$\\mu_{\\text{k}} = 2.1 \\div 6.0 = 0.35$"]'::jsonb, '[{"element":"المتوسطان","marks":2},{"element":"المعاملان","marks":2},{"element":"المقارنة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"4 درجات","description":"خطأ حسابي واحد"},{"level":"3 درجات","description":"المتوسطان ومعامل واحد"},{"level":"درجتان","description":"المتوسطان فقط"},{"level":"درجة واحدة","description":"متوسط واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة القوة العمودية على قوة الاحتكاك.","استعمال قراءة محاولة واحدة بدل المتوسط.","تبديل عمودي السكوني والحركي."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-20T17:53:29.971Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) نقطة تمثل القطعة تخرج منها: الوزن $\boldsymbol{F}_g$ رأسيًا إلى أسفل، والقوة العمودية $\boldsymbol{F}_{\text{N}}$ عمودية على السطح نحو الخارج، وقوة الاحتكاك السكوني $\boldsymbol{f}_{\text{s}}$ موازية للسطح نحو أعلاه. (b) نختار المحور x موازيًا للسطح: عموديًا على السطح $F_{\text{N}} = F_g \cos\theta$، وموازيًا له لحظة بدء الانزلاق $f_{\text{s, max}} = F_g \sin\theta$؛ وبما أن $f_{\text{s, max}} = \mu_{\text{s}} F_{\text{N}}$ فإن $\mu_{\text{s}} = \frac{F_g \sin\theta}{F_g \cos\theta} = \tan\theta$. (c) $\tan 26.0^\circ = 0.488$؛ وهي قريبة من 0.47 (الفرق نحو 4%)، فالطريقتان متفقتان في حدود أخطاء القياس.', '["مخطط جسم حر صحيح بثلاث قوى","كتابة $F_{\\text{N}} = F_g \\cos\\theta$ و$f_{\\text{s, max}} = F_g \\sin\\theta$","الوصول إلى $\\mu_{\\text{s}} = \\tan\\theta$","حساب 0.488 والمقارنة بـ 0.47"]'::jsonb, '["$F_{\\text{N}} = F_g \\cos\\theta$","$f_{\\text{s, max}} = F_g \\sin\\theta = \\mu_{\\text{s}} F_g \\cos\\theta$","$\\mu_{\\text{s}} = \\tan\\theta = \\tan 26.0^\\circ = 0.488$","المقارنة: 0.488 ≈ 0.47"]'::jsonb, '[{"element":"مخطط الجسم الحر","marks":1},{"element":"المعادلتان","marks":1},{"element":"الاشتقاق","marks":1},{"element":"الحساب والمقارنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3 درجات","description":"خطأ في عنصر واحد"},{"level":"درجتان","description":"المخطط والحساب دون اشتقاق"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم القوة العمودية رأسية.","رسم الاحتكاك نحو أسفل السطح.","استعمال $\\sin\\theta$ بدل $\\tan\\theta$."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-20T17:53:29.971Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يمكن ذلك بطريقتين: (1) على جزء أفقي مغطى بالثلج نفسه: نقيس وزن الزلاجة بميزان نابضي (القوة العمودية)، ثم نسحبها أفقيًا بالميزان بسرعة ثابتة ونسجل القراءة (قوة الاحتكاك الحركي) ونكرر ثلاث مرات ونأخذ المتوسط، ثم $\mu_{\text{k}} = \frac{f_{\text{k}}}{F_{\text{N}}}$. (2) على التل: نبحث عن جزء من المنحدر تنزلق عليه الزلاجة بسرعة ثابتة (نتحقق بقياس أزمنة متساوية لمسافات متساوية)، ونقيس زاوية ميله $\theta$؛ وعند السرعة الثابتة القوة المحصلة صفر فـ $F_g \sin\theta = \mu_{\text{k}} F_g \cos\theta$، ومنه $\mu_{\text{k}} = \tan\theta$. ونكرر القياس ونأخذ المتوسط.', '["قياس القوة العمودية (الوزن) أو زاوية الميل","شرط السرعة الثابتة","قياس قوة الاحتكاك أو التحقق من السرعة الثابتة","العلاقة المستعملة $\\mu_{\\text{k}} = f_{\\text{k}}/F_{\\text{N}}$ أو $\\tan\\theta$","تكرار القياس وأخذ المتوسط"]'::jsonb, '[]'::jsonb, '[{"element":"ما يُقاس","marks":1},{"element":"شرط السرعة الثابتة","marks":1},{"element":"طريقة القياس","marks":1},{"element":"العلاقة","marks":1},{"element":"التكرار","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات كاملة دقيقة"},{"level":"4 درجات","description":"نقص عنصر واحد"},{"level":"3 درجات","description":"طريقة صحيحة دون شرط السرعة الثابتة"},{"level":"درجتان","description":"فكرة عامة صحيحة دون تفاصيل"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال زاوية بدء الانزلاق لحساب المعامل الحركي.","القياس والزلاجة تتسارع."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-20T17:53:29.971Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C5-L2-O11') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C5-L3-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تؤثر في جسم أربع قوى مختلفة المقادير والاتجاهات تقع في مستوى واحد (بُعدين). ما الشرط اللازم ليكون الجسم متزنًا؟', null, null, '["أن تكون جميع القوى المؤثرة فيه متساوية في المقدار","أن تكون القوى المؤثرة فيه متعامدة بعضها على بعض","أن تكون محصلة القوى المؤثرة فيه صفرًا","أن تؤثر فيه قوتان فقط متعاكستان في الاتجاه"]'::jsonb, 'تذكر', 'تعريف مفهوم', 'سهل', 'الكتاب ص 146 — الاتزان'),
('mcq', 2, 'يؤثر في حلقة ساكنة موضوعة على سطح أفقي أملس ثلاث قوى أفقية كما في الشكل الآتي (منظر من أعلى). ما الوصف الصحيح لحالة الحلقة؟', null, '[{"src":"qimg/phys1/c5l3-o01-ring3.svg","alt":"مخطط قوى من أعلى لحلقة عند نقطة الأصل، مع محورين متقطعين +x إلى اليمين و+y إلى أعلى. ثلاثة أسهم زرقاء تخرج من الحلقة: سهم إلى اليمين على المحور x مكتوب عنده 30.0 N، وسهم إلى أعلى على المحور y مكتوب عنده 40.0 N، وسهم إلى أسفل اليسار مكتوب عنده 50.0 N يصنع زاوية 53.1° أسفل الاتجاه السالب للمحور x (الزاوية محصورة بين السهم والجزء الأيسر من المحور x)."}]'::jsonb, '["تبقى ساكنة؛ لأن مجموع المركّبات x ومجموع المركّبات y للقوى يساوي كلٌّ منهما صفرًا","تتسارع في اتجاه القوة 50.0 N؛ لأنها أكبر القوى الثلاث مقدارًا","تتسارع؛ لأن القوى الثلاث غير متساوية في المقدار","تتسارع؛ لأن القوى الثلاث لا تقع على خط مستقيم واحد"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 146 — الاتزان، الشكل 5-11'),
('mcq', 3, 'هل يمكن أن يكون جسم متحرك في حالة اتزان؟', null, null, '["لا؛ فالجسم المتزن يجب أن يكون ساكنًا دائمًا","نعم؛ إذا تحرك بسرعة ثابتة المقدار حتى لو تغيّر اتجاهها","نعم؛ إذا تحرك بتسارع ثابت في خط مستقيم","نعم؛ إذا تحرك بسرعة متجهة ثابتة في خط مستقيم"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 156 — التقويم 54'),
('mcq', 4, 'يمثل مخطط الحركة الآتي قرصًا ينزلق على سطح أفقي، وقد التُقطت صوره على فترات زمنية متساوية. ماذا تستنتج عن القوى المؤثرة في القرص؟', null, '[{"src":"qimg/phys1/c5l3-o01-dots.svg","alt":"مخطط حركة: سبع نقاط سوداء على خط أفقي واحد، المسافات بينها متساوية تمامًا، وفوق كل نقطة (عدا الأخيرة) سهم أحمر يشير إلى اليمين يمثل السرعة المتجهة، والأسهم كلها متساوية الطول. تحت النقاط محور أفقي مكتوب عند طرفه d، وعند بدايته 0."}]'::jsonb, '["لا تؤثر فيه أي قوة على الإطلاق","محصلتها صفر؛ فالقرص متزن رغم أنه يتحرك","محصلتها ثابتة لا تساوي صفرًا وفي اتجاه حركته","محصلتها في عكس اتجاه حركته فتبطئه"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 146 — الاتزان'),
('mcq', 5, 'أيّ الأجسام الآتية في حالة اتزان تحت تأثير قوى ليست على خط واحد؟', null, null, '["كتاب ساكن على سطح مائل خشن","سيارة تسير بسرعة ثابتة المقدار في منعطف دائري","كرة عند أعلى نقطة في مسارها بعد قذفها رأسيًا إلى أعلى","صندوق ينزلق بتسارع ثابت إلى أسفل سطح مائل أملس"]'::jsonb, 'تحليل', 'تصنيف مواقف', 'متوسط', 'الكتاب ص 146 — الاتزان'),
('mcq', 6, 'تؤثر ثلاث قوى غير متعامدة في جسم متزن. ما مقدار تسارع الجسم؟ ولماذا؟', null, null, '["يساوي g؛ لأن الوزن إحدى القوى المؤثرة فيه","صفر في الاتجاه الأفقي فقط؛ لأن الوزن قوة رأسية","صفر؛ لأن التسارع يساوي القوة المحصلة مقسومة على الكتلة، والمحصلة صفر","يتناسب مع أكبر القوى الثلاث؛ لأنها تحدد اتجاه الحركة"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 146 — الاتزان وقانون نيوتن الثاني'),
('mcq', 7, 'يستقر كتاب على سطح مائل خشن، وتؤثر فيه ثلاث قوى: الوزن $\boldsymbol{F}_{g}$ والقوة العمودية $\boldsymbol{F}_{\text{N}}$ وقوة الاحتكاك السكوني $\boldsymbol{f}_{\text{s}}$. أيّ العبارات الآتية صحيحة؟', null, null, '["مقدار القوة العمودية يساوي مقدار وزن الكتاب، وهي تعاكسه في الاتجاه","قوة الاحتكاك السكوني وحدها تساوي وزن الكتاب في المقدار","الكتاب غير متزن؛ لأن القوى الثلاث لا تقع على خط واحد","المجموع المتجهي للقوى الثلاث صفر رغم أن كل قوة منها في اتجاه مختلف"]'::jsonb, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 146، 150 — الاتزان والسطح المائل'),
('essay', 1, 'وضّح المقصود بحالة الاتزان لجسم تؤثر فيه عدة قوى في بُعدين، ثم بيّن هل يمكن لجسم متزن أن يتحرك، وأعطِ مثالًا لجسم متزن ساكن وآخر متزن متحرك.', null, null, null, 'فهم', 'شرح مفهوم', 'متوسط', 'الكتاب ص 146، 156 — الاتزان، التقويم 53–54'),
('essay', 2, 'تتدلى إشارة مرور كتلتها 10.0 kg ساكنةً من حبلين متماثلين، يصنع كلٌّ منهما زاوية $30.0^\circ$ مع الأفقي كما في الشكل الآتي، وقوة الشد في كل حبل 98.0 N. (أ) سمِّ القوى المؤثرة في الإشارة. (ب) بيّن بالحساب أن الإشارة متزنة رغم أن القوى المؤثرة فيها ليست على خط واحد.', null, '[{"src":"qimg/phys1/c5l3-o01-light.svg","alt":"إشارة مرور (صندوق داكن فيه ثلاثة مصابيح أحمر وأصفر وأخضر) مكتوب بجانبها 10.0 kg، معلّقة من نقطة يلتقي عندها حبلان مشدودان إلى قمتي عمودين على الجانبين. خط أفقي متقطع يمر بنقطة الالتقاء، وكل حبل يصنع معه زاوية مكتوب عندها 30.0°؛ الأيسر يصعد إلى اليسار والأيمن يصعد إلى اليمين."}]'::jsonb, null, 'تحليل', 'تحقق حسابي', 'صعب', 'الكتاب ص 146 — الاتزان'),
('essay', 3, 'قال طالب: «الصندوق الذي يُسحب بحبل مائل على أرض أفقية خشنة بسرعة ثابتة في خط مستقيم غير متزن؛ لأنه يتحرك ولأن القوى المؤثرة فيه ليست على خط واحد، أما السيارة التي تسير بسرعة مقدارها ثابت 60 km/h في منعطف دائري فمتزنة لأن عداد سرعتها لا يتغير». قوّم العبارتين، مبيّنًا الصواب في كل حالة مع التعليل.', null, null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 146، 156 — الاتزان، التقويم 54')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C5-L3-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'يتزن الجسم عندما تكون محصلة القوى المؤثرة فيه صفرًا، مهما كان عدد هذه القوى أو اتجاهاتها؛ فلا يتسارع، ويبقى ساكنًا أو يتحرك بسرعة ثابتة في خط مستقيم.', '["تساوي مقادير القوى لا يكفي؛ فثلاث قوى متساوية قد تكون محصلتها غير صفرية إذا لم تُغلق متجهاتها مضلعًا.","التعامد ليس شرطًا للاتزان؛ فقد يتزن الجسم تحت قوى غير متعامدة، وقد لا يتزن تحت قوى متعامدة.","","الاتزان قد يحدث مع أي عدد من القوى؛ والمهم أن تكون محصلتها صفرًا لا أن تكونا قوتين فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-20T17:53:29.972Z"}'::jsonb),
('mcq', 2, 0, 'مركّبتا القوة 50.0 N: $-50.0\cos 53.1^\circ = -30.0\ \text{N}$ و$-50.0\sin 53.1^\circ = -40.0\ \text{N}$. إذن $\sum F_x = 30.0 - 30.0 = 0$ و$\sum F_y = 40.0 - 40.0 = 0$، فالمحصلة صفر والحلقة متزنة؛ أي إن مجموع المركّبات x ومجموع المركّبات y يساوي كلٌّ منهما صفرًا، فتبقى الحلقة ساكنة.', '["","كبر إحدى القوى لا يعني أن الحلقة تتسارع في اتجاهها؛ فمركّبتاها تلغيان القوتين الأخريين تمامًا.","لا يُشترط تساوي المقادير؛ فالمهم أن يكون المجموع المتجهي صفرًا، وهو كذلك هنا.","القوى غير الواقعة على خط واحد قد تكون محصلتها صفرًا إذا أغلقت متجهاتها مثلثًا، كما في هذه الحالة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-20T17:53:29.972Z"}'::jsonb),
('mcq', 3, 3, 'الجسم المتزن محصلة القوى المؤثرة فيه صفر، فلا يتسارع وفق قانون نيوتن الثاني؛ لذا إما أن يكون ساكنًا وإما أن يتحرك بسرعة متجهة ثابتة (مقدارًا واتجاهًا) في خط مستقيم.', '["السكون حالة واحدة من حالتي الاتزان؛ فالحركة بسرعة متجهة ثابتة في خط مستقيم اتزان أيضًا.","تغيّر اتجاه السرعة يعني وجود تسارع، والتسارع يتطلب قوة محصلة لا تساوي صفرًا.","التسارع الثابت يعني وجود قوة محصلة ثابتة لا تساوي صفرًا، فالجسم غير متزن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-20T17:53:29.972Z"}'::jsonb),
('mcq', 4, 1, 'المسافات بين الصور المتتالية متساوية في خط مستقيم، وأسهم السرعة متساوية الطول؛ فالسرعة المتجهة ثابتة والتسارع صفر، إذن محصلة القوى المؤثرة في القرص صفر، وهو متزن رغم حركته.', '["تؤثر في القرص قوى فعلًا (وزنه والقوة العمودية مثلًا)؛ المهم أن محصلتها صفر لا أن تنعدم القوى.","","المحصلة الثابتة غير الصفرية تُكسب القرص تسارعًا فتتباعد صوره تدريجيًا، والصور هنا متساوية التباعد.","لو كانت المحصلة عكس الحركة لتقاربت الصور تدريجيًا وقصرت أسهم السرعة، وهذا غير ظاهر في المخطط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-20T17:53:29.972Z"}'::jsonb),
('mcq', 5, 0, 'الكتاب الساكن على السطح المائل لا يتسارع؛ فمحصلة القوى المؤثرة فيه (الوزن والقوة العمودية والاحتكاك السكوني) صفر رغم أنها في ثلاثة اتجاهات مختلفة، فهو متزن.', '["","اتجاه سرعة السيارة يتغير في المنعطف، فلها تسارع، ومحصلة القوى المؤثرة فيها لا تساوي صفرًا.","سرعة الكرة لحظيًا صفر عند القمة، لكن وزنها يؤثر فيها وتسارعها g إلى أسفل؛ فالمحصلة لا تساوي صفرًا.","الصندوق يتسارع، فمحصلة القوى المؤثرة فيه لا تساوي صفرًا (مركّبة الوزن الموازية للسطح غير موزونة)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-20T17:53:29.972Z"}'::jsonb),
('mcq', 6, 2, 'وفق قانون نيوتن الثاني $\boldsymbol{a} = \frac{\boldsymbol{F}_{\text{المحصلة}}}{m}$، أي إن التسارع يساوي القوة المحصلة مقسومة على الكتلة، والجسم المتزن محصلة القوى المؤثرة فيه صفر، إذن تسارعه صفر في كل الاتجاهات، مهما كان عدد القوى أو اتجاهاتها.', '["يكون التسارع g عندما يكون الوزن هو القوة الوحيدة المؤثرة (سقوط حر)، أما هنا فالقوى الأخرى توازنه.","الاتزان يعني انعدام المحصلة في كل الاتجاهات، فالتسارع صفر أفقيًا ورأسيًا معًا.","","التسارع تحدده المحصلة لا أكبر القوى، والمحصلة هنا صفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-20T17:53:29.972Z"}'::jsonb),
('mcq', 7, 3, 'الكتاب ساكن فلا يتسارع، إذن $\boldsymbol{F}_{g} + \boldsymbol{F}_{\text{N}} + \boldsymbol{f}_{\text{s}} = 0$. فالمجموع المتجهي للقوى الثلاث صفر رغم أن كل قوة منها في اتجاه مختلف (رأسي، وعمودي على السطح، وموازٍ للسطح)، ومتجهاتها مرسومة رأسًا لذيل تكوّن مثلثًا مغلقًا.', '["القوة العمودية عمودية على السطح المائل لا رأسية، وتوازن مركّبة الوزن العمودية فقط ($F_g\\cos\\theta$)، فهي أصغر من الوزن.","الاحتكاك السكوني يوازن مركّبة الوزن الموازية للسطح فقط ($F_g\\sin\\theta$)، لا الوزن كله.","الاتزان لا يتطلب أن تكون القوى على خط واحد؛ يكفي أن يكون مجموعها المتجهي صفرًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-20T17:53:29.973Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يكون الجسم متزنًا عندما تكون محصلة القوى المؤثرة فيه صفرًا، مهما كان عدد القوى واتجاهاتها. ووفق قانون نيوتن الثاني $\boldsymbol{a} = \frac{\boldsymbol{F}_{\text{المحصلة}}}{m}$ فإن تسارعه صفر؛ لذا إما أن يكون ساكنًا وإما أن يتحرك بسرعة متجهة ثابتة في خط مستقيم. نعم، يمكن لجسم متزن أن يتحرك بشرط ثبات سرعته المتجهة مقدارًا واتجاهًا. مثال المتزن الساكن: إشارة مرور معلّقة بحبلين، أو كتاب ساكن على سطح مائل. مثال المتزن المتحرك: صندوق يُسحب بسرعة ثابتة في خط مستقيم على أرض أفقية، أو مظلي يهبط بسرعته الحدية.', '["الاتزان: محصلة القوى المؤثرة صفر","التسارع صفر وفق قانون نيوتن الثاني","يمكن أن يتحرك بسرعة متجهة ثابتة في خط مستقيم","مثالان صحيحان: ساكن ومتحرك"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الاتزان","marks":1},{"element":"ربطه بانعدام التسارع","marks":1},{"element":"الحكم على إمكان الحركة مع الشرط","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح وربط بقانون نيوتن الثاني وحكم مشروط ومثالان صحيحان"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص في الشرط أو في أحد المثالين"},{"level":"درجة واحدة","description":"تعريف صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الجسم المتزن لا بد أن يكون ساكنًا","اعتبار الحركة بسرعة ثابتة المقدار في مسار منحنٍ اتزانًا","القول إن الاتزان يعني انعدام القوى المؤثرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-20T17:53:29.973Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تؤثر في الإشارة ثلاث قوى: قوة الشد في الحبل الأيسر وقوة الشد في الحبل الأيمن (كلٌّ منهما على امتداد حبلها)، ووزنها $F_g = mg = (10.0)(9.80) = 98.0\ \text{N}$ إلى أسفل. (ب) باختيار +x إلى اليمين و+y إلى أعلى: المركّبتان الأفقيتان للشدّين $+98.0\cos 30.0^\circ = +84.9\ \text{N}$ و$-84.9\ \text{N}$، فمجموعهما صفر. والمركّبتان الرأسيتان $98.0\sin 30.0^\circ = 49.0\ \text{N}$ لكل حبل، فمجموع المركّبات الرأسية $49.0 + 49.0 - 98.0 = 0$. إذن $\sum F_x = 0$ و$\sum F_y = 0$، فالمحصلة صفر والإشارة متزنة؛ والاتزان لا يتطلب أن تقع القوى على خط واحد، بل أن يكون مجموعها المتجهي صفرًا.', '["القوى الثلاث: شدّا الحبلين والوزن","الوزن 98.0 N","مجموع المركّبات الأفقية صفر","مجموع المركّبات الرأسية صفر"]'::jsonb, '["$F_g = mg = (10.0\\ \\text{kg})(9.80\\ \\text{m/s}^2) = 98.0\\ \\text{N}$","$\\sum F_x = 98.0\\cos 30.0^\\circ - 98.0\\cos 30.0^\\circ = 84.9 - 84.9 = 0$","$\\sum F_y = 2(98.0\\sin 30.0^\\circ) - 98.0 = 98.0 - 98.0 = 0$","المحصلة صفر، إذن الإشارة متزنة"]'::jsonb, '[{"element":"تسمية القوى الثلاث","marks":1},{"element":"حساب الوزن","marks":1},{"element":"المركّبات الأفقية","marks":1},{"element":"المركّبات الرأسية والاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"القوى مسماة، والحسابان صحيحان، والاستنتاج مبرر"},{"level":"2–3 درجات","description":"تحليل أحد الاتجاهين فقط أو خطأ حسابي بسيط"},{"level":"درجة واحدة","description":"تسمية القوى فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال $\\sin$ للمركّبة الأفقية و$\\cos$ للرأسية مع أن الزاوية مقيسة من الأفقي","التحقق من الاتجاه الرأسي فقط وإهمال الأفقي","جمع مقداري الشدّين مباشرة ومقارنته بالوزن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-20T17:53:29.973Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارتان خاطئتان. الصندوق: سرعته المتجهة ثابتة مقدارًا واتجاهًا (حركة في خط مستقيم)، فتسارعه صفر، ومحصلة القوى الأربع المؤثرة فيه (الوزن والقوة العمودية والاحتكاك وقوة الشد المائلة) صفر: فالمركّبة الأفقية للشد توازن الاحتكاك، ومجموع المركّبة الرأسية للشد والقوة العمودية يوازن الوزن؛ فهو متزن رغم حركته ورغم أن القوى ليست على خط واحد. السيارة في المنعطف: مقدار سرعتها ثابت لكن اتجاهها يتغير باستمرار، فسرعتها المتجهة تتغير ولها تسارع، فمحصلة القوى المؤثرة فيها لا تساوي صفرًا وهي غير متزنة. فالمعيار هو انعدام المحصلة (ثبات السرعة المتجهة مقدارًا واتجاهًا)، لا مجرد الحركة أو اتجاهات القوى أو قراءة العداد.', '["الصندوق متزن","تعليل: سرعة متجهة ثابتة في خط مستقيم، والمحصلة صفر رغم أن القوى ليست على خط واحد","السيارة غير متزنة","تعليل: تغير اتجاه السرعة يعني تسارعًا وقوة محصلة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على الصندوق","marks":1},{"element":"تعليله","marks":1},{"element":"الحكم على السيارة","marks":1},{"element":"تعليله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكمان صحيحان مع تعليل كامل يستند إلى السرعة المتجهة أو المحصلة"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليله في حالة واحدة، أو حكمان بلا تعليل كافٍ"},{"level":"درجة واحدة","description":"حكم صحيح واحد بلا تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين ثبات مقدار السرعة وثبات السرعة المتجهة","الاعتقاد أن أي جسم متحرك غير متزن","الظن أن الاتزان يتطلب أن تقع القوى على خط واحد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-20T17:53:29.973Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C5-L3-O01') and x.type = v.type and x.number = v.number
