from (values
('mcq', 1, 'ما المقصود بالقوة الموازنة؟', null, null, '["القوة التي لها التأثير نفسه للقوى المؤثرة في الجسم مجتمعة","القوة التي تؤثر في الجسم فتجعله متزنًا","أكبر القوى المؤثرة في الجسم مقدارًا","القوة العمودية التي يؤثر بها السطح في الجسم"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 146، 155 — القوة الموازنة'),
('mcq', 2, 'ما العلاقة بين القوة الموازنة والقوة المحصلة لمجموعة قوى تؤثر في جسم؟', null, null, '["تساويها في المقدار ولها الاتجاه نفسه","تساوي نصفها في المقدار وتعاكسها في الاتجاه","تساويها في المقدار وتعاكسها في الاتجاه","تساويها في المقدار وتكون عمودية عليها"]'::jsonb, 'فهم', 'علاقة بين مفهومين', 'سهل', 'الكتاب ص 146 — القوة الموازنة'),
('mcq', 3, 'يؤثر في جسم نقطي القوتان A وB المبينتان يسار الشكل الآتي. أيّ الأسهم المرقمة يمثل القوة الموازنة لهاتين القوتين؟', null, '[{"src":"qimg/phys1/c5l3-o02-candidates.svg","alt":"في يسار الشكل نقطة يخرج منها سهمان أزرقان: A أفقي إلى اليمين طوله 4 وحدات، وB رأسي إلى أعلى طوله 3 وحدات. يفصلها خط عن يمين الشكل حيث أربعة أسهم زرقاء مرقمة: السهم 1 طوله 5 وحدات يتجه إلى أعلى اليمين بزاوية 36.9° فوق الأفقي؛ السهم 2 طوله 4 وحدات يتجه أفقيًا إلى اليسار؛ السهم 3 طوله 5 وحدات يتجه إلى أسفل اليسار بزاوية 36.9° تحت الأفقي؛ السهم 4 طوله 5 وحدات يتجه إلى أسفل اليسار بزاوية 53.1° تحت الأفقي."}]'::jsonb, '["السهم 1","السهم 2","السهم 3","السهم 4"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 146 — الشكل 5-12'),
('mcq', 4, 'يتزن جسم تحت تأثير ثلاث قوى، إحداها $\boldsymbol{F}_1$ مقدارها 20.0 N نحو الشمال. إذا أُزيلت $\boldsymbol{F}_1$ فجأة، فما محصلة القوتين الباقيتين؟', null, null, '["20.0 N نحو الجنوب","20.0 N نحو الشمال","صفر؛ لأن الجسم كان متزنًا","40.0 N نحو الجنوب"]'::jsonb, 'تطبيق', 'استنتاج', 'متوسط', 'الكتاب ص 146 — القوة الموازنة'),
('mcq', 5, 'يبين الشكل الآتي جمع القوتين A وB بطريقة الرسم، والمتجه المتقطع R محصلتهما. أيّ مما يأتي يمثل القوة الموازنة للقوتين؟', null, '[{"src":"qimg/phys1/c5l3-o02-triangle.svg","alt":"مثلث متجهات أزرق: السهم A أفقي إلى اليمين من الركن الأيسر السفلي، يليه السهم B يبدأ من رأس A ويتجه إلى أعلى اليمين بميل كبير، وسهم متقطع مكتوب عنده R يبدأ من ذيل A وينتهي عند رأس B."}]'::jsonb, '["المتجه $\\boldsymbol{R}$ نفسه","المتجه $\\boldsymbol{A} - \\boldsymbol{B}$","المتجه $\\boldsymbol{B} - \\boldsymbol{A}$","المتجه $-\\boldsymbol{R}$"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 146 — الشكل 5-12'),
('mcq', 6, 'جسم متزن أصلًا تحت تأثير عدة قوى. ما مقدار القوة الموازنة اللازمة له؟', null, null, '["يساوي مجموع مقادير القوى المؤثرة فيه","يساوي مقدار أكبر القوى المؤثرة فيه","يساوي وزن الجسم دائمًا","صفر؛ لأن محصلة القوى المؤثرة فيه صفر"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'سهل', 'الكتاب ص 146 — القوة الموازنة'),
('mcq', 7, 'أيّ العبارات الآتية يصف الفرق بين القوة المحصلة والقوة الموازنة لمجموعة قوى تؤثر في جسم؟', null, null, '["المحصلة تحل محل القوى مجتمعة، أما الموازنة فتُضاف إلى القوى فتصبح محصلتها صفرًا","المحصلة والموازنة كلتاهما تُضافان إلى القوى الأصلية فتتضاعف محصلتها","الموازنة تساوي المحصلة مقدارًا واتجاهًا لكنها تؤثر في جسم آخر","الموازنة تساوي مجموع مقادير القوى، واتجاهها عكس اتجاه أكبر قوة"]'::jsonb, 'تحليل', 'مقارنة مفهومين', 'صعب', 'الكتاب ص 146، 155 — المحصلة والقوة الموازنة'),
('essay', 1, 'تؤثر القوتان A وB في جسم نقطي كما في الشكل الآتي. صف خطوات إيجاد القوة الموازنة لهما بطريقة الرسم، ثم صف مقدارها واتجاهها بالنسبة إلى محصلتهما، وبيّن ما الشكل الذي تكوّنه القوى الثلاث إذا رُسمت رأسًا لذيل.', null, '[{"src":"qimg/phys1/c5l3-o02-two-forces.svg","alt":"نقطة سوداء يخرج منها سهمان أزرقان: A أفقي إلى اليمين وهو الأطول، وB أقصر منه يتجه إلى أعلى اليمين ويصنع زاوية 60° مع A."}]'::jsonb, null, 'فهم', 'وصف إجراء', 'متوسط', 'الكتاب ص 146 — الشكل 5-12'),
('essay', 2, 'لتخليص سيارة من الوحل رُبط حبل بين السيارة وشجرة، ثم سُحبت نقطة منتصف الحبل بقوة صغيرة F عموديًا على الحبل كما في الشكل الآتي، فانحرف كل نصف من الحبل بزاوية صغيرة $\theta$ عن خطه الأصلي. (أ) صف مخطط الجسم الحر لنقطة المنتصف. (ب) فسّر باستعمال مفهوم القوة الموازنة لماذا تكون قوة الشد في الحبل كبيرة رغم صغر F. (ج) احسب قوة الشد إذا كانت F = 400 N و$\theta = 5.0^\circ$.', null, '[{"src":"qimg/phys1/c5l3-o02-rope.svg","alt":"سيارة في اليسار وشجرة في اليمين، بينهما حبل مشدود. خط متقطع أفقي يصل نقطتي الربط ويمثل الوضع الأصلي للحبل. منتصف الحبل منخفض قليلًا عن الخط المتقطع فيتكون شكل حرف V منفرج جدًا، ومكتوب عنده «نقطة المنتصف». من نقطة المنتصف يخرج سهم أزرق رأسي إلى أسفل مكتوب عنده F."}]'::jsonb, null, 'تحليل', 'تفسير وحساب', 'صعب', 'الكتاب ص 151 — المراجعة 37'),
('essay', 3, 'تُعلَّق لوحة فنية بسلك طويل بإحدى طريقتين كما في الشكل الآتي: في الطريقة 1 يكون السلك قريبًا من الأفقي، وفي الطريقة 2 يميل بشدة. إذا كانت قوة الشد الكبيرة قد تقطع السلك، فأيّ الطريقتين أفضل؟ قوّم ذلك مستعينًا بمفهوم القوة الموازنة، ثم ادعم إجابتك بحساب الشد للوحة وزنها 50.0 N عندما يميل كل جزء من السلك بزاوية $15.0^\circ$ على الأفقي ثم $40.0^\circ$.', null, '[{"src":"qimg/phys1/c5l3-o02-frames.svg","alt":"لوحتان فنيتان متماثلتان معلقتان بسلك ونقطة تعليق فوق منتصف كل منهما. في اللوحة المرقمة 1 يرتفع السلك ارتفاعًا قليلًا فوق إطار اللوحة فيكاد يكون أفقيًا، وفي اللوحة المرقمة 2 يرتفع السلك كثيرًا فيصنع جزآه زاوية كبيرة مع الأفقي."}]'::jsonb, null, 'تقويم', 'مقارنة وتقويم', 'صعب', 'الكتاب ص 151 — المراجعة 40')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
