insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'القوة الموازنة هي القوة التي تؤثر في الجسم فتجعله متزنًا؛ أي تجعل محصلة القوى المؤثرة فيه صفرًا.', '["هذا وصف القوة المحصلة لا الموازنة؛ فالمحصلة تحل محل القوى، والموازنة تُلغي أثرها.","","أكبر القوى لا تجعل الجسم متزنًا بالضرورة، والموازنة قوة إضافية تُلغي أثر القوى جميعها.","القوة العمودية قوة تلامس عمودية على السطح، ولا توازن إلا مركّبة القوى العمودية عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-20T17:53:29.974Z"}'::jsonb),
('mcq', 2, 2, 'القوة الموازنة تساوي القوة المحصلة في المقدار وتعاكسها في الاتجاه ($-\boldsymbol{R}$)؛ فإذا أُضيفت إلى القوى أصبحت المحصلة صفرًا.', '["لو كانت في اتجاه المحصلة لتضاعفت المحصلة بدل أن تنعدم.","نصف المحصلة المعاكس يُبقي محصلة مقدارها نصف المحصلة الأصلية، فلا يتزن الجسم.","","القوة العمودية على المحصلة لا تُلغيها؛ بل تنتج محصلة جديدة أكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (64%)"}],"at":"2026-11-20T17:53:29.974Z"}'::jsonb),
('mcq', 3, 2, 'محصلة A (أفقية إلى اليمين) وB (رأسية إلى أعلى) تتجه إلى أعلى اليمين، وطولها وتر المثلث القائم الذي ضلعاه A وB. القوة الموازنة تساوي المحصلة طولًا وتعاكسها اتجاهًا، فتتجه إلى أسفل اليسار بالزاوية نفسها، وهو السهم 3.', '["السهم 1 في اتجاه المحصلة نفسها؛ فإضافته تضاعف المحصلة ولا تجعل الجسم متزنًا.","السهم 2 يعاكس A فقط ويساويها، فيُبقي B دون موازنة.","","السهم 4 له طول المحصلة لكن زاويته مختلفة (أُبدلت الزاويتان)، فلا يعاكس المحصلة تمامًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-20T17:53:29.974Z"}'::jsonb),
('mcq', 4, 0, 'لأن الجسم متزن فإن $\boldsymbol{F}_1 + \boldsymbol{F}_2 + \boldsymbol{F}_3 = 0$، إذن $\boldsymbol{F}_2 + \boldsymbol{F}_3 = -\boldsymbol{F}_1$؛ أي إن $\boldsymbol{F}_1$ كانت القوة الموازنة للقوتين الأخريين، فمحصلتهما تساويها مقدارًا (20.0 N) وتعاكسها اتجاهًا (نحو الجنوب).', '["","محصلة القوتين الباقيتين تعاكس $\\boldsymbol{F}_1$ لأنها كانت توازنها، فلا يمكن أن تكون في اتجاهها.","بعد إزالة إحدى القوى لا يبقى الجسم متزنًا؛ فالقوتان الباقيتان كانت $\\boldsymbol{F}_1$ توازنهما.","المحصلة تساوي مقدار القوة المُزالة نفسه لا ضعفه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-20T17:53:29.974Z"}'::jsonb),
('mcq', 5, 3, 'القوة الموازنة تساوي المحصلة مقدارًا وتعاكسها اتجاهًا، أي $-\boldsymbol{R}$؛ وبإضافتها تصبح $\boldsymbol{A} + \boldsymbol{B} + (-\boldsymbol{R}) = 0$ ويتكوّن مثلث مغلق.', '["$\\boldsymbol{R}$ هي المحصلة نفسها؛ وإضافتها تضاعف أثر القوتين بدل أن تلغيه.","هذا فرق القوتين لا معكوس مجموعهما؛ ولا علاقة له بالاتزان.","هذا فرق القوتين أيضًا، وليس معكوس محصلتهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-20T17:53:29.974Z"}'::jsonb),
('mcq', 6, 3, 'القوة الموازنة تساوي المحصلة مقدارًا وتعاكسها اتجاهًا، ولأن الجسم متزن أصلًا فمحصلة القوى المؤثرة فيه صفر، إذن القوة الموازنة اللازمة صفر.', '["مجموع المقادير ليس المحصلة؛ والمحصلة هنا صفر فلا حاجة إلى قوة موازنة.","الجسم لا يحتاج إلى أي قوة إضافية؛ فأكبر القوى موزونة أصلًا بالقوى الأخرى.","الوزن موزون أصلًا بالقوى الأخرى؛ والموازنة تساوي الوزن فقط حين يكون الوزن القوة الوحيدة المؤثرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-20T17:53:29.974Z"}'::jsonb),
('mcq', 7, 0, 'المحصلة قوة واحدة لها تأثير القوى مجتمعة فتحل محلها، أما الموازنة فقوة إضافية تساوي المحصلة مقدارًا وتعاكسها اتجاهًا، تؤثر في الجسم نفسه فتصبح محصلة القوى كلها صفرًا ويتزن الجسم.', '["","المحصلة لا تُضاف إلى القوى بل تحل محلها؛ وإضافة الموازنة تُلغي المحصلة ولا تضاعفها.","الموازنة تعاكس المحصلة اتجاهًا وتؤثر في الجسم نفسه؛ ولا تؤثر في جسم آخر كزوجي التأثير المتبادل.","الموازنة تساوي مقدار المحصلة لا مجموع مقادير القوى، واتجاهها عكس المحصلة لا عكس أكبر قوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (64%)"}],"at":"2026-11-20T17:53:29.975Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) ارسم المتجه A بمقياس رسم مناسب، ثم انقل المتجه B دون تغيير طوله أو اتجاهه بحيث يبدأ ذيله عند رأس A. 2) ارسم المحصلة R من ذيل A إلى رأس B، وقِس طولها وزاويتها. 3) القوة الموازنة متجه طوله يساوي طول R واتجاهه عكس اتجاه R تمامًا ($-\boldsymbol{R}$)، وتؤثر في الجسم نفسه. وإذا رُسمت A وB والقوة الموازنة رأسًا لذيل تكوّن مثلثًا مغلقًا؛ لأن مجموعها صفر فيتزن الجسم.', '["ترتيب المتجهين رأسًا لذيل","رسم المحصلة من ذيل الأول إلى رأس الثاني","الموازنة: مقدار المحصلة نفسه وعكس اتجاهها","القوى الثلاث تكوّن مثلثًا مغلقًا"]'::jsonb, '[]'::jsonb, '[{"element":"نقل B ورسمه رأسًا لذيل","marks":1},{"element":"رسم المحصلة","marks":1},{"element":"وصف الموازنة","marks":1},{"element":"المثلث المغلق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الخطوات الثلاث مرتبة صحيحة مع وصف الموازنة والمثلث المغلق"},{"level":"2–3 درجات","description":"خطوتان صحيحتان أو نقص في وصف الاتجاه"},{"level":"درجة واحدة","description":"ذكر أن الموازنة تعاكس المحصلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم الموازنة في اتجاه المحصلة نفسه","تغيير اتجاه B عند نقله","رسم المحصلة من رأس A إلى ذيل B"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-20T17:53:29.975Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تؤثر في نقطة المنتصف ثلاث قوى: F عمودية على الحبل، وقوتا شد متساويتان $\boldsymbol{F}_{\text{T}}$ على امتداد نصفي الحبل نحو السيارة ونحو الشجرة، كلٌّ منهما تميل بزاوية $\theta$ عن الخط الأصلي. (ب) نقطة المنتصف متزنة، فمحصلة قوتي الشد هي القوة الموازنة لـ F: تساويها مقدارًا وتعاكسها اتجاهًا. مركّبتا الشد على امتداد الخط الأصلي متعاكستان فتلغي إحداهما الأخرى، ولا يبقى للموازنة إلا المركّبتان الصغيرتان $F_{\text{T}}\sin\theta$، فيكون $2F_{\text{T}}\sin\theta = F$، أي $F_{\text{T}} = \frac{F}{2\sin\theta}$. ولأن $\theta$ صغيرة فإن $\sin\theta$ صغير جدًا، فتكون $F_{\text{T}}$ أكبر كثيرًا من F، وهي القوة التي يؤثر بها الحبل في السيارة. (ج) $F_{\text{T}} = \frac{400}{2\sin 5.0^\circ} = 2.3 \times 10^3\ \text{N}$، أي نحو ستة أضعاف F تقريبًا.', '["ثلاث قوى على نقطة المنتصف: F وشدّان على امتداد الحبل","محصلة الشدّين هي القوة الموازنة لـ F","$2F_{\\text{T}}\\sin\\theta = F$ وصغر $\\theta$ يجعل الشد كبيرًا","$F_{\\text{T}} \\approx 2.3 \\times 10^3\\ \\text{N}$"]'::jsonb, '["نقطة المنتصف متزنة: $2F_{\\text{T}}\\sin\\theta - F = 0$","$F_{\\text{T}} = \\frac{F}{2\\sin\\theta}$","$F_{\\text{T}} = \\frac{400\\ \\text{N}}{2\\sin 5.0^\\circ} = 2294.7\\ \\text{N} \\approx 2.3 \\times 10^3\\ \\text{N}$"]'::jsonb, '[{"element":"مخطط الجسم الحر","marks":1},{"element":"ربط محصلة الشدّين بالقوة الموازنة","marks":1},{"element":"تفسير أثر صغر الزاوية","marks":1},{"element":"الحساب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مخطط صحيح وتفسير بالقوة الموازنة وحساب صحيح"},{"level":"2–3 درجات","description":"تفسير صحيح مع خطأ في الحساب أو نقص في المخطط"},{"level":"درجة واحدة","description":"مخطط جسم حر صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال $\\cos\\theta$ بدل $\\sin\\theta$","نسيان أن هناك نصفين للحبل (العامل 2)","الاعتقاد أن قوة الشد تساوي F"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-20T17:53:29.975Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نقطة التعليق متزنة، فمحصلة قوتي الشد في جزأي السلك هي القوة الموازنة لوزن اللوحة: رأسية إلى أعلى ومقدارها يساوي الوزن. المركّبتان الأفقيتان للشدين تلغي إحداهما الأخرى، والمركّبتان الرأسيتان تحملان الوزن: $2F_{\text{T}}\sin\alpha = F_g$، حيث $\alpha$ زاوية ميل السلك على الأفقي. كلما صغرت $\alpha$ صغر $\sin\alpha$ فكبر الشد. عند $\alpha = 15.0^\circ$: $F_{\text{T}} = \frac{50.0}{2\sin 15.0^\circ} = 96.6\ \text{N}$. عند $\alpha = 40.0^\circ$: $F_{\text{T}} = \frac{50.0}{2\sin 40.0^\circ} = 38.9\ \text{N}$. إذن الطريقة 2 (السلك المائل بشدة) أفضل؛ لأن الشد فيها أقل، فاحتمال انقطاع السلك أقل.', '["محصلة الشدين هي الموازنة للوزن","$2F_{\\text{T}}\\sin\\alpha = F_g$","الحسابان: 96.6 N و38.9 N","الحكم: الطريقة 2 أفضل"]'::jsonb, '["$F_{\\text{T}} = \\frac{F_g}{2\\sin\\alpha}$","$\\alpha = 15.0^\\circ$: $F_{\\text{T}} = \\frac{50.0}{2(0.259)} = 96.6\\ \\text{N}$","$\\alpha = 40.0^\\circ$: $F_{\\text{T}} = \\frac{50.0}{2(0.643)} = 38.9\\ \\text{N}$"]'::jsonb, '[{"element":"ربط محصلة الشدين بموازنة الوزن","marks":1},{"element":"العلاقة الرياضية","marks":1},{"element":"الحسابان","marks":1},{"element":"الحكم المعلّل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح معلل بالقوة الموازنة مع حسابين صحيحين"},{"level":"2–3 درجات","description":"حكم صحيح مع حساب واحد أو تعليل ناقص"},{"level":"درجة واحدة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد أن الشد يساوي نصف الوزن دائمًا مهما كانت الزاوية","استعمال $\\cos\\alpha$ مع أن الزاوية مقيسة من الأفقي","اختيار الطريقة 1 لأن السلك فيها أقصر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-20T17:53:29.975Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
