('mcq', 1, 'عند رسم متجهات جميع القوى المؤثرة في جسم متزن رأسًا لذيل، ما الشكل الذي تكوّنه؟', null, null, '["مضلعًا مغلقًا ينتهي رأس آخر متجه فيه عند ذيل أول متجه","خطًا مستقيمًا واحدًا يبدأ من ذيل أول متجه","مضلعًا مفتوحًا تمثل فجوته القوة المحصلة","مثلثًا قائم الزاوية مهما كان عدد القوى"]'::jsonb, 'تذكر', 'تذكر شرط', 'سهل', 'الكتاب ص 146 — الاتزان، الشكل 5-11'),
('mcq', 2, 'رُسمت متجهات القوى المؤثرة في أربعة أجسام رأسًا لذيل كما في المخططات المرقمة الآتية. أيّ المخططات يمثل جسمًا متزنًا؟', null, '[{"src":"qimg/phys1/c5l3-o03-polygons.svg","alt":"أربعة مخططات مرقمة لمتجهات قوى زرقاء. المخطط 1: متجه أفقي إلى اليمين، يليه متجه من رأسه إلى أعلى اليسار، يليه متجه إلى أسفل اليسار ينتهي قبل أن يصل إلى ذيل المتجه الأول بمسافة واضحة. المخطط 2: متجه أفقي إلى اليمين، يليه من رأسه متجه إلى أعلى اليسار، ومتجه ثالث يبدأ من ذيل المتجه الأول ويتجه إلى أعلى اليمين فيلتقي رأسه برأس المتجه الثاني. المخطط 3: أربعة متجهات كل منها يبدأ من رأس الذي قبله، ويعود رأس الرابع إلى ذيل الأول تمامًا مكوّنًا شكلًا رباعيًا. المخطط 4: ثلاثة متجهات متتالية رأسًا لذيل تصعد إلى أعلى اليمين، ولا يعود آخرها إلى نقطة البداية."}]'::jsonb, '["المخطط 2","المخطط 4","المخطط 1","المخطط 3"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 146 — الاتزان، الشكل 5-11'),
('mcq', 3, 'ما الشرط الجبري لاتزان جسم تؤثر فيه عدة قوى في بُعدين؟', null, null, '["أن يكون مجموع المركّبات x للقوى مساويًا لمجموع مركّباتها y","أن يكون مجموع المركّبات x صفرًا ومجموع المركّبات y صفرًا معًا","أن يكون مجموع المركّبات x للقوى صفرًا فقط","أن تكون مقادير القوى المؤثرة كلها متساوية"]'::jsonb, 'فهم', 'تذكر شرط', 'سهل', 'الكتاب ص 135، 146 — جمع المركّبات والاتزان'),
('mcq', 4, 'يبين الجدول الآتي المركّبتين x وy لثلاث قوى تؤثر في جسم. ما الحكم الصحيح على حالة الجسم؟', '{"headers":["القوة","المركّبة x (N)","المركّبة y (N)"],"rows":[["$\\boldsymbol{F}_1$","$12.0$","$5.0$"],["$\\boldsymbol{F}_2$","$-7.0$","$9.0$"],["$\\boldsymbol{F}_3$","$-5.0$","$-14.0$"]]}'::jsonb, null, '["غير متزن؛ لأن مقادير القوى الثلاث غير متساوية","متزن أفقيًا فقط؛ لأن مجموع المركّبات y لا يساوي صفرًا","متزن؛ لأن مجموع المركّبات x صفر ومجموع المركّبات y صفر","غير متزن؛ لأن القوى الثلاث ليست متعامدة بعضها على بعض"]'::jsonb, 'تطبيق', 'تحليل بيانات', 'متوسط', 'الكتاب ص 147 — مسألة تحفيز'),
('mcq', 5, 'يؤثر في جسم عدة قوى، فكان مجموع مركّباتها x صفرًا، ومجموع مركّباتها y يساوي $-6.0\ \text{N}$، علمًا بأن الاتجاه الموجب للمحور y إلى أعلى. ما وصف حالة الجسم؟', null, null, '["متزن؛ لأن مجموع المركّبات x يساوي صفرًا","غير متزن، ويتسارع في الاتجاه السالب للمحور y","غير متزن، ويتسارع في الاتجاه الموجب للمحور y","غير متزن، ويتسارع في اتجاه المحور x"]'::jsonb, 'تحليل', 'تحليل حالة', 'صعب', 'الكتاب ص 146، 151 — الاتزان وقانون نيوتن الثاني في محورين'),
('mcq', 6, 'تمثل المتجهات في الشكل الآتي أربع قوى تؤثر في جسم، رُسمت رأسًا لذيل. أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/phys1/c5l3-o03-closed4.svg","alt":"أربعة متجهات قوى زرقاء مرسومة رأسًا لذيل تكوّن شكلًا رباعيًا مغلقًا: F1 من الركن الأيسر السفلي إلى اليمين، ثم F2 من رأسه إلى أعلى اليمين، ثم F3 من رأسه إلى أعلى اليسار، ثم F4 من رأسه إلى أسفل اليسار فينتهي رأسها عند ذيل F1 تمامًا."}]'::jsonb, '["$\\boldsymbol{F}_4$ هي محصلة القوى الثلاث الأخرى","الجسم يتسارع في اتجاه $\\boldsymbol{F}_4$ لأنها آخر القوى","الجسم يتسارع في اتجاه $\\boldsymbol{F}_1$ لأنها أول القوى","$\\boldsymbol{F}_4$ هي القوة الموازنة للقوى الثلاث الأخرى"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 146 — الشكلان 5-11 و5-12'),
('mcq', 7, 'هل يمكن أن يتزن جسم تحت تأثير ثلاث قوى فقط مقاديرها 3.0 N و4.0 N و10.0 N؟', null, null, '["لا؛ لأن 10.0 N أكبر من مجموع القوتين الأخريين","نعم؛ إذا كانت القوتان 3.0 N و4.0 N متعامدتين","نعم؛ إذا وقعت القوى الثلاث على خط مستقيم واحد","لا؛ لأن ثلاث قوى فقط لا يتزن بها جسم أبدًا"]'::jsonb, 'تحليل', 'استدلال', 'صعب', 'الكتاب ص 146 — الشكل 5-11'),
