('mcq', 1, 0, 'المحصلة تُرسم من ذيل أول متجه إلى رأس آخر متجه، والجسم المتزن محصلته صفر؛ لذا ينتهي رأس آخر متجه عند ذيل الأول فيتكوّن مضلع مغلق (مثلث في حالة ثلاث قوى).', '["","المتجهات المؤثرة في اتجاهات مختلفة لا تقع على خط واحد عادة؛ والمطلوب أن يُغلق الشكل لا أن يستقيم.","وجود فجوة يعني أن المحصلة لا تساوي صفرًا، فالجسم غير متزن.","الشكل المغلق قد يكون أي مضلع، ولا يلزم أن يكون مثلثًا قائمًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-20T17:53:29.976Z"}'::jsonb),
('mcq', 2, 3, 'في المخطط 3 يبدأ كل متجه من رأس المتجه الذي قبله، وينتهي رأس آخر متجه عند ذيل الأول، فالمضلع مغلق والمحصلة صفر، والجسم متزن.', '["يبدو المخطط 2 مثلثًا، لكن المتجه الثالث يبدأ من ذيل الأول ويلتقي رأسه برأس الثاني؛ فهو في اتجاه المحصلة لا عكسها، والمجموع لا يساوي صفرًا.","المخطط 4 مفتوح؛ فرأس آخر متجه بعيد عن ذيل الأول، والمحصلة لا تساوي صفرًا.","في المخطط 1 فجوة بين رأس آخر متجه وذيل الأول، فالمحصلة لا تساوي صفرًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-20T17:53:29.976Z"}'::jsonb),
('mcq', 3, 1, 'يتزن الجسم عندما يكون مجموع المركّبات x صفرًا ومجموع المركّبات y صفرًا معًا؛ فالمحصلة صفر يعني أن مركّبتيها صفر معًا: $\sum F_x = 0$ و$\sum F_y = 0$؛ وتُجمع المركّبات في كل محور على حدة.', '["تساوي المجموعين لا يعني انعدامهما؛ فقد يساوي كلٌّ منهما 5 N مثلًا والمحصلة لا تساوي صفرًا.","","انعدام مجموع المركّبات x وحده يعني أن الجسم لا يتسارع أفقيًا فقط، وقد يتسارع في اتجاه y.","تساوي المقادير لا يضمن الاتزان؛ فالمهم أن يكون المجموع المتجهي صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-20T17:53:29.976Z"}'::jsonb),
('mcq', 4, 2, '$\sum F_x = 12.0 + (-7.0) + (-5.0) = 0$ و$\sum F_y = 5.0 + 9.0 + (-14.0) = 0$؛ فالجسم متزن لأن مجموع المركّبات x صفر ومجموع المركّبات y صفر، أي إن محصلة القوى صفر.', '["تساوي المقادير ليس شرطًا للاتزان؛ والشرط انعدام مجموع المركّبات في المحورين، وهو متحقق هنا.","مجموع المركّبات y يساوي صفرًا: $5.0 + 9.0 - 14.0 = 0$.","","التعامد ليس شرطًا؛ فالقوى غير المتعامدة تتزن إذا انعدم مجموع مركّباتها في المحورين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-20T17:53:29.976Z"}'::jsonb),
('mcq', 5, 1, 'الاتزان يتطلب $\sum F_x = 0$ و$\sum F_y = 0$ معًا، وهنا $\sum F_y = -6.0\ \text{N}$؛ فالمحصلة 6.0 N في الاتجاه السالب للمحور y، والجسم يتسارع في اتجاهها (إلى أسفل) وفق قانون نيوتن الثاني.', '["انعدام مجموع المركّبات x شرط غير كافٍ؛ فالمحصلة في اتجاه y لا تساوي صفرًا.","","الإشارة السالبة تعني أن المحصلة في الاتجاه السالب للمحور y، والتسارع في اتجاه المحصلة.","مجموع المركّبات x صفر، فلا تسارع في اتجاه x؛ والتسارع في اتجاه y فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-20T17:53:29.976Z"}'::jsonb),
('mcq', 6, 3, 'المضلع مغلق، فمجموع القوى الأربع صفر والجسم متزن: $\boldsymbol{F}_1 + \boldsymbol{F}_2 + \boldsymbol{F}_3 + \boldsymbol{F}_4 = 0$، إذن $\boldsymbol{F}_4 = -(\boldsymbol{F}_1 + \boldsymbol{F}_2 + \boldsymbol{F}_3)$؛ أي إنها تساوي محصلة الثلاث مقدارًا وتعاكسها اتجاهًا، فهي القوة الموازنة لها.', '["محصلة الثلاث تُرسم من ذيل $\\boldsymbol{F}_1$ إلى رأس $\\boldsymbol{F}_3$، أما $\\boldsymbol{F}_4$ فتتجه عكس ذلك؛ فهي معكوس المحصلة.","المضلع مغلق، فالمحصلة صفر والجسم لا يتسارع.","ترتيب رسم المتجهات لا يغير مجموعها، والمجموع هنا صفر فلا تسارع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-20T17:53:29.976Z"}'::jsonb),
('mcq', 7, 0, 'لكي يتزن الجسم يجب أن تُغلق متجهات القوى الثلاث مثلثًا، أي أن تساوي محصلة أي قوتين القوة الثالثة مقدارًا. أكبر محصلة ممكنة للقوتين 3.0 N و4.0 N هي 7.0 N (عندما تكونان في الاتجاه نفسه)، وهي أصغر من 10.0 N؛ أي إن 10.0 N أكبر من مجموع القوتين الأخريين، فلا يمكن أن تُغلق المتجهات مثلثًا، ولا يتزن الجسم.', '["","محصلة القوتين المتعامدتين 5.0 N فقط، وهي لا توازن 10.0 N.","على خط واحد تكون أكبر محصلة للقوتين 7.0 N، فلا توازن 10.0 N أيضًا.","ثلاث قوى قد يتزن بها الجسم إذا أغلقت متجهاتها مثلثًا؛ والمانع هنا مقاديرها لا عددها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-20T17:53:29.977Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الطريقة البيانية (بالرسم): تُرسم متجهات القوى بمقياس رسم واحد رأسًا لذيل (مع الحفاظ على مقدار كل متجه واتجاهه عند نقله)؛ فإذا انتهى رأس آخر متجه عند ذيل أول متجه وتكوّن مضلع مغلق كانت المحصلة صفرًا والجسم متزنًا. الطريقة الجبرية (بالمركّبات): تُحلل كل قوة إلى مركّبتين x وy، ثم تُجمع مركّبات x معًا ومركّبات y معًا؛ فإذا كان $\sum F_x = 0$ و$\sum F_y = 0$ معًا كان الجسم متزنًا.', '["الطريقة البيانية: رسم المتجهات رأسًا لذيل","الشرط البياني: مضلع مغلق","الطريقة الجبرية: تحليل القوى إلى مركّبات وجمعها","الشرط الجبري: $\\sum F_x = 0$ و$\\sum F_y = 0$ معًا"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الطريقة البيانية","marks":1},{"element":"شرطها","marks":1},{"element":"وصف الطريقة الجبرية","marks":1},{"element":"شرطها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الطريقتان موصوفتان مع شرط كل منهما"},{"level":"2–3 درجات","description":"طريقة كاملة والأخرى ناقصة"},{"level":"درجة واحدة","description":"ذكر إحدى الطريقتين دون شرطها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بانعدام مجموع المركّبات في محور واحد","جمع مقادير القوى بدل جمع مركّباتها","تغيير اتجاه المتجه عند نقله في الرسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-20T17:53:29.977Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المركّبات x: $50.0\cos 0^\circ + 50.0\cos 120^\circ + 50.0\cos 240^\circ = 50.0 - 25.0 - 25.0 = 0$. المركّبات y: $50.0\sin 0^\circ + 50.0\sin 120^\circ + 50.0\sin 240^\circ = 0 + 43.3 - 43.3 = 0$. بما أن $\sum F_x = 0$ و$\sum F_y = 0$ فالمحصلة صفر والجسم متزن. (ب) تكوّن المتجهات الثلاثة مثلثًا مغلقًا متساوي الأضلاع (طول كل ضلع يمثل 50.0 N)، فرأس المتجه الثالث يعود إلى ذيل الأول.', '["$\\sum F_x = 0$","$\\sum F_y = 0$","الاستنتاج: الجسم متزن","مثلث مغلق متساوي الأضلاع"]'::jsonb, '["$F_{1x} = 50.0$، $F_{2x} = 50.0\\cos 120^\\circ = -25.0$، $F_{3x} = 50.0\\cos 240^\\circ = -25.0$ (بوحدة N)","$\\sum F_x = 50.0 - 25.0 - 25.0 = 0$","$F_{1y} = 0$، $F_{2y} = 50.0\\sin 120^\\circ = 43.3$، $F_{3y} = 50.0\\sin 240^\\circ = -43.3$ (بوحدة N)","$\\sum F_y = 0$، إذن المحصلة صفر"]'::jsonb, '[{"element":"مجموع المركّبات x","marks":1},{"element":"مجموع المركّبات y","marks":1},{"element":"الاستنتاج","marks":1},{"element":"وصف الشكل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان واستنتاج ووصف المثلث المغلق"},{"level":"2–3 درجات","description":"حساب محور واحد صحيح أو خطأ في إشارة مركّبة"},{"level":"درجة واحدة","description":"وصف الشكل المغلق فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال الإشارة السالبة لـ $\\cos 120^\\circ$ أو $\\sin 240^\\circ$","جمع المقادير 150 N والقول إن الجسم غير متزن","التحقق من محور واحد فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-20T17:53:29.977Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المركّبات x: $40.0\cos 30.0^\circ - 40.0\cos 30.0^\circ + 0 = 34.6 - 34.6 = 0$؛ وهذا صحيح لكنه غير كافٍ. المركّبات y: $40.0\sin 30.0^\circ + 40.0\sin 30.0^\circ - 30.0 = 20.0 + 20.0 - 30.0 = +10.0\ \text{N}$. بما أن $\sum F_y \neq 0$ فالجسم غير متزن، وعبارة الطالب خاطئة؛ لأن الاتزان يتطلب انعدام مجموع المركّبات في المحورين معًا. (ب) المحصلة 10.0 N في الاتجاه الموجب للمحور y، فالجسم يتسارع إلى أعلى. ولكي يتزن يجب أن تصبح القوة الرأسية إلى أسفل 40.0 N بدل 30.0 N (أي إضافة 10.0 N إلى أسفل)، فيصبح $\sum F_y = 40.0 - 40.0 = 0$.', '["$\\sum F_x = 0$ صحيح لكنه غير كافٍ","$\\sum F_y = +10.0\\ \\text{N}$","الجسم غير متزن ويتسارع في اتجاه +y","التعديل: القوة الرأسية 40.0 N إلى أسفل"]'::jsonb, '["$\\sum F_x = 40.0\\cos 30.0^\\circ - 40.0\\cos 30.0^\\circ = 0$","$\\sum F_y = 2(40.0\\sin 30.0^\\circ) - 30.0 = 10.0\\ \\text{N}$","المحصلة 10.0 N في اتجاه +y","للاتزان: $F = 2(40.0\\sin 30.0^\\circ) = 40.0\\ \\text{N}$ إلى أسفل"]'::jsonb, '[{"element":"حساب المركّبات x","marks":1},{"element":"حساب المركّبات y","marks":1},{"element":"الحكم واتجاه التسارع","marks":1},{"element":"التعديل المقترح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح للمحورين وحكم معلل واتجاه التسارع وتعديل صحيح"},{"level":"2–3 درجات","description":"حساب المحورين مع نقص في التعديل أو اتجاه التسارع"},{"level":"درجة واحدة","description":"الحكم بعدم الاتزان دون حساب كافٍ"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال $\\cos 30.0^\\circ$ للمركّبة الرأسية","الاكتفاء بانعدام المركّبات الأفقية","تحديد اتجاه التسارع إلى أسفل لأن القوة الرأسية إلى أسفل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-20T17:53:29.977Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C5-L3-O03') and x.type = v.type and x.number = v.number
